Object.assign(window.TEM8_DICTIONARY, {"watt":{"media":{"uk":"media/uk/watt__gb_1.mp3","us":"media/us/watt__us_1.mp3"},"oxford":{"phon":"wɒt","pos":"noun","senses":[{"en":"a unit for measuring electrical power","cn":"瓦，瓦特（电功率单位）","ex":{"en":"a 60-watt light bulb","cn":"60 瓦的电灯泡"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"瓦，瓦特(电的功率单位)","en":"A watt is a unit of measurement of electrical power.","ex":{"en":"Use a 3 amp fuse for equipment up to 720 watts.","cn":"720 瓦以下的设备使用3安培的保险丝。"}}]},"examples":[{"en":"a 60-watt light bulb * 60","cn":"瓦的电灯泡"},{"en":"a 60-watt light bulb","cn":""}]},"water":{"media":{"uk":"media/uk/water__gb_1.mp3","us":"media/us/water__us_1.mp3"},"oxford":{"phon":"ˈwɔːtə(r)","pos":"noun","senses":[{"en":"a liquid without colour, smell or taste that falls as rain, is in lakes, rivers and seas, and is used for drinking, washing, etc.","cn":"水","g":"[uncountable]","ex":{"en":"a glass of water","cn":"一杯水"}},{"en":"an area of water, especially a lake, river, sea or ocean","cn":"大片的水；水域；（尤指）江，河，湖，海","g":"[uncountable]","ex":{"en":"We walked down to the water's edge.","cn":"我们步行到水边去。"}},{"en":"the surface of a mass of water","cn":"（一片）水面","g":"[uncountable]","ex":{"en":"The leaves floated on the water.","cn":"叶片漂浮在水面上。"}},{"en":"the water in a particular lake, river, sea or ocean","cn":"（某一江、河、湖、海的）水域","g":"[plural]","ex":{"en":"the grey waters of the River Clyde","cn":"克莱德河灰蒙蒙的河水"}},{"en":"an area of sea or ocean belonging to a particular country","cn":"（某个国家的）领海，海域","g":"[plural]","ex":{"en":"We were still in British waters.","cn":"我们仍在英国的领海上。"}},{"en":"used to describe a situation, usually one that is difficult, dangerous or not familiar","cn":"不明朗（或未知、困难、危险等）的局面","g":"[plural]","ex":{"en":"The conversation got into the murky waters of jealousy and relationships.","cn":"交谈进入到爱妒交织的复杂话题。"}},{"en":"to pour water on plants, etc.","cn":"给…浇水；灌溉","g":"[transitive]","ex":{"en":"to water the plants/garden","cn":"给花草／花园浇水"},"pos":"verb"},{"en":"to become full of tears","cn":"充满眼泪","g":"[intransitive]","ex":{"en":"The smoke made my eyes water.","cn":"烟熏得我直流眼泪。"},"pos":"verb"},{"en":"to produce saliva","cn":"流口水","g":"[intransitive]","ex":{"en":"The smells from the kitchen made our mouths water.","cn":"厨房里的香味馋得我们直流口水。"},"pos":"verb"},{"en":"to give water to an animal to drink","cn":"给…水喝；饮（动物）","g":"[transitive]","lab":"humorous","ex":{"en":"to water the horses","cn":"饮马"},"pos":"verb"},{"en":"to provide an area of land with water","cn":"流经；给（某地）供水","g":"[transitive, usually passive]","lab":"specialist","ex":{"en":"The valley is watered by a stream.","cn":"这山谷有一条小溪流过。"},"pos":"verb"},{"en":"to add water to an alcoholic drink","cn":"往（酒里）掺水；给…加水","g":"[transitive]","ex":{"en":"watered wine","cn":"掺了水的葡萄酒"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"水;雨水","en":"Water is a clear thin liquid that has no colour or taste when it is pure. It falls from clouds as rain and enters rivers and seas. All animals and people need water in order to live.","ex":{"en":"Get me a glass of water.","cn":"给我杯水。"}},{"pos":"N-PLURAL 复数名词","cn":"海域;(尤指)领海","en":"You use waters to refer to a large area of sea, especially the area of sea which is near to a country and which is regarded as belonging to it.","ex":{"en":"The ship will remain outside Chinese territorial waters.","cn":"这艘船将继续呆在中国领海之外。"}},{"pos":"N-PLURAL 复数名词","cn":"困境","en":"You sometimes use waters to refer to a situation which is very complex or difficult.","ex":{"en":"...the man brought in to guide him through troubled waters","cn":"被请来帮助他渡过难关的人"}},{"pos":"VERB 动词","cn":"给(植物)浇水","en":"If you water plants, you pour water over them in order to help them to grow.","ex":{"en":"He went out to water the plants.","cn":"他出去给植物浇水。"}},{"pos":"VERB 动词","cn":"流泪","en":"If your eyes water, tears build up in them because they are hurting or because you are upset.","ex":{"en":"His eyes watered from cigarette smoke.","cn":"他的眼睛被香烟熏得直流泪。"}},{"pos":"VERB 动词","cn":"流口水","en":"If you say that your mouth is watering, you mean that you can smell or see some nice food and you might mean that your mouth is producing a liquid.","ex":{"en":"...cookies to make your mouth water.","cn":"令人垂涎的饼干"}},{"pos":"PHR-ERG","cn":"（孕妇）羊水破裂;（医生或接生员）给（孕妇）破羊水","en":"When a pregnant woman's waters break, the fluid in her womb that surrounds the baby passes out of her body, showing that the baby is ready to be born. A doctor or midwife can break a woman's waters so that the birth can begin.","ex":{"en":"My waters broke at six in the morning and within four hours Jamie was born.","cn":"我是凌晨6点破水的，不到4个小时杰米就出生了。"}},{"pos":"PHRASE 短语","cn":"泼出之水;不可改变的既成事实;无法挽回的过去","en":"If you say that an event or incident is water under the bridge, you mean that it has happened and cannot now be changed, so there is no point in worrying about it any more.","ex":{"en":"He was relieved his time in jail was over and regarded it as water under the bridge.","cn":"他为服刑期满而感到如释重负，而且觉得既已无可更改，过去的就让它过去吧。"}},{"pos":"PHRASE 短语","cn":"陷入困境;处境尴尬","en":"If you are in deep water, you are in a difficult or awkward situation.","ex":{"en":"You certainly seem to be in deep water","cn":"你看起来无疑是陷入了困境。"}},{"pos":"PHRASE 短语","cn":"(论点或理论)符合逻辑，站得住脚，经得起考验","en":"If an argument or theory does not hold water, it does not seem to be reasonable or be in accordance with the facts.","ex":{"en":"This argument simply cannot hold water in Europe.","cn":"这个论点在欧洲根本就站不住脚。"}},{"pos":"PHRASE 短语","cn":"陷于困境;遇到麻烦","en":"If you are in hot water, you are in trouble.","ex":{"en":"The company has already been in hot water over high prices this year.","cn":"这家公司今年由于价格过高已经陷入困境。"}},{"pos":"PHRASE 短语","cn":"给(想法或建议)泼冷水","en":"If you pour cold water on an idea or suggestion, you show that you have a low opinion of it.","ex":{"en":"City economists pour cold water on the idea that the economic recovery has begun.","cn":"伦敦金融城的经济学家给经济开始复苏的说法泼了冷水。"}},{"pos":"PHRASE 短语","cn":"试探","en":"If you test the water or test the waters, you try to find out what reaction an action or idea will get before you do it or tell it to people.","ex":{"en":"You should be cautious when getting involved and test the water before committing yourself.","cn":"参与其中时一定要小心谨慎，表态之前最好试探一下。"}},{"pos":"","cn":"","en":"like water off a duck's back→see: ; to take to something like a duck to water→see: ; like a fish out of water→see: ; to keep your head above water→see: ; to pour oil on troubled waters→see: ;"},{"pos":"","cn":"","en":"相关词组：water down"}]},"examples":[{"en":"I can't tell my son what to do; it's water off a duck's back with him.","cn":"我无法告诉我儿子该做什么，他根本听不进去。"},{"en":"( humorous ) After a tour of the grounds, the guests were fed and watered.","cn":"客人们游览场地之后，给招待得酒足饭饱。"}]},"wallpaper":{"oxford":{"phon":"ˈwɔːlpeɪpə(r)","pos":"noun","senses":[{"en":"thick paper, often with a pattern on it, used for covering the walls and ceiling of a room","cn":"壁纸；墙纸","lab":"British English","ex":{"en":"wallpaper paste","cn":"贴壁纸用的糨糊"}},{"en":"the background pattern or picture that you choose to have on the screen of your computer, mobile phone, etc.","cn":"（计算机、手机等屏幕上的）壁纸，桌面背景","lab":"computing","ex":{"en":"You can download desktop wallpaper.","cn":"你可以下载桌面壁纸。"}},{"en":"to put wallpaper onto the walls of a room","cn":"往（屋里墙上）贴壁纸","pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"墙纸;壁纸","en":"Wallpaper is thick coloured or patterned paper that is used for covering and decorating the walls of rooms.","ex":{"en":"...the wallpaper in the bedroom.","cn":"卧室内的壁纸"}},{"pos":"VERB 动词","cn":"糊墙纸于","en":"If someone wallpapers a room, they cover the walls with wallpaper.","ex":{"en":"We were going to wallpaper that room anyway.","cn":"反正我们本来就打算在那间屋里贴墙纸的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"墙纸式作品(乏味浅薄、虽令人愉悦却不能引人关注的音乐、电视或艺术)","en":"If you describe music, television, or art as wallpaper, you are critical of it because there is nothing interesting or difficult to understand about it, so people find it pleasant but do not pay much attention to it.","ex":{"en":"...bland, wallpaper music.","cn":"乏味的墙纸式音乐"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(屏幕的)墙纸，壁纸","en":"Wallpaper is the background on a computer screen.","ex":{"en":"... pre-installed wallpaper images.","cn":"预设的壁纸图案"}}]},"media":{"uk":"media/uk/wallpaper__gb_1.mp3","us":"media/us/wallpaper__us_1.mp3"},"examples":[{"en":"wallpaper paste","cn":"贴壁纸用的糨糊"},{"en":"a roll of wallpaper","cn":"一卷壁纸"}]},"waking":{"media":{"uk":"media/uk/waking__gb_1.mp3","us":"media/us/waking__us_1.mp3"},"oxford":{"phon":"ˈweɪkɪŋ","pos":"noun","senses":[{"en":"the condition of not being asleep","cn":"清醒","ex":{"en":"the dreamlike state between waking and sleeping","cn":"似睡非睡梦境般的状态"}},{"en":"used to describe time when you are not asleep","cn":"醒着的；不眠的","ex":{"en":"She spends all her waking hours caring for her mother.","cn":"她不睡觉的时候都在照看母亲。"},"pos":"adjective"}]},"examples":[{"en":"She spends all her waking hours caring for her mother.","cn":"她不睡觉的时候都在照看母亲。"},{"en":"the dreamlike state between waking and sleeping","cn":"似睡非睡的梦境状态"}]},"walnuts":{"oxford":{"phon":"ˈwɔːlnʌt","pos":"noun","senses":[{"en":"the light brown nut of the walnut tree that has a rough surface and a hard round shell in two halves","cn":"核桃；胡桃"},{"en":"the tree on which walnuts grow","cn":"核桃树；胡桃树"}]},"media":{"img":["media/pic/nuts_comp.jpg","media/thumb/walnut.jpg"],"uk":"media/uk/walnut__gb_1.mp3","us":"media/us/walnut__us_1.mp3"}},"washable":{"media":{"uk":"media/uk/washable__gb_1.mp3","us":"media/us/washable__us_1.mp3"},"oxford":{"phon":"ˈwɒʃəbl","pos":"adjective","senses":[{"en":"that can be washed without being damaged","cn":"可洗的；耐洗的","ex":{"en":"machine washable (= that can be washed in a washing machine)","cn":"可机洗的"}},{"en":"that can be removed from something by washing it","cn":"可洗掉的；可洗净的","ex":{"en":"washable ink/paint/marker pens","cn":"可洗掉的墨水／油漆；可水洗记号笔"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可水洗的","en":"Washable clothes or materials can be washed in water without being damaged.","ex":{"en":"Choose washable curtains.","cn":"选择可水洗的窗帘。"}}]},"examples":[{"en":"machine washable (= that can be washed in a washing machine)","cn":"可用洗衣机洗的"},{"en":"The gloves are machine washable .","cn":"这副手套可以机洗。"}]},"wave":{"media":{"uk":"media/uk/wave__gb_1.mp3","us":"media/us/wave__us_1.mp3","img":["media/ldoce/img/wave.jpg"]},"oxford":{"phon":"weɪv","pos":"noun","senses":[{"en":"a raised line of water that moves across the surface of the sea, ocean, etc.","cn":"海浪；波浪；波涛","g":"[countable]","sc":"of water","ex":{"en":"Huge waves were breaking on the shore.","cn":"巨浪拍打着海岸。"}},{"en":"the form that some types of energy such as heat, sound, light, etc. take as they move","cn":"波；波状运动","g":"[countable]","sc":"of heat/sound/light","ex":{"en":"electromagnetic/gravity/ultrasonic waves","cn":"电磁波；重力波；超声波"}},{"en":"a movement of your arm and hand from side to side","cn":"挥臂；挥手；招手；摆手","g":"[countable]","sc":"movement of arm/hand/body","ex":{"en":"She declined the offer with a wave of her hand.","cn":"她摆了摆手谢绝了这一提议。"}},{"en":"a continuous movement that looks like a wave on the sea, made by a large group of people, especially people watching a sports game, when one person after another stands up, raises their arms, and then sits down again","cn":"人浪（尤指体育比赛中看台上的观众依次站起坐下而形成的波浪状场面）","g":"[singular]","lab":"North American English","sc":"movement of arm/hand/body"},{"en":"a sudden increase in a particular activity or feeling","cn":"汹涌的行动（或思想）态势；心潮；风潮","g":"[countable]","sc":"of activity/feeling","ex":{"en":"Insurgents launched a wave of attacks against the security forces.","cn":"叛乱者发起了针对安全部队的一波袭击。"}},{"en":"a large number of things or people suddenly appearing or arriving somewhere","cn":"突现，大量涌现，…潮","g":"[countable]","sc":"large number","ex":{"en":"Wave after wave of aircraft passed overhead.","cn":"一批又一批飞机从上空掠过。"}},{"en":"if a person’s hair has a wave or waves, it is not straight but slightly curly","cn":"拳曲；波浪","g":"[countable]","sc":"in hair"},{"en":"the sea","cn":"大海","g":"[plural]","lab":"literary","sc":"sea","ex":{"en":"life on the waves (= life at sea)","cn":"海上生活"}},{"en":"to move your hand or arm from side to side in the air in order to attract attention, say hello, etc.","cn":"挥手；招手；摆手；挥臂","g":"[intransitive, transitive]","sc":"move hand/arm","ex":{"en":"The people on the bus waved and we waved back.","cn":"公共汽车上的人挥手致意，我们也向他们挥手。"},"pos":"verb"},{"en":"to show where something is, show somebody where to go, etc. by moving your hand in a particular direction","cn":"挥手指引，挥手示意（方向）","g":"[intransitive, transitive]","sc":"move hand/arm","ex":{"en":"She waved vaguely in the direction of the house.","cn":"她含糊地朝房子的方向挥了挥手。"},"pos":"verb"},{"en":"to hold something in your hand and move it from side to side","cn":"挥舞，挥动（手中之物）","g":"[transitive]","sc":"move hand/arm","ex":{"en":"Crowds lined the route, waving flags and cheering.","cn":"人群沿路线排成行，挥舞着旗子欢呼。"},"pos":"verb"},{"en":"to move freely and gently, for example in the wind, while one end or side is held in position","cn":"（一端固定地）飘扬，飘动，摇晃，起伏","g":"[intransitive]","sc":"move freely","ex":{"en":"The flag waved in the breeze.","cn":"旗子在微风中飘扬。"},"pos":"verb"},{"en":"to be slightly curly","cn":"略呈波形；鬈曲","g":"[intransitive]","sc":"hair","ex":{"en":"His hair waves naturally.","cn":"他天生一头鬈发。"},"pos":"verb"},{"en":"to make somebody’s hair slightly curly","cn":"使…略呈波形；烫（发）","g":"[transitive]","sc":"hair","ex":{"en":"She's had her hair waved.","cn":"她烫发了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"挥(手)示意(或致意)","en":"If you wave or wave your hand, you move your hand from side to side in the air, usually in order to say hello or goodbye to someone.","ex":{"en":"Jessica caught sight of Lois and waved to her","cn":"杰茜卡看到了洛伊丝，就冲她挥手致意。"}},{"pos":"VERB 动词","cn":"挥手示意(方向);挥手指引","en":"If you wave someone away or wave them on, you make a movement with your hand to indicate that they should move in a particular direction.","ex":{"en":"Leshka waved him away with a show of irritation","cn":"廖什克恼火地挥手让他离开。"}},{"pos":"VERB 动词","cn":"挥舞","en":"If you wave something, you hold it up and move it rapidly from side to side.","ex":{"en":"Hospital staff were outside to welcome him, waving flags and applauding","cn":"医院的工作人员都在外面一边挥动旗子一边鼓掌欢迎他。"}},{"pos":"VERB 动词","cn":"飘动;摆动;起伏","en":"If something waves, it moves gently from side to side or up and down.","ex":{"en":"...grass and flowers waving in the wind.","cn":"随风摇曳的花草"}},{"pos":"N-COUNT 可数名词","cn":"波浪;(尤指)海浪","en":"A wave is a raised mass of water on the surface of water, especially the sea, which is caused by the wind or by tides making the surface of the water rise and fall.","ex":{"en":"...the sound of the waves breaking on the shore.","cn":"海浪拍岸的声音"}},{"pos":"N-COUNT 可数名词","cn":"(头发的)波浪卷，鬈曲","en":"If someone's hair has waves, it curves slightly instead of being straight."},{"pos":"N-COUNT 可数名词","cn":"冲击波","en":"A wave is a sudden increase in heat or energy that spreads out from an earthquake or explosion.","ex":{"en":"The shock waves of the earthquake were felt in Teheran","cn":"地震带来的冲击波在德黑兰也能感觉到。"}},{"pos":"N-COUNT 可数名词","cn":"(声、光、无线电等的)波","en":"Waves are the form in which things such as sound, light, and radio signals travel.","ex":{"en":"Sound waves, light waves, and radio waves have a certain frequency, or number of waves per second.","cn":"声波、光波或无线电波等都有特定的频率，或者说是每秒的波数。"}},{"pos":"N-COUNT 可数名词","cn":"(情绪的)突发，高涨","en":"If you refer to a wave of a particular feeling, you mean that it increases quickly and becomes very intense, and then often decreases again.","ex":{"en":"She felt a wave of panic, but forced herself to leave the room calmly","cn":"她感到一阵恐慌，但还是强作镇定地离开了房间。"}},{"pos":"N-COUNT 可数名词","cn":"(活动、行为的)爆发，浪潮","en":"A wave is a sudden increase in a particular activity or type of behaviour, especially an undesirable or unpleasant one.","ex":{"en":"...the current wave of violence.","cn":"目前的暴力浪潮"}},{"pos":"N-COUNT 可数名词","cn":"(突然涌向某处的)人流","en":"A wave is a sudden increase in the number of people moving somewhere.","ex":{"en":"A wave of immigrants is washing over Western Europe.","cn":"移民潮正席卷西欧。"}},{"pos":"N-COUNT 可数名词","cn":"人群形成的波浪;人浪","en":"If a crowd of people do the wave, each person in the crowd stands up and puts their arms in the air after the person to one side of them, then sits down again, creating a continuous wave-like motion through the crowd."},{"pos":"","cn":"","en":"相关词组：wave aside wave down"}]},"examples":[{"en":"‘I'm rich!’ she exclaimed, waving the money under his nose. “","cn":"我发财了！”她在他的鼻子下面舞动着钞票喊道。"},{"en":"The people on the bus waved and we waved back.","cn":"公共汽车上的人挥手致意，我们也向他们挥手。"}]},"ware":{"media":{"uk":"media/uk/ware__gb_1.mp3","us":"media/us/ware__us_1.mp3"},"oxford":{"phon":"weə(r)","pos":"noun","senses":[{"en":"objects made of the material or in the way or place mentioned","cn":"用某材料（或以某方式、在某地）制造的物品","g":"[uncountable]","ex":{"en":"ceramic ware","cn":"陶瓷制品"}},{"en":"objects used for the purpose or in the room mentioned","cn":"作…用的器皿；…室的物品","g":"[uncountable]","ex":{"en":"bathroom ware","cn":"浴室用品"}},{"en":"things that somebody is selling, especially in the street or at a market","cn":"（尤指小商贩在大街上或市场里出售的）物品","g":"[plural]","lab":"old-fashioned","ex":{"en":"He travelled from town to town selling his wares.","cn":"他走乡串镇出售自己的货品。"}}]},"examples":[{"en":"He travelled from town to town selling his wares.","cn":"他走乡串镇出售自己的货品。"},{"en":"a collection of local ware","cn":"一批当地器皿"}]},"waterproof":{"oxford":{"phon":"ˈwɔːtəpruːf","pos":"adjective","senses":[{"en":"that does not let water through or that cannot be damaged by water","cn":"不透水的；防水的；耐水的","ex":{"en":"waterproof clothing","cn":"防水衣"}},{"en":"a piece of clothing made from material that does not let water through","cn":"防水衣物；雨衣","ex":{"en":"You’ll need waterproofs (= a waterproof jacket and trousers).","cn":"你会用得着雨衣裤的。"},"pos":"noun"},{"en":"to make something waterproof","cn":"使不透水；使防水","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"防水的;不透水的","en":"Something which is waterproof does not let water pass through it.","ex":{"en":"Take waterproof clothing — Orkney weather is unpredictable","cn":"带上防水的衣服吧——奥克尼的天气可是变幻莫测的。"}},{"pos":"N-COUNT 可数名词","cn":"防水服;雨衣","en":"Waterproofs are items of clothing which do not let water in.","ex":{"en":"For staying dry you'll want nice lightweight waterproofs to wear over your leathers.","cn":"为了不被淋湿，你需要在皮衣的外面套上一件轻便的防水服。"}},{"pos":"VERB 动词","cn":"对…进行防水处理","en":"If something is waterproofed, it is treated so that water cannot pass through it or damage it.","ex":{"en":"The whole boat has been totally waterproofed","cn":"整条船全部经过防水处理。"}}]},"media":{"uk":"media/uk/waterproof__gb_1.mp3","us":"media/us/waterproof__us_1.mp3"},"examples":[{"en":"You'll need waterproofs (= a waterproof jacket and trousers/pants).","cn":"你会用得着雨衣裤的。"},{"en":"a waterproof camera","cn":"防水照相机"}]},"warfare":{"media":{"uk":"media/uk/warfare__gb_1.mp3","us":"media/us/warfare__us_1.mp3"},"oxford":{"phon":"ˈwɔːfeə(r)","pos":"noun","senses":[{"en":"the activity of fighting a war, especially using particular weapons or methods","cn":"战；作战；战争","ex":{"en":"air/naval/guerrilla warfare","cn":"空战；海战；游击战"}},{"en":"the activity of competing in an aggressive way with another group, company, etc.","cn":"（群体、公司等之间的）斗争，竞争，冲突","ex":{"en":"gang warfare","cn":"帮派火拼"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"作战;战争","en":"Warfare is the activity of fighting a war.","ex":{"en":"...the threat of chemical warfare.","cn":"化学战的威胁"}},{"pos":"N-UNCOUNT 不可数名词","cn":"打架;冲突;斗争","en":"Warfare is sometimes used to refer to any violent struggle or conflict.","ex":{"en":"Much of the violence is related to drugs and gang warfare","cn":"大多数暴力事件都与吸毒和群殴有关。"}}]},"examples":[{"en":"The debate soon degenerated into open warfare.","cn":"争论很快恶化，演变成了公开的论战。"},{"en":"air/naval/guerrilla, etc. warfare","cn":"空战、海战、游击战等"}]},"warranty":{"media":{"uk":"media/uk/warranty__gb_1.mp3","us":"media/us/warranty__us_1.mp3"},"oxford":{"phon":"ˈwɒrənti","pos":"noun","senses":[{"en":"a written agreement in which a company selling something promises to repair or replace it if there is a problem within a particular period of time","cn":"（商品）保用单","ex":{"en":"The television comes with a full two-year warranty.","cn":"这台电视机有整两年的保修期。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"保修单","en":"A warranty is a written promise by a company that, if you find a fault in something they have sold you within a certain time, they will repair it or replace it free of charge.","ex":{"en":"...a twelve month warranty","cn":"为期12个月的保修单"}}]},"examples":[{"en":"The television comes with a full two-year warranty.","cn":"这台电视机有整两年的保修期。"},{"en":"Is the car still under warranty?","cn":"这辆汽车仍在保修期内吗？"}]},"wasteful":{"oxford":{"phon":"ˈweɪstfl","pos":"adjective","senses":[{"en":"using more of something than is necessary; not saving or keeping something that could be used","cn":"浪费的；挥霍的","ex":{"en":"The whole process is wasteful and inefficient.","cn":"整个程序既浪费又低效。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"浪费的;耗费的;挥霍的","en":"Action that is wasteful uses too much of something valuable such as time, money, or energy.","ex":{"en":"This kind of training is ineffective, and wasteful of scarce resources","cn":"这种训练没有效率，而且是对稀缺资源的浪费。"}}]},"media":{"uk":"media/uk/wasteful__gb_1.mp3","us":"media/us/wasteful__us_1.mp3"},"examples":[{"en":"The whole process is wasteful and inefficient.","cn":"整个程序既浪费又效率低。"},{"en":"an engine that is wasteful of fuel","cn":"费燃料的发动机"}]},"want":{"media":{"uk":"media/uk/want__gb_1.mp3","us":"media/us/want__us_1.mp3"},"oxford":{"phon":"wɒnt","pos":"verb","senses":[{"en":"to have a desire or a wish for something/somebody","cn":"要；想要；希望","lab":"informal","sc":"wish","ex":{"en":"Do you want some more tea?","cn":"你再要点儿茶吗？"}},{"en":"to need something","cn":"需要","lab":"informal","sc":"need","ex":{"en":"We'll want more furniture for the new office.","cn":"我们的新办公室需要添些家具。"}},{"en":"to need somebody to be present in the place or for the purpose mentioned","cn":"需要…在场","g":"[usually passive]","sc":"need","ex":{"en":"She's wanted immediately in the director's office.","cn":"她得马上到主任办公室去。"}},{"en":"used to give advice to somebody, meaning ‘should’ or ‘ought to’","cn":"（用于提出建议）应该","lab":"informal","sc":"should/ought to","ex":{"en":"If possible, you want to avoid alcohol.","cn":"你应尽可能避免饮酒。"}},{"en":"to feel sexual desire for somebody","cn":"对…有性欲","sc":"feel sexual desire","ex":{"en":"‘I want you so much,’ she whispered in his ear.","cn":"“我很想要你。”她在他耳边低声说道。"}},{"en":"to lack something","cn":"缺少；缺乏","lab":"formal","sc":"lack","ex":{"en":"He doesn't want courage.","cn":"他有的是勇气。"}},{"en":"something that you need or want","cn":"需要的东西；想望的东西","g":"[countable, usually plural]","sc":"something you need","ex":{"en":"She spent her life pandering to the wants of her children.","cn":"她一生都在设法满足子女的需要。"},"pos":"noun"},{"en":"a situation in which there is not enough of something","cn":"缺少；缺乏；不足","g":"[uncountable, singular]","lab":"formal","sc":"lack","ex":{"en":"There is a want of adequate medical facilities.","cn":"缺乏足够的医疗设施。"},"pos":"noun"},{"en":"the state of being poor, not having food, etc.","cn":"贫穷；贫困；匮乏","g":"[uncountable]","lab":"formal","sc":"being poor","ex":{"en":"Visitors to the slums were clearly shocked to see so many families living in want.","cn":"到访贫民窟的人看到有这么多的家庭生活在贫苦之中显然震惊不已。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"需要;想要","en":"If you want something, you feel a desire or a need for it.","ex":{"en":"I want a drink","cn":"我想喝点什么。"}},{"pos":"VERB 动词","cn":"打算","en":"You can say that you want to say something to indicate that you are about to say it.","ex":{"en":"I want to say how really delighted I am that you're having a baby","cn":"我想说你怀孕了我有多高兴。"}},{"pos":"VERB 动词","cn":"(用于疑问句中表示提议或邀请)想要，需要","en":"You use want in questions as a way of making an offer or inviting someone to do something.","ex":{"en":"Do you want another cup of coffee?","cn":"你想再来一杯咖啡吗？"}},{"pos":"VERB 动词","cn":"必须;需要","en":"If you say to someone that you want something, or ask them if they want to do it, you are firmly telling them what you want or what you want them to do.","ex":{"en":"I want an explanation from you, Jeremy","cn":"杰里米，我需要你解释一下。"}},{"pos":"VERB 动词","cn":"需要(做);该(做)","en":"If you say that something wants doing, you think that it needs to be done.","ex":{"en":"The windows wanted cleaning","cn":"窗户该擦了。"}},{"pos":"VERB 动词","cn":"(用于建议)应该做","en":"If you tell someone that they want to do a particular thing, you are advising them to do it.","ex":{"en":"You want to be very careful not to have a man like Crevecoeur for an enemy","cn":"你应当格外小心，别与克雷弗克这样的人为敌。"}},{"pos":"VERB 动词","cn":"通缉;缉拿","en":"If someone is wanted by the police, the police are searching for them because they are thought to have committed a crime.","ex":{"en":"They were wanted by the police","cn":"他们被警方通缉。"}},{"pos":"VERB 动词","cn":"想与…发生性关系","en":"If you want someone, you have a great desire to have sex with them.","ex":{"en":"Come on, darling. I want you.","cn":"亲爱的，过来。我想要你。"}},{"pos":"VERB 动词","cn":"照料，爱护(小孩)","en":"If a child is wanted, its mother or another person loves it and is willing to look after it.","ex":{"en":"Children should be wanted and planned","cn":"应当好好照看孩子，并为他们规划一生。"}},{"pos":"VERB 动词","cn":"想要;要","en":"If someone wants you in a particular place or role, they desire you to be in that place or role.","ex":{"en":"Albie wants you in his office","cn":"阿尔比要你去他办公室。"}},{"pos":"N-SING 单数名词","cn":"缺乏;缺少","en":"A want of something is a lack of it.","ex":{"en":"...a want of manners and charm","cn":"缺乏风度和魅力"}},{"pos":"N-UNCOUNT 不可数名词","cn":"极度贫困","en":"Want is the state of being extremely poor.","ex":{"en":"He said they were fighting for freedom of speech, freedom of worship, and freedom from want.","cn":"他说他们在为言论自由而战，为信仰自由而战，为远离贫困而战。"}},{"pos":"N-PLURAL 复数名词","cn":"想要的东西","en":"Your wants are the things that you want.","ex":{"en":"She couldn't lift a spoon without a servant anticipating her wants and getting it for her","cn":"要是没有仆人事先想她所想并为她准备妥当，她连汤匙也举不起来。"}},{"pos":"PHRASE 短语","cn":"由于缺少;由于没有","en":"If you do something for want of something else, you do it because the other thing is not available or not possible.","ex":{"en":"Many of them had gone into teaching for want of anything better to do","cn":"因为没有更好的工作，他们当中很多人做了教师。"}},{"pos":"PHRASE 短语","cn":"如果你想;如果你愿意","en":"You say if you want when you are making or agreeing to an offer or suggestion in a casual way.","ex":{"en":"Mary says you're welcome to stay the night if you want","cn":"玛丽说如果你愿意，可以在这儿呆一宿。"}},{"pos":"PHRASE 短语","cn":"我并不想…;我无意…","en":"People sometimes say 'I don't want to be rude', for example, or 'without wanting to be rude' as a way of apologizing or warning you when they are going to say something which might upset, annoy, or worry you.","ex":{"en":"'I don't want to appear big-headed,' explains Loubet, 'but I would say there is a 95% chance of success.'","cn":"“我并不想显得自大，”劳伯特解释说，“但我有95%的成功把握。”"}},{"pos":"PHRASE 短语","cn":"(粗暴或生气地问)你想干什么？","en":"If you say to someone 'what do you want?', you are asking them in a rather rude or angry way why they have come to the place where you are or why they want to speak to you.","ex":{"en":"'What do you want!' she whispered savagely. 'Get out.'","cn":"“你想干什么！”她粗野地低语道，“滚开。”"}},{"pos":"","cn":"","en":"相关词组：want out"}]},"examples":[{"en":"We call our music ‘postmodern’ for the want of a better word.","cn":"由于没有更合适的词来表达，我们把我们的音乐称作“后现代风格”。"},{"en":"Visitors to the slums were clearly shocked to see so many families living in want.","cn":"到过贫民窟的人看到有这么多的家庭生活在贫苦之中显然震惊不已。"}]},"warm":{"media":{"uk":"media/uk/warm__gb_1.mp3","us":"media/us/warm__us_1.mp3"},"oxford":{"phon":"wɔːm","pos":"adjective","senses":[{"en":"at a fairly high temperature in a way that is pleasant, rather than being hot or cold","cn":"温暖的；暖和的","sc":"at pleasant temperature","ex":{"en":"warm weather/temperatures/air","cn":"温暖的天气／温度／空气"}},{"en":"keeping you warm or staying warm in cold weather","cn":"保暖的；保温的","sc":"clothes/buildings","ex":{"en":"warm clothing/clothes","cn":"暖和的衣服"}},{"en":"showing enthusiasm, friendship or love","cn":"温情的；热心的；友好的","sc":"friendly","ex":{"en":"Her smile was warm and friendly.","cn":"她的微笑热情而友好。"}},{"en":"containing red, orange or yellow, which creates a pleasant, comfortable and relaxed feeling or atmosphere","cn":"暖色调的","sc":"colours","ex":{"en":"The room was decorated in warm shades of red and orange.","cn":"这房间是用红和橙这些暖色调装饰的。"}},{"en":"used to say that somebody has almost guessed the answer to something or that they have almost found somebody/something that has been hidden","cn":"即将猜中；接近答案；即将找到","g":"[not before noun]","sc":"in game","ex":{"en":"Keep guessing—you're getting warmer.","cn":"接着猜，你离答案越来越近了。"}},{"en":"to make something/somebody warm or warmer; to become warm or warmer","cn":"（使）温暖，变暖和","g":"[transitive, intransitive]","sc":"make/become warm","ex":{"en":"Come in and warm yourself by the fire.","cn":"进来烤火暖和暖和吧。"},"pos":"verb"},{"en":"to become more friendly, loving, etc.; to make somebody feel or become more friendly, loving, etc.","cn":"（使）变得更友好，变得更温情","g":"[intransitive, transitive]","sc":"become friendly","ex":{"en":"His voice suddenly warmed.","cn":"他的语气突然变得友善起来。"},"pos":"verb"},{"en":"a place where the temperature is warm","cn":"暖和的地方","sc":"place","ex":{"en":"Come inside into the warm.","cn":"进来暖和暖和。"},"pos":"noun"},{"en":"in a way that makes you feel warm","cn":"使人暖和地；温暖地","ex":{"en":"Wrap up warm before you go outside!","cn":"穿得暖和些再出去！"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"温暖的;暖和的","en":"Something that is warm has some heat but not enough to be hot. →see usage note at:","ex":{"en":"Wheat is grown in places which have cold winters and warm, dry summers","cn":"小麦适宜在冬季寒冷而夏季温暖干燥的地方生长。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣物或毯子)保暖的，保温的","en":"Warm clothes and blankets are made of a material such as wool which protects you from the cold.","ex":{"en":"They have been forced to sleep in the open without food or warm clothing","cn":"他们被迫风餐露宿，吃不饱也穿不暖。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"暖色调的;有暖感的","en":"Warm colours have red or yellow in them rather than blue or green, and make you feel comfortable and relaxed.","ex":{"en":"We hope the colour gives the house a warm and inviting feel","cn":"我们希望这种颜色能让房子给人一种暖意融融、宾至如归的感觉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热心的;热情的;热烈的","en":"A warm person is friendly and shows a lot of affection or enthusiasm in their behaviour.","ex":{"en":"She was a warm and loving mother","cn":"她是一位热情慈爱的母亲。"}},{"pos":"VERB 动词","cn":"使暖和;让…取暖","en":"If you warm a part of your body or if something hot warms it, it stops feeling cold and starts to feel hotter.","ex":{"en":"The sun had come out to warm his back","cn":"太阳出来了，把他后背晒得暖洋洋的。"}},{"pos":"VERB 动词","cn":"(对某人)产生好感;(对想法)开始感兴趣","en":"If you warm to a person or an idea, you become fonder of the person or more interested in the idea.","ex":{"en":"Those who got to know him better warmed to his openness and honesty","cn":"那些对他日渐了解的人被他的坦率和真诚所打动。"}},{"pos":"","cn":"","en":"相关词组：warm down warm up"}]},"examples":[{"en":"They were warmly dressed in coats and scarves.","cn":"他们身着大衣，围着围巾，穿得暖暖和和。"},{"en":"The room was decorated in warm shades of red and orange.","cn":"这房间是用红和橙的这些暖色调装饰的。"}]},"wanted":{"media":{"uk":"media/uk/wanted__gb_1.mp3","us":"media/us/wanted__us_1.mp3"},"oxford":{"phon":"ˈwɒntɪd","pos":"adjective","senses":[{"en":"being searched for by the police, in connection with a crime","cn":"受通缉的","ex":{"en":"He is wanted by the police in connection with the deaths of two people.","cn":"他因与两条人命有关而受到警方通缉。"}}]},"examples":[{"en":"He is wanted by the police in connection with the deaths of two people.","cn":"他因与两条人命有关而受到警方通缉。"},{"en":"Italy's most wanted man","cn":"意大利头号通缉犯"}]},"walnut":{"media":{"img":["media/pic/nuts_comp.jpg","media/thumb/walnut.jpg"],"uk":"media/uk/walnut__gb_1.mp3","us":"media/us/walnut__us_1.mp3"},"oxford":{"phon":"ˈwɔːlnʌt","pos":"noun","senses":[{"en":"the light-brown nut of the walnut tree that has a rough surface and a hard round shell in two halves","cn":"核桃；胡桃","g":"[countable]"},{"en":"the tree on which walnuts grow","cn":"核桃树；胡桃树","g":"[countable]"},{"en":"the brown wood of the walnut tree, used in making furniture","cn":"核桃木；胡桃木","g":"[uncountable]","ex":{"en":"a walnut writing desk","cn":"胡桃木写字台"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"胡桃;核桃","en":"Walnuts are edible nuts which have a wrinkled shape and a hard round shell that is light brown in colour.","ex":{"en":"...chopped walnuts.","cn":"碎核桃仁"}},{"pos":"N-VAR 可变名词","cn":"胡桃树;核桃树","en":"A walnut tree or a walnut is a tree on which walnuts grow.","ex":{"en":"The stool comes in several sizes in walnut or mahogany.","cn":"凳子有几种尺寸，材质分胡桃木和红木两种。"}}]},"examples":[{"en":"coffee and walnut cake","cn":"咖啡核桃蛋糕"}]},"wall":{"media":{"uk":"media/uk/wall__gb_1.mp3","us":"media/us/wall__us_1.mp3"},"oxford":{"phon":"wɔːl","pos":"noun","senses":[{"en":"a long, solid structure that rises straight up from the ground, made of stone, brick or concrete, that surrounds, divides or protects an area of land","cn":"城墙；围墙；隔墙","ex":{"en":"to build a wall","cn":"垒墙"}},{"en":"any of the sides of a building or room","cn":"墙；壁；墙壁","lab":"British English","ex":{"en":"She leaned against the wall.","cn":"她倚靠着墙。"}},{"en":"something that forms a barrier or stops you from making progress","cn":"屏障；隔阂；壁垒","ex":{"en":"The boat struck a solid wall of water.","cn":"船撞上一道水幕。"}},{"en":"the outer layer of something hollow such as an organ of the body or a cell of an animal or a plant","cn":"（身体器官或动植物细胞等的）外壁","ex":{"en":"the abdominal wall","cn":"腹壁"}},{"en":"a space on a social media website where you can share messages, photos, etc. with other users","cn":"分享墙（社交媒体网站分享信息、照片等的版块）","ex":{"en":"She posted a pink baby romper on her Facebook wall, announcing they were expecting a girl.","cn":"她在 Facebook 墙上发布了一件粉色婴儿连身衣，宣布他们即将生下一个女孩。"}},{"en":"to surround an area, a town, etc. with a wall or walls","cn":"用墙把…围住","ex":{"en":"a walled city","cn":"有城墙的城市"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"墙;墙壁","en":"A wall is one of the vertical sides of a building or room.","ex":{"en":"Kathryn leaned against the wall of the church","cn":"凯瑟琳倚靠在教堂的墙上。"}},{"pos":"N-COUNT 可数名词","cn":"(石或砖砌成的)围墙，隔墙","en":"A wall is a long narrow vertical structure made of stone or brick that surrounds or divides an area of land.","ex":{"en":"He sat on the wall in the sun","cn":"他坐在墙上晒太阳。"}},{"pos":"N-COUNT 可数名词","cn":"(中空物体的)壁，内壁","en":"The wall of something that is hollow is its side.","ex":{"en":"He ran his fingers along the inside walls of the box.","cn":"他用手指摸了摸盒子的内壁。"}},{"pos":"N-COUNT 可数名词","cn":"屏障;堆成墙的大量物品","en":"A wall of something is a large amount of it forming a high vertical barrier.","ex":{"en":"She gazed at the wall of books","cn":"她目不转睛地盯着书墙。"}},{"pos":"N-COUNT 可数名词","cn":"障碍;隔阂;壁垒","en":"You can describe something as a wall of a particular kind when it acts as a barrier and prevents people from understanding something.","ex":{"en":"The police say they met the usual wall of silence","cn":"警方称他们像往常一样碰了壁，没人吭气。"}},{"pos":"PHRASE 短语","cn":"碰壁;徒劳","en":"If you say that you are banging your head against a wall, you are emphasizing that you are frustrated because someone is stopping you from making progress in something.","ex":{"en":"I appealed for help but felt I was always banging my head against a wall","cn":"我寻求帮助，却发现自己处处碰壁。"}},{"pos":"PHRASE 短语","cn":"处于困境（或绝境);走投无路","en":"If you have your back to the wall, you are in a very difficult situation and can see no way out of it.","ex":{"en":"Their threat to hire replacement workers has the union with its back to the wall.","cn":"他们威胁说要雇用替工，这使工会陷入了困境。"}},{"pos":"PHRASE 短语","cn":"(感到)十分沮丧（或紧张、焦虑）","en":"If you say that you are climbing the walls, you are emphasizing that you feel very frustrated, nervous, or anxious.","ex":{"en":"Sitting at home would only have had him climbing the walls with frustration.","cn":"呆在家里只会让他沮丧得抓狂。"}},{"pos":"PHRASE 短语","cn":"把…逼得发疯；逼得…受不了","en":"If you say that something or someone is driving you up the wall, you are emphasizing that they annoy and irritate you.","ex":{"en":"The heat is driving me up the wall","cn":"炎热快把我逼疯了。"}},{"pos":"PHRASE 短语","cn":"破产;(生意)失败","en":"If a person or company goes to the wall, they lose all their money and their business fails.","ex":{"en":"Even quite big companies are going to the wall these days.","cn":"现如今甚至有些大公司也濒临破产。"}},{"pos":"","cn":"","en":"fly on the wall→see: ; the writing is on the wall→see: ;"},{"pos":"","cn":"","en":"相关词组：wall in wall off wall up"}]},"examples":[{"en":"I'm going to paint the walls white and the ceiling pink.","cn":"我打算把墙壁刷成白色，把天花板刷成粉红色。"},{"en":"The investigators were confronted by a wall of silence.","cn":"调查人员碰了壁，问谁谁都默不作声。"}]},"wanton":{"media":{"uk":"media/uk/wanton__gb_1.mp3","us":"media/us/wanton__us_1.mp3"},"oxford":{"phon":"ˈwɒntən","pos":"adjective","senses":[{"en":"causing harm or damage deliberately and for no acceptable reason","cn":"恶意的；不怀好意的；恣意的","g":"[usually before noun]","ex":{"en":"wanton destruction","cn":"肆意破坏"}},{"en":"behaving in a way that is thought to be immoral; thought to have many sexual partners","cn":"淫荡的；淫乱的；水性杨花的","lab":"old-fashioned, disapproving，，"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有意伤害的;肆无忌惮的；恶意的","en":"A wanton action deliberately causes harm, damage, or waste without having any reason to.","ex":{"en":"...this unnecessary and wanton destruction of our environment","cn":"对我们环境毫无必要的肆意破坏"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(女人)放荡的，淫乱的","en":"If someone describes a woman as wanton, they disapprove of her because she clearly enjoys sex or has sex with a lot of men.","ex":{"en":"...the idea that only wanton women have sexual passions.","cn":"认为只有放荡女人才有性激情的观念"}}]},"examples":[{"en":"a wanton disregard for human life","cn":"全然不顾人的死活"},{"en":"wanton destruction","cn":"肆意破坏"}]},"watts":{"oxford":{"phon":"wɒt","pos":"noun","senses":[{"en":"a unit for measuring electrical power","cn":"瓦，瓦特（电功率单位）"}]},"media":{"uk":"media/uk/watt__gb_1.mp3","us":"media/us/watt__us_1.mp3"}},"warm-hearted":{"oxford":{"phon":"ˌwɔːm ˈhɑːtɪd","pos":"adjective","senses":[{"en":"kind and friendly","cn":"善良诚恳的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热心的;热情的","en":"A warm-hearted person is friendly and affectionate."}]},"media":{"uk":"media/uk/warm_hearted_1_gb_1.mp3","us":"media/us/warm_hearted_1_us_1.mp3"},"examples":[{"en":"a warm-hearted landlady","cn":"热心的女房东"}]},"wastewater":{"media":{"uk":"media/uk/wastewater__gb_1.mp3","us":"media/us/wastewater__us_1.mp3"},"oxford":{"phon":"ˈweɪstwɔːtə(r)","pos":"noun","senses":[{"en":"used water that contains waste substances from homes, factories and farms","cn":"废水","ex":{"en":"municipal water and wastewater systems","cn":"市政用水和废水系统"}}]},"examples":[{"en":"municipal water and wastewater systems","cn":"市政用水和废水系统"},{"en":"a wastewater treatment plant","cn":"废水处理厂"}]},"warned":{"oxford":{"phon":"wɔːn","pos":"verb","senses":[{"en":"to tell sb about sth, especially sth dangerous or unpleasant that is likely to happen, so that they can avoid it","cn":"提醒注意（可能发生的事）；使警惕"},{"en":"to strongly advise sb to do or not to do sth in order to avoid danger or punishment","cn":"劝告（使有所防备）；警告；告诫"}]}},"wasn't":{"media":{"uk":"media/uk/wasn_t_1_gb_1.mp3","us":"media/us/wasn_t_1_us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"（was not 的常用口语形式）","en":"Wasn't is the usual spoken form of 'was not'."}]},"examples":[{"en":"Jason wasn’t at the party.","cn":""}]},"waterfall":{"oxford":{"phon":"ˈwɔːtəfɔːl","pos":"noun","senses":[{"en":"a place where a stream or river falls from a high place, for example over a cliff or rock","cn":"瀑布","ex":{"en":"She watched the magnificent waterfall cascade down the mountainside.","cn":"她看着壮观的瀑布从山坡上倾泻而下。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"瀑布","en":"A waterfall is a place where water flows over the edge of a steep, high cliff in hills or mountains, and falls into a pool below.","ex":{"en":"...Angel Falls, the world's highest waterfall.","cn":"安赫尔瀑布，世界上最高的瀑布"}}]},"media":{"uk":"media/uk/waterfall__gb_1.mp3","us":"media/us/waterfall__us_1.mp3"}},"way":{"media":{"uk":"media/uk/way__gb_1.mp3","us":"media/us/way__us_1.mp3"},"oxford":{"phon":"weɪ","pos":"noun","senses":[{"en":"a method, style or manner of doing something","cn":"方法；手段；途径；方式","g":"[countable]","lab":"informal, disapproving，，","sc":"method/style","ex":{"en":"I prefer to do things the easy way.","cn":"我做事喜欢简单。"}},{"en":"a particular manner or style of behaviour","cn":"作风；风度；样子","g":"[countable]","sc":"behaviour","ex":{"en":"They grinned at her in a friendly way.","cn":"他们友好地对她咧嘴笑了笑。"}},{"en":"the typical way of behaving and living of a particular group of people","cn":"（群体的）行为方式，生活方式，习俗","g":"[plural]","sc":"behaviour","ex":{"en":"After ten years I'm used to the strange British ways.","cn":"十年之后，我习惯了英国人的奇异习俗。"}},{"en":"a route or road that you take in order to reach a place","cn":"路线；路；道路","g":"[countable, usually singular]","sc":"route/road","ex":{"en":"to ask somebody the way","cn":"向某人问路"}},{"en":"the route along which somebody/something is moving; the route that somebody/something would take if there was nothing stopping them/it","cn":"行进路线；通路","g":"[countable, usually singular]","lab":"figurative","sc":"route/road","ex":{"en":"Get out of my way! I'm in a hurry.","cn":"让开！我有急事。"}},{"en":"a road, path or street for travelling along","cn":"路；小径；街道","g":"[countable]","sc":"route/road","ex":{"en":"There's a way across the fields.","cn":"有一条路穿过田地。"}},{"en":"used in the names of streets","cn":"（用于街道名称）路，道，街","sc":"route/road","ex":{"en":"106 Headley Way","cn":"黑德利路 106 号"}},{"en":"a particular direction; in a particular direction","cn":"某方向；往某方向","g":"[countable, usually singular]","lab":"figurative","sc":"direction","ex":{"en":"Which way did they go?","cn":"他们往哪边去了？"}},{"en":"a means of going into or leaving a place, such as a door or gate","cn":"出入通道；门口","g":"[countable, usually singular]","sc":"for entering/leaving","ex":{"en":"the way in/out","cn":"入口；出口"}},{"en":"a distance or period of time between two points","cn":"（两点之间的）距离，时间段","g":"[singular]","lab":"also North American English, informal，，","sc":"distance/time","ex":{"en":"A little way up on the left is the Museum of Modern Art.","cn":"前面不远左手边就是现代艺术博物馆。"}},{"en":"an area, a part of a country, etc.","cn":"地区；地带","g":"[singular]","lab":"informal","sc":"area","ex":{"en":"I think he lives somewhere over Greenwich way.","cn":"我想他住在格林尼治那一带。"}},{"en":"a particular aspect of something","cn":"方面","g":"[countable]","sc":"aspect","ex":{"en":"I have changed in every way.","cn":"我已经完完全全变了。"}},{"en":"a particular condition or state","cn":"情况；状态","g":"[singular]","sc":"condition/state","ex":{"en":"The economy's in a bad way.","cn":"经济状况很糟。"}},{"en":"very far; by a large amount","cn":"很远；大量","ex":{"en":"She finished the race way ahead of the other runners.","cn":"她遥遥领先于其他选手跑到终点。"},"pos":"adverb"},{"en":"very","cn":"非常；极其","lab":"informal, especially North American English，，","ex":{"en":"Things just got way difficult.","cn":"事情变得太困难了。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方法;手段","en":"If you refer to a way of doing something, you are referring to how you can do it, for example the action you can take or the method you can use to achieve it.","ex":{"en":"Freezing isn't a bad way of preserving food","cn":"冷冻不失为一种保存食物的好方法。"}},{"pos":"N-COUNT 可数名词","cn":"方式;作风","en":"If you talk about the way someone does something, you are talking about the qualities their action has.","ex":{"en":"She smiled in a friendly way","cn":"她友好地笑了笑。"}},{"pos":"N-COUNT 可数名词","cn":"形式","en":"If a general statement or description is true in a particular way, this is the form of it that is true in a particular case.","ex":{"en":"Computerized reservation systems help airline profits in several ways","cn":"电子订票系统通过多种方式帮助航空公司获利。"}},{"pos":"N-COUNT 可数名词","cn":"(某个)方面;(某)点","en":"You use way in expressions such as in some ways ,in many ways, and in every way to indicate the degree or extent to which a statement is true.","ex":{"en":"In some ways, the official opening is a formality","cn":"从某些方面来说，正式的开幕仪式只不过是走个形式。"}},{"pos":"N-PLURAL 复数名词","cn":"习惯;习俗;行为方式","en":"The ways of a particular person or group of people are their customs or their usual behaviour.","ex":{"en":"He denounces people who urge him to alter his ways","cn":"他指责那些督促他改变习惯的人。"}},{"pos":"N-SING 单数名词","cn":"惯常的行为;作风","en":"If you refer to someone's way, you are referring to their usual or preferred type of behaviour.","ex":{"en":"She is now divorced and, in her usual resourceful way, has started her own business","cn":"如今她离了婚。一贯足智多谋的她已开始自己创业。"}},{"pos":"N-COUNT 可数名词","cn":"看法;角度","en":"You use way to refer to one particular opinion or interpretation of something, when others are possible.","ex":{"en":"I suppose that's one way of looking at it","cn":"我想那是其中的一种看法。"}},{"pos":"N-COUNT 可数名词","cn":"可能的后果;可能作出的决定","en":"You use way when mentioning one of a number of possible, alternative results or decisions.","ex":{"en":"There is no indication which way the vote could go","cn":"没有迹象表明投票结果会怎样。"}},{"pos":"N-SING 单数名词","cn":"观点;态度","en":"The way you feel about something is your attitude to it or your opinion about it.","ex":{"en":"I'm terribly sorry — I had no idea you felt that way.","cn":"我非常抱歉——没有想到你是那样想的。"}},{"pos":"N-SING 单数名词","cn":"情况;状态","en":"If you mention the way that something happens, you are mentioning the fact that it happens.","ex":{"en":"I hate the way he manipulates people","cn":"我讨厌他摆布别人。"}},{"pos":"N-SING 单数名词","cn":"行进;前进;进程","en":"You use way in expressions such as push your way ,work your way, or eat your way, followed by a prepositional phrase or adverb, in order to indicate movement, progress, or force as well as the action described by the verb.","ex":{"en":"She thrust her way into the crowd","cn":"她挤进了人群。"}},{"pos":"N-COUNT 可数名词","cn":"路线;路径","en":"The way somewhere consists of the different places that you go through or the route that you take in order to get there.","ex":{"en":"Does anybody know the way to the bathroom?","cn":"有谁知道洗手间在哪里吗？"}},{"pos":"N-SING 单数名词","cn":"方向","en":"If you go or look a particular way, you go or look in that direction.","ex":{"en":"As he strode into the kitchen, he passed Pop coming the other way","cn":"他大步走进厨房，与迎面而来的爸爸擦身而过。"}},{"pos":"N-SING 单数名词","cn":"行进方向","en":"You can refer to the direction you are travelling in as your way .","ex":{"en":"It's not very far out of his way","cn":"就在他走的路上不远处。"}},{"pos":"N-SING 单数名词","cn":"(正确的)路径，道路","en":"If you lose your way, you take a wrong or unfamiliar route, so that you do not know how to get to the place that you want to go to. If you find your way, you manage to get to the place that you want to go to.","ex":{"en":"The men lost their way in a sandstorm and crossed the border by mistake","cn":"那些人在沙尘暴中迷了路，不小心穿越了边境。"}},{"pos":"N-COUNT 可数名词","cn":"生活道路","en":"You talk about people going their different ways in order to say that their lives develop differently and they have less contact with each other.","ex":{"en":"It wasn't until we each went our separate ways that I began to learn how to do things for myself","cn":"直到大家各奔东西，我才开始学着自力更生。"}},{"pos":"N-SING 单数名词","cn":"获得;收到","en":"If something comes your way, you get it or receive it.","ex":{"en":"Take advantage of the opportunities coming your way in a couple of months","cn":"把握住这几个月之内你可能获得的机会。"}},{"pos":"N-SING 单数名词","cn":"行进路线；通路","en":"If someone or something is in the way, they prevent you from moving forward or seeing clearly.","ex":{"en":"'You're standing in the way,' she said. 'Would you mind moving aside'","cn":"“你挡着道了，”她说，“麻烦你让一下。”"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于道路名）…路","en":"Way is used in the names of some roads, and also in the names of some long paths for walkers in the countryside.","ex":{"en":"Silvertown Way, was that the road?","cn":"锡尔弗敦路，是这条路么？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（某人居住地的）周边；特定的地区","en":"You can use way to refer to the area near where someone lives or near a specified place.","ex":{"en":"If you speak standard English anywhere round our way, people tend to view you with suspicion.","cn":"如果你在我们这里说标准英语，大家就会对你产生怀疑。"}},{"pos":"N-SING 单数名词","cn":"位置;摆放","en":"You use way in expressions such as the right way up and the other way around to refer to one of two or more possible positions or arrangements that something can have.","ex":{"en":"The flag was held the wrong way up by some spectators","cn":"一些观众把旗子拿倒了。"}},{"pos":"ADV 副词","cn":"远远地;大大地;非常","en":"You can use way to emphasize, for example, that something is a great distance away or is very much below or above a particular level or amount.","ex":{"en":"Way down in the valley to the west is the town of Freiburg","cn":"从这里往西远远的山谷中是弗赖堡镇。"}},{"pos":"N-PLURAL 复数名词","cn":"(分成的)部分","en":"If you split something a number of ways, you divide it into a number of different parts or quantities, usually fairly equal in size.","ex":{"en":"The region was split three ways, between Greece, Serbia and Bulgaria","cn":"这一地区被希腊、塞尔维亚和保加利亚分成了3部分。"}},{"pos":"N-SING 单数名词","cn":"路程;距离","en":"Way is used in expressions such as a long way ,a little way, and quite a way, to say how far away something is or how far you have travelled.","ex":{"en":"Some of them live in places quite a long way from here","cn":"他们中有些人住的地方离这里很远。"}},{"pos":"N-SING 单数名词","cn":"(时间的)距离","en":"Way is used in expressions such as a long way ,a little way, and quite a way, to say how far away in time something is.","ex":{"en":"Success is still a long way off","cn":"离成功还远着呢。"}},{"pos":"N-SING 单数名词","cn":"(表示动作完成的程度)全部/多半/一半","en":"You use way in expressions such as all the way ,most of the way and half the way to refer to the extent to which an action has been completed.","ex":{"en":"He had unscrewed the caps most of the way","cn":"他已经快把螺丝帽拧下来了。"}},{"pos":"PHRASE 短语","cn":"在街对面","en":"If something is across the way, it is nearby on the opposite side of a road or area.","ex":{"en":"...the big gabled house across the way.","cn":"街对面那座带三角屋顶的大房子"}},{"pos":"PHRASE 短语","cn":"(强调距离)一路","en":"You use all the way to emphasize how long a distance is.","ex":{"en":"He had to walk all the way home","cn":"他不得不一路步行回家。"}},{"pos":"PHRASE 短语","cn":"自始至终;一直","en":"You can use all the way to emphasize that your remark applies to every part of a situation, activity, or period of time.","ex":{"en":"Having started a revolution we must go all the way","cn":"既然已经发动了革命，我们就一定要进行到底。"}},{"pos":"PHRASE 短语","cn":"事情就是这样","en":"You can use as is the way to say that a particular situation or example of behaviour is typical and you would not expect it to be different.","ex":{"en":"As is the way with these gatherings, the declarations were largely drafted before the delegations arrived.","cn":"就像通常的这种集会一样，宣言内容在代表团到达之前就差不多拟好了。"}},{"pos":"PHRASE 短语","cn":"病得很重;很不健康","en":"If you say that someone is in a bad way, you mean that they are very ill or unhealthy.","ex":{"en":"He's in a bad way, but able to talk.","cn":"他病得很重，但还能说话。"}},{"pos":"PHRASE 短语","cn":"大规模地；大肆地","en":"If you say that something exists, happens, or develops in a big way, you are emphasizing its great extent or importance.","ex":{"en":"The man who took over a few weeks later has also helped further her career in a big way","cn":"几周后上台的那个人也帮助她把事业推进了一大步。"}},{"pos":"PHRASE 短语","cn":"二者不能兼得","en":"If someone says that you can't have it both ways, they are telling you that you have to choose between two things and cannot do or have them both.","ex":{"en":"Countries cannot have it both ways: the cost of a cleaner environment may sometimes be fewer jobs in dirty industries","cn":"各国不可能两全其美：环境更清洁的代价有时可能就是污染企业就业岗位的减少。"}},{"pos":"PHRASE 短语","cn":"顺便地;附带说一句","en":"You say by the way when you add something to what you are saying, especially something that you have just thought of.","ex":{"en":"The name Latifah, by the way, means 'delicate'","cn":"顺便说一句，Latifah 这个名字意思是“娇嫩”。"}},{"pos":"PREP-PHRASE 短语介词","cn":"作为…；以求…","en":"You use by way of when you are explaining the purpose of something that you have said or are about to say. For example, if you say something by way of an introduction, you say it as an introduction.","ex":{"en":"By way of contrast, Manchester United will travel slightly more than 1,200 miles","cn":"相比而言，曼联队的行程将略多于1,200英里。"}},{"pos":"PREP-PHRASE 短语介词","cn":"采用…方法；通过","en":"If you do something by way of a particular method, you use that method to do it.","ex":{"en":"I teach psychology by way of a range of traditional lectures, practicals and tutorials.","cn":"我采用传统授课与实践和指导相结合的方式教授心理学。"}},{"pos":"PREP-PHRASE 短语介词","cn":"经由；取道","en":"If you go somewhere by way of a particular place, you go through that place in order to get to where you want.","ex":{"en":"The path goes under the river by way of the tunnel.","cn":"这条通道经隧道从河下经过。"}},{"pos":"PHRASE 短语","cn":"(彻底地)改变","en":"If someone changes their ways or mends their ways, they permanently improve their behaviour or their way of doing something.","ex":{"en":"What can be done to encourage convicted offenders to change their ways?","cn":"怎样才能激励这些罪犯洗心革面呢？"}},{"pos":"PHRASE 短语","cn":"排除障碍;扫清道路","en":"If you clear the way ,open the way, or prepare the way for something, you create an opportunity for it to happen.","ex":{"en":"The talks are meant to clear the way for formal negotiations on a new constitution","cn":"会谈旨在为新宪法的正式商讨扫清道路。"}},{"pos":"PHRASE 短语","cn":"(采取)最容易的办法，最省事的做法(以回避困难或尴尬处境)","en":"If you say that someone takes the easy way out, you disapprove of them because they do what is easiest for them in a difficult situation, rather than dealing with it properly.","ex":{"en":"As soon as things got difficult he took the easy way out","cn":"事情刚变得有点棘手他就急忙脱身。"}},{"pos":"PHRASE 短语","cn":"(两种情况中)不论发生哪一种情况","en":"You use either way in order to introduce a statement which is true in each of the two possible or alternative cases that you have just mentioned.","ex":{"en":"The sea may rise or the land may fall; either way the sand dunes will be gone in a short time.","cn":"可能会出现海平面上升或陆地下沉:不论发生哪种情况，沙丘都会在短时间内消失。"}},{"pos":"PHRASE 短语","cn":"出路;未来发展之路","en":"If you say that a particular type of action or development is the way forward, you approve of it because it is likely to lead to success.","ex":{"en":"...people who genuinely believe that anarchy is the way forward","cn":"真的相信无政府主义才是未来出路的人"}},{"pos":"PHRASE 短语","cn":"想怎样就怎样;随心所欲","en":"If someone gets their way or has their way, nobody stops them doing what they want to do. You can also say that someone gets their own way or has their own way .","ex":{"en":"She is very good at using her charm to get her way.","cn":"她非常善于利用自己的魅力随心所欲。"}},{"pos":"PHRASE 短语","cn":"被…替代","en":"If one thing gives way to another, the first thing is replaced by the second.","ex":{"en":"First he had been numb. Then the numbness gave way to anger","cn":"起初他只是麻木，接着转为了愤怒。"}},{"pos":"PHRASE 短语","cn":"断裂; 倒塌","en":"If an object that is supporting something gives way, it breaks or collapses, so that it can no longer support that thing.","ex":{"en":"The hook in the ceiling had given way and the lamp had fallen blazing on to the table.","cn":"天花板上的钩子断了，灯落下来砸到桌子上燃起了火。"}},{"pos":"PHRASE 短语","cn":"向…让步;向…妥协","en":"If you give way to someone or something that you have been resisting, you stop resisting and allow yourself to be persuaded or controlled by them.","ex":{"en":"It seems the President has given way to pressure from the hardliners","cn":"总统似乎已迫于强硬派的压力而妥协了。"}},{"pos":"PHRASE 短语","cn":"让路;让其他人(或车辆)先行","en":"If a moving person, a vehicle, or its driver gives way, they slow down or stop in order to allow other people or vehicles to pass in front of them.","ex":{"en":"Give way to traffic coming from the left.","cn":"让从左边来的车先行。"}},{"pos":"PHRASE 短语","cn":"有…习惯","en":"If you say that someone or something has a way of doing a particular thing, you mean that they often do it.","ex":{"en":"Bosses have a way of always finding out about such things.","cn":"老板总喜欢把这类事情搞清楚。"}},{"pos":"PHRASE 短语","cn":"善于与(某人或某事物)打交道","en":"If you say hat a person has a way with something or someone, you mean that that person seems to have a natural skill or instinct for dealing with them.","ex":{"en":"Constance doesn't have a way with words like you do","cn":"康斯坦丝没有你这么健谈。"}},{"pos":"PHRASE 短语","cn":"随你的便","en":"If you say have it your way or have it your own way, you are telling someone in an annoyed way that you will agree with or accept their suggestion even though you do not think they are right.","ex":{"en":"All right then, have it your way. Be like that.","cn":"那好吧，随你的便。就那样吧。"}},{"pos":"PHRASE 短语","cn":"决不;一点也不","en":"You use in no way or not in any way to emphasize that a statement is not at all true.","ex":{"en":"In no way am I going to adopt any of his methods","cn":"我绝对不会采纳他的任何方法。"}},{"pos":"PHRASE 短语","cn":"(用于缓和语气)在某种程度上，在某些方面","en":"If you say that something is true in a way, you mean that although it is not completely true, it is true to a limited extent or in certain respects. You use in a way to reduce the force of a statement.","ex":{"en":"In a way, I suppose I'm frightened of failing","cn":"我想我有点惧怕失败。"}},{"pos":"PHRASE 短语","cn":"小规模地","en":"If you say that someone does something in a small way, you mean that although they do not do very much, their actions are useful or important.","ex":{"en":"...demonstrations against corruption, which began in a small way last week","cn":"上周开始的小规模的反腐示威游行"}},{"pos":"PHRASE 短语","cn":"妨碍;碍事","en":"If you say that someone gets in the way or is in the way, you are annoyed because their presence or their actions stop you doing something properly.","ex":{"en":"'We wouldn't get in the way,' Suzanne promised. 'We'd just stand quietly in a corner.'","cn":"“我们不会妨碍你的，”苏珊娜保证道，“我们就在角落里安安静静地站着。”"}},{"pos":"PHRASE 短语","cn":"阻碍;妨碍","en":"To get in the way of something means to make it difficult for it to happen, continue, or be appreciated properly.","ex":{"en":"She had a job which never got in the way of her leisure interests.","cn":"她有一份从来不会影响她的业余爱好的工作。"}},{"pos":"PHRASE 短语","cn":"对…完全熟悉;通晓","en":"If you know your way around a particular subject, system, or job, or if you know your way about it, you know all the procedures and facts about it.","ex":{"en":"He knows his way around the intricate maze of European law","cn":"他通晓错综复杂的欧洲律法。"}},{"pos":"PHRASE 短语","cn":"赚钱容易；轻轻松松赚大钱","en":"If you say that someone is laughing all the way to the bank, you mean that they are making a lot of money very easily.","ex":{"en":"The lucrative contract with television means that England's wealthy football clubs will now be laughing all the way to the bank.","cn":"与电视台签订的这项大合同会让富有的英格兰足球俱乐部财源滚滚。"}},{"pos":"PHRASE 短语","cn":"带路;领路","en":"If you lead the way along a particular route, you go along it in front of someone in order to show them where to go.","ex":{"en":"She grabbed his suitcase and led the way.","cn":"她拿过他的箱子在前面带路。"}},{"pos":"PHRASE 短语","cn":"领先;走在前沿","en":"If a person or group leads the way in a particular activity, they are the first person or group to do it or they make the most new developments in it.","ex":{"en":"Sony has also led the way in shrinking the size of compact-disc players.","cn":"索尼公司在缩小CD播放机的体积方面也处于领先地位。"}},{"pos":"PHRASE 短语","cn":"取得巨大进展;取得很多成就","en":"If you say that someone or something has come a long way, you mean that they have developed, progressed, or become very successful.","ex":{"en":"He has come a long way since the days he could only afford one meal a day.","cn":"那种一天只吃得起一顿饭的日子已经离他很遥远了。"}},{"pos":"PHRASE 短语","cn":"(表示强调)远远地，大大地","en":"You can use by a long way to emphasize that something is, for example, much better, worse, or bigger than any other thing of that kind.","ex":{"en":"It was, by a long way, the worst meeting I have ever attended","cn":"这绝对是我参加过的最差劲的会议。"}},{"pos":"PHRASE 短语","cn":"离…还差得远","en":"If you say that something is a long way from being true, you are emphasizing that it is definitely not true.","ex":{"en":"She is a long way from being the richest person in Britain","cn":"比起英国首富，她还差得远呢。"}},{"pos":"PHRASE 短语","cn":"(对…)大有帮助;(对…)有很大作用","en":"If you say that something goes a long way towards doing a particular thing, you mean that it is an important factor in achieving that thing.","ex":{"en":"Although by no means a cure, it goes a long way towards making the patient's life more tolerable.","cn":"虽然并不能根治，但它对减轻病人的痛苦大有帮助。"}},{"pos":"PHRASE 短语","cn":"迷失;茫然;不知所措","en":"If you say that someone has lost their way, you are criticizing them because they do not have any good ideas any more, or seem to have become unsure about what to do.","ex":{"en":"Why has the White House lost its way on tax and budget policy?","cn":"为什么白宫在税收和预算政策问题上束手无策呢？"}},{"pos":"PHRASE 短语","cn":"去;前往","en":"When you make your way somewhere, you walk or travel there.","ex":{"en":"He made his way to the marketplace, as he had been instructed to do","cn":"他按照指示去了市场。"}},{"pos":"PHRASE 短语","cn":"被…取代;让位于","en":"If one person or thing makes way for another, the first is replaced by the second.","ex":{"en":"He said he was prepared to make way for younger people in the party","cn":"他说他已准备好让位于党内的年轻一代。"}},{"pos":"PHRASE 短语","cn":"没有可能","en":"If you say there's no way that something will happen, you are emphasizing that you think it will definitely not happen.","ex":{"en":"There was absolutely no way that we were going to be able to retrieve it.","cn":"我们绝对不可能把它找回来。"}},{"pos":"PHRASE 短语","cn":"没门儿;不可能","en":"You can say no way as an emphatic way of saying no.","ex":{"en":"Mike, no way am I playing cards with you for money","cn":"迈克，我是决不会和你玩牌赌钱的。"}},{"pos":"PHRASE 短语","cn":"关于;就…而言","en":"You use in the way of or by way of in order to specify the kind of thing you are talking about.","ex":{"en":"Latvia is a country without much in the way of natural resources","cn":"拉脱维亚并不是一个自然资源丰富的国家。"}},{"pos":"PHRASE 短语","cn":"在路上;在途中","en":"If you are on your way, you have started your journey somewhere.","ex":{"en":"He has been allowed to leave the country and is on his way to Britain","cn":"他已获准离境，正在去往英国的路上。"}},{"pos":"PHRASE 短语","cn":"继续行程","en":"If you go on your way, you continue with your journey.","ex":{"en":"She picked up her bag, and went on her way.","cn":"她提起包继续赶路。"}},{"pos":"PHRASE 短语","cn":"在过程中","en":"If something happens on the way or along the way, it happens during the course of a particular event or process.","ex":{"en":"You may have to learn a few new skills along the way.","cn":"在这个过程中你可能还得新学几招。"}},{"pos":"PHRASE 短语","cn":"(大)有进展","en":"If you are on your way or well on your way to something, you have made so much progress that you are almost certain to achieve that thing.","ex":{"en":"I am now out of hospital and well on the way to recovery.","cn":"我现在已经出院，快康复了。"}},{"pos":"PHRASE 短语","cn":"即将到来","en":"If something is on the way, it will arrive soon.","ex":{"en":"The forecasters say more snow is on the way","cn":"天气预报员说不久还将有降雪。"}},{"pos":"PHRASE 短语","cn":"(表示某事一定发生)无论如何，不管怎样","en":"You can use one way or another or one way or the other when you want to say that something definitely happens, but without giving any details about how it happens.","ex":{"en":"...those who had entered Germany one way or another during the war","cn":"那些在战争时期以各种方式进入德国的人"}},{"pos":"PHRASE 短语","cn":"(指之前提到的两个可能的决定或结论)无论哪个","en":"You use one way or the other or one way or another to refer to two possible decisions or conclusions that have previously been mentioned, without stating which one is reached or preferred.","ex":{"en":"We've got to make our decision one way or the other","cn":"不是这样就是那样，我们无论如何都得作出决定了。"}},{"pos":"PHRASE 短语","cn":"不止一种意义;不单是这样","en":"You say in more ways than one to indicate that what you have said is intended to have more than one meaning.","ex":{"en":"These local elections may prove a turning point in more ways than one.","cn":"这些地方选举从许多方面来说都是一个转折点。"}},{"pos":"PHRASE 短语","cn":"相反地;倒过来","en":"You use the other way around or the other way round to refer to the opposite of what you have just said.","ex":{"en":"You'd think you were the one who did me the favor, and not the other way around.","cn":"应该是你帮了我，而不是我帮了你。"}},{"pos":"PHRASE 短语","cn":"行将消失;行将被取代","en":"If something or someone is on the way out or on their way out, they are likely to disappear or to be replaced very soon.","ex":{"en":"There are encouraging signs that cold war attitudes are on the way out","cn":"有令人欣慰的迹象表明冷战思维即将成为历史。"}},{"pos":"PHRASE 短语","cn":"特地;不怕麻烦;格外努力","en":"If you go out of your way to do something, for example to help someone, you make a special effort to do it.","ex":{"en":"He was very kind to me and seemed to go out of his way to help me.","cn":"他对我非常友善，似乎是特意帮我的忙。"}},{"pos":"PHRASE 短语","cn":"避开;不参加;不卷入","en":"If you keep out of someone's way or stay out of their way, you avoid them or do not get involved with them.","ex":{"en":"I'd kept out of his way as much as I could","cn":"我一直尽量躲着他。"}},{"pos":"PHRASE 短语","cn":"结束;被处理好;得到解决","en":"When something is out of the way, it has finished or you have dealt with it, so that it is no longer a problem or needs no more time spent on it.","ex":{"en":"The plan has to remain confidential at least until the local elections are out of the way","cn":"此项计划至少在地方选举结束之前都得保密。"}},{"pos":"PHRASE 短语","cn":"按自己的意愿行事","en":"If you go your own way, you do what you want rather than what everyone else does or expects.","ex":{"en":"In school I was a loner. I went my own way.","cn":"在学校里我独来独往，我行我素。"}},{"pos":"PHRASE 短语","cn":"同样;同理","en":"You use in the same way to introduce a situation that you are comparing with one that you have just mentioned, because there is a strong similarity between them.","ex":{"en":"There is no reason why a gifted aircraft designer should also be a capable pilot. In the same way, a brilliant pilot can be a menace behind the wheel of a car.","cn":"杰出的飞机设计师没有理由一定也是个出色的飞行员。同样，一个优秀的飞行员或许会是个糟糕的司机。"}},{"pos":"PHRASE 短语","cn":"顽固不变;不变通","en":"If you say that someone is set in their ways, you mean that they have been behaving in the same way for many years and do not want to change.","ex":{"en":"He was too set in his ways to make any real changes.","cn":"他已经积习成性，不肯作任何真正的改变。"}},{"pos":"PHRASE 短语","cn":"（用于指刚才说过的话）那样，这样","en":"You can use that way and this way to refer to a statement or comment that you have just made.","ex":{"en":"Some of us have habits few people know about and we keep it this way","cn":"我们中的一些人有些不为人知的习惯，我们也不想改变这一状况。"}},{"pos":"PHRASE 短语","cn":"(用于引出结果)那样，这样","en":"You can use that way or this way to refer to an action or situation that you have just mentioned, when you go on to mention the likely consequence or effect of it.","ex":{"en":"Keep the soil moist. That way, the seedling will flourish","cn":"保持土壤湿润，那样幼苗就能茁壮成长。"}},{"pos":"PHRASE 短语","cn":"从目前事情发展的情况看","en":"You can use the way things are going to indicate that you expect something to happen because of the way the present situation is developing.","ex":{"en":"The way things are going, perhaps he won't come at all.","cn":"现在看来他是不会来了。"}},{"pos":"PHRASE 短语","cn":"(提供个人意见)我觉得","en":"You add to my way of thinking to a statement in order to indicate that you are giving your opinion.","ex":{"en":"To my way of thinking, it didn't seem as if it ought to be so terribly complicated.","cn":"我觉得，事情好像没必要这么复杂。"}},{"pos":"PHRASE 短语","cn":"毫无疑问；千真万确","en":"If you say that there are no two ways about it, you are emphasizing that there is no doubt at all about a particular situation or about how it should be interpreted.","ex":{"en":"You stay here, you die. No two ways about it.","cn":"你若留在这里，必死无疑。"}},{"pos":"PHRASE 短语","cn":"在进行中","en":"If an activity or plan is under way, it has begun and is now taking place.","ex":{"en":"A full-scale security operation is now under way","cn":"一项全面的安全行动正在进行中…"}},{"pos":"PHRASE 短语","cn":"以各种方式；采用各种方式","en":"Every which way and any which way are used to emphasize that something happens, or might happen, in a lot of different ways, or using a lot of different methods.","ex":{"en":"He re-ran the experiment every which way he could","cn":"他用尽所有可能的方法重复做这个实验。"}},{"pos":"PHRASE 短语","cn":"(强调位置和方向的混乱)向四面八方，杂乱地","en":"Every which way is used to emphasize that things move in a lot of different directions or are arranged in a lot of different positions.","ex":{"en":"...cars parked every which way.","cn":"横七竖八停着的车辆"}},{"pos":"","cn":"","en":"to see the error of your ways→see: ; to look the other way→see: ;"}]},"examples":[{"en":"You can't have it both ways. If you can afford to go out all the time, you can afford to pay off some of your debts.","cn":"你不可能做到两全其美。如果你有钱整天外出玩乐，就能还掉一部分债。"},{"en":"Oh by the way, if you see Jackie, tell her I'll call her this evening.","cn":"啊，对了，你要是看到杰基，告诉她我今晚给她打电话。"}]},"watch":{"media":{"img":["media/ldoce/img/watch.jpg","media/pic/clock_comp.jpg"],"uk":"media/uk/watch__gb_1.mp3","us":"media/us/watch__us_1.mp3"},"oxford":{"phon":"wɒtʃ","pos":"verb","senses":[{"en":"to look at somebody/something for a time, paying attention to what happens","cn":"看；注视；观看；观察","g":"[transitive, intransitive]","ex":{"en":"I was in the living room, watching TV.","cn":"我在客厅里看电视。"}},{"en":"to take care of somebody/something for a short time","cn":"（短时间）照看，看护，照管","g":"[transitive]","ex":{"en":"Could you watch my bags for me while I buy a paper?","cn":"我去买份报纸，你能替我照看一下我的包吗？"}},{"en":"to be careful about something","cn":"小心；当心；留意","g":"[transitive]","lab":"British English also","ex":{"en":"Watch yourself! (= be careful, because you're in a dangerous situation)","cn":"当心！"}},{"en":"to pay attention to a situation so that you notice any changes","cn":"关注；掌握…的情况","g":"[transitive, intransitive]","ex":{"en":"We're watching the situation very carefully.","cn":"我们在密切关注事态发展。"}},{"en":"to observe somebody's activities without their knowledge, especially over a period of time","cn":"监视","g":"[often passive]","ex":{"en":"He didn't know he was being watched by the authorities.","cn":"他当时不知道自己正被当局监视。"}},{"en":"a type of small clock that you wear on your wrist, or (in the past) carried in your pocket","cn":"表；手表；（旧时的）怀表","g":"[countable]","ex":{"en":"She kept looking anxiously at her watch.","cn":"她焦急不安地一个劲儿看表。"},"pos":"noun"},{"en":"the act of watching somebody/something carefully in case of possible danger or problems","cn":"注意；注视；监视；观察","g":"[singular, uncountable]","ex":{"en":"The police have mounted a watch outside the hotel.","cn":"警方已在旅馆外面布置人监视。"},"pos":"noun"},{"en":"a fixed period of time, usually while other people are asleep, during which somebody watches for any danger so that they can warn others, for example on a ship; the person or people who do this","cn":"值班（人）；警戒（人）；守夜（人）","g":"[countable, uncountable]","ex":{"en":"I go on watch in an hour.","cn":"我一个小时后值班。"},"pos":"noun"},{"en":"a notice or an announcement that warns the public that there may be severe weather conditions very soon","cn":"（恶劣天气）警报，预警","g":"[countable]","lab":"North American English","ex":{"en":"They're in charge of issuing the tornado watches.","cn":"他们负责发布龙卷风警报。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"看;注视;留神观察","en":"If you watch someone or something, you look at them, usually for a period of time, and pay attention to what is happening.","ex":{"en":"The man was standing in his doorway watching him","cn":"那个男人站在门口盯着他看。"}},{"pos":"VERB 动词","cn":"看，观看(电视节目、比赛等)","en":"If you watch something on television or an event such as a sports match, you spend time looking at it, especially when you see it from the beginning to the end.","ex":{"en":"I'd stayed up late to watch the film","cn":"我熬夜看了那场电影。"}},{"pos":"VERB 动词","cn":"对…保持关注;掌握…的情况","en":"If you watch a situation or event, you pay attention to it or you are aware of it, but you do not influence it.","ex":{"en":"Human rights groups have been closely watching the case","cn":"人权组织一直在密切关注此案。"}},{"pos":"VERB 动词","cn":"照看，看护(尤指孩子或动物)","en":"If you watch people, especially children or animals, you are responsible for them, and make sure that they are not in danger.","ex":{"en":"Parents can't be expected to watch their children 24 hours a day.","cn":"父母不可能每天24小时照看孩子。"}},{"pos":"VERB 动词","cn":"监视","en":"If you watch someone, you follow them secretly or spy on them.","ex":{"en":"Ella was scared that someone was watching her","cn":"有个人一直在监视埃拉，这让她很害怕。"}},{"pos":"VERB 动词","cn":"当心;留神","en":"If you tell someone to watch a particular person or thing, you are warning them to be careful that the person or thing does not get out of control or do something unpleasant.","ex":{"en":"You really ought to watch these quiet types","cn":"你真的应该留神这些寡言少语的人。"}},{"pos":"N-COUNT 可数名词","cn":"警戒时间;值班时间","en":"A watch is a period of carefully looking and listening, often while other people are asleep and often as a military duty, so that you can warn them of danger or an attack.","ex":{"en":"I had the first watch that May evening.","cn":"我第一次执行警戒任务是在那个五月的晚上。"}},{"pos":"PHRASE 短语","cn":"警戒;守卫","en":"If someone keeps watch, they look and listen all the time, while other people are asleep or doing something else, so that they can warn them of danger or an attack.","ex":{"en":"Jose, as usual, had climbed a tree to keep watch.","cn":"乔斯像往常一样爬到树上放哨。"}},{"pos":"PHRASE 短语","cn":"注意，关注(事态发展)","en":"If you keep watch on events or a situation, you pay attention to what is happening, so that you can take action at the right moment.","ex":{"en":"US officials have been keeping close watch on the situation.","cn":"美国官员一直密切注意着事态的发展。"}},{"pos":"PHRASE 短语","cn":"当心;留神","en":"You say 'watch it' in order to warn someone to be careful, especially when you want to threaten them about what will happen if they are not careful.","ex":{"en":"'Now watch it, Patsy,' the Sergeant told her.","cn":"“留点神，帕齐。”中士提醒她。"}},{"pos":"PHRASE 短语","cn":"（通常指军队夜间的）警戒，值夜","en":"If someone is on watch, they have the job of carefully looking and listening, often while other people are asleep and often as a military duty, so that they can warn them of danger or an attack.","ex":{"en":"Apart from two men on watch in the engine-room, everyone was asleep.","cn":"除了两个人在机房值班外，其他人都在睡觉。"}},{"pos":"PHRASE 短语","cn":"密切注意;提防","en":"If you are on the watch for something, you are expecting it to happen and you therefore pay attention to events so that you will notice it when it does happen.","ex":{"en":"Environmentalists will be on the watch for damage to wildlife.","cn":"环境保护主义者将会密切关注对野生动物造成的伤害。"}},{"pos":"PHRASE 短语","cn":"受到保卫;受到监视;被密切关注","en":"If someone is being kept under watch, they are being guarded or observed all the time."},{"pos":"PHRASE 短语","cn":"等着瞧","en":"You say to someone 'you watch' or 'just watch' when you are predicting that something will happen, and you are very confident that it will happen as you say.","ex":{"en":"You watch. Things will get worse before they get better.","cn":"看着吧，事情在好转之前会先恶化。"}},{"pos":"","cn":"","en":"watch this space→see: ; to watch your step→see: ;"},{"pos":"","cn":"","en":"相关词组：watch for watch out watch out for watch over"},{"pos":"N-COUNT 可数名词","cn":"手表;怀表","en":"A watch is a small clock which you wear on a strap on your wrist, or on a chain."}]},"examples":[{"en":"We sat outside a cafe, watching the world go by.","cn":"我们坐在一家小餐馆外面，望着眼前来来往往的人们。"},{"en":"‘Would you like to play?’ ‘No thanks — I'll just watch.’ “","cn":"你想玩吗？” “不啦，谢谢。我就看看好了。”"}]},"waist":{"media":{"uk":"media/uk/waist__gb_1.mp3","us":"media/us/waist__us_1.mp3"},"oxford":{"phon":"weɪst","pos":"noun","senses":[{"en":"the area around the middle of the body between the ribs and the hips, often narrower than the areas above and below","cn":"腰；腰部","lab":"informal","ex":{"en":"He put his arm around her waist.","cn":"他搂住了她的腰。"}},{"en":"the part of a piece of clothing that covers the waist","cn":"（衣服的）腰部，腰","ex":{"en":"a skirt with an elasticated waist","cn":"腰部有松紧带的裙子"}},{"en":"having the type of waist mentioned","cn":"有…腰身的；腰身…的","ex":{"en":"a high-waisted dress","cn":"高腰连衣裙"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腰;腰部","en":"Your waist is the middle part of your body where it narrows slightly above your hips.","ex":{"en":"Ricky kept his arm round her waist","cn":"里基一直揽着她的腰。"}},{"pos":"N-COUNT 可数名词","cn":"(衣服的)腰部，腰身","en":"The waist of a garment such as a dress, coat, or pair of trousers is the part of it which covers the middle part of your body."}]},"examples":[{"en":"She was paralysed from the waist down (= in the area below her waist).","cn":"她从腰部以下都瘫痪了。"},{"en":"a skirt with an elasticated waist","cn":"腰部有松紧带的裙子"}]},"warn":{"oxford":{"phon":"wɔːn","pos":"verb","senses":[{"en":"to tell somebody about something, especially something dangerous or unpleasant that is likely to happen, so that they can avoid it","cn":"提醒注意（可能发生的事）；使警惕","g":"[transitive, intransitive]","ex":{"en":"I tried to warn him, but he wouldn't listen.","cn":"我设法提醒过他，可他就是不听。"}},{"en":"to strongly advise somebody to do or not to do something in order to avoid danger or punishment","cn":"劝告（使有所防备）；警告；告诫","g":"[intransitive, transitive]","ex":{"en":"The guidebook warns against walking alone at night.","cn":"这本指南告诫夜间不要单独行走。"}},{"en":"to give somebody an official warning after they have broken a rule","cn":"警告","g":"[transitive]","ex":{"en":"The referee warned him for dangerous play.","cn":"裁判警告他有危险动作。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"提醒;警告","en":"If you warn someone about something such as a possible danger or problem, you tell them about it so that they are aware of it.","ex":{"en":"When I had my first baby friends warned me that children were expensive","cn":"当我有了第一个孩子时，朋友们提醒我说养孩子是很花钱的。"}},{"pos":"VERB 动词","cn":"警告，告诫(不要做…)","en":"If you warn someone not to do something, you advise them not to do it so that they can avoid possible danger or punishment. →see usage note at:","ex":{"en":"Mrs. Blount warned me not to interfere","cn":"布朗特夫人警告我不要插手。"}},{"pos":"CONVENTION 惯用语","cn":"小心;提防","en":"If someone says to you 'be warned', they are advising you to be cautious, because there are risks that you may not have thought about.","ex":{"en":"But be warned: this is not a cheap option.","cn":"但要慎重：这个选择代价不菲。"}},{"pos":"","cn":"","en":"相关词组：warn away warn off"}]},"media":{"uk":"media/uk/warn__gb_1.mp3","us":"media/us/warn__us_1.mp3"},"examples":[{"en":"The farmer warned us off his land when we tried to camp there.","cn":"我们想在那里露营时，农场主警告我们不得靠近他的土地。"},{"en":"If you're thinking of getting a dog, be warned — they take a lot of time and money.","cn":"如果你想养条狗，有话说在前头，那可既费时间又费钱。"}]},"watermill":{"media":{"uk":"media/uk/watermill__gb_1.mp3","us":"media/us/watermill__us_1.mp3"},"oxford":{"phon":"ˈwɔːtəmɪl","pos":"noun","senses":[{"en":"a mill next to a river in which the equipment for grinding grain into flour is driven by the power of the water turning a wheel","cn":"水磨；水力磨粉机"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水磨;水力磨粉机","en":"A watermill is a mill powered by a water wheel."}]}},"walking":{"media":{"uk":"media/uk/walking__gb_1.mp3","us":"media/us/walking__us_1.mp3"},"oxford":{"phon":"ˈwɔːkɪŋ","pos":"noun","senses":[{"en":"the activity of going for walks in the countryside for exercise or pleasure","cn":"行走；步行；散步；徒步旅行","lab":"especially British English","ex":{"en":"to go walking","cn":"去散步"}},{"en":"the sport of walking a long distance as fast as possible without running","cn":"竞走"},{"en":"used to describe a human or living example of the thing mentioned","cn":"似人的；活的","ex":{"en":"She's a walking dictionary (= she knows a lot of words).","cn":"她是部活字典。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指在乡间以休闲或锻炼为目的的)散步，步行","en":"Walking is the activity of taking walks for exercise or pleasure, especially in the country.","ex":{"en":"Recently I've started to do a lot of walking and cycling.","cn":"最近我开始经常散步和骑自行车。"}},{"pos":"ADJ 形容词","cn":"（表示强调）活的…","en":"You can use walking in expressions like a walking disaster or a walking dictionary in order to emphasize, for example, that someone causes a lot of disasters, or knows a lot of difficult words.","ex":{"en":"He was a walking encyclopaedia","cn":"他是一部活的百科全书。"}}]},"examples":[{"en":"She's a walking dictionary (= she knows a lot of words).","cn":"她是部活字典。"},{"en":"a walking holiday in Scotland","cn":"苏格兰的徒步旅行假日"}]},"wavelength":{"oxford":{"phon":"ˈweɪvleŋkθ","pos":"noun","senses":[{"en":"the distance between two similar points on a wave of energy, such as light or sound","cn":"波长"},{"en":"the size of a radio wave that is used by a particular radio station, etc. for sending signals or broadcasting programmes","cn":"（广播电台等使用的）频道，波道","ex":{"en":"Radio One has broadcast on this wavelength for years.","cn":"广播1 台已经用这个波长广播多年了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"波长","en":"A wavelength is the distance between a part of a wave of energy such as light or sound and the next similar part.","ex":{"en":"Sunlight consists of different wavelengths of radiation","cn":"阳光由几种不同波长的射线组成。"}},{"pos":"N-COUNT 可数名词","cn":"广播波段","en":"A wavelength is the size of radio wave which a particular radio station uses to broadcast its programmes.","ex":{"en":"She found the wavelength of their broadcasts, and left the radio tuned to their station.","cn":"她找到了他们的广播波段，把收音机调到那个位置收听他们电台的节目。"}},{"pos":"PHRASE 短语","cn":"志趣相投;观点一致","en":"If two people are on the same wavelength, they find it easy to understand each other and they tend to agree, because they share similar interests or opinions.","ex":{"en":"It's great to work with people who are on the same wavelength.","cn":"与志同道合的人一起工作真是太棒了。"}}]},"media":{"img":["media/pic/wavelength.jpg","media/thumb/wavelength.jpg"],"uk":"media/uk/wavelength__gb_1.mp3","us":"media/us/wavelength__us_1.mp3"},"examples":[{"en":"Dad is just on a different wavelength from me.","cn":"爸爸和我就是没有共同语言。"}]},"wayward":{"media":{"uk":"media/uk/wayward__gb_1.mp3","us":"media/us/wayward__us_1.mp3"},"oxford":{"phon":"ˈweɪwəd","pos":"adjective","senses":[{"en":"difficult to control","cn":"难以控制的；任性的；倔强的","ex":{"en":"a wayward child","cn":"任性的孩子"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"任性的;不易管教的;难以捉摸的","en":"If you describe a person or their behaviour as wayward, you mean that they behave in a selfish, bad, or unpredictable way, and are difficult to control.","ex":{"en":"...wayward children with a history of severe emotional problems.","cn":"出现过严重情绪问题的任性的孩子"}}]},"examples":[{"en":"wayward emotions","cn":"反复无常的情绪"},{"en":"a wayward child","cn":"任性的孩子"}]},"washing":{"media":{"uk":"media/uk/washing__gb_1.mp3","us":"media/us/washing__us_1.mp3"},"oxford":{"phon":"ˈwɒʃɪŋ","pos":"noun","senses":[{"en":"the act of cleaning something using water and usually soap","cn":"洗；洗涤；洗刷；冲洗","g":"[uncountable, singular]","ex":{"en":"a gentle shampoo for frequent washing","cn":"供经常洗发用的柔性洗发剂"}},{"en":"clothes, sheets, etc. that are waiting to be washed, being washed or have just been washed","cn":"待洗的（或正在洗的、刚洗过的）衣物","g":"[uncountable]","lab":"British English","ex":{"en":"a pile of dirty washing","cn":"一堆待洗的脏衣物"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"待洗(或正在洗、刚洗过)的衣物","en":"Washing is a collection of clothes, sheets, and other things which are waiting to be washed, are being washed, or have just been washed.","ex":{"en":"...plastic bags full of dirty washing","cn":"装满脏衣服的塑料袋"}}]},"examples":[{"en":"Would you hang the washing out (= hang it outside to dry)?","cn":"你把刚洗过的衣服晾在外面好吗？"},{"en":"a gentle shampoo for frequent washing","cn":"供经常洗发用的柔性洗发剂"}]},"washbasin":{"oxford":{"phon":"ˈwɒʃbeɪsn","pos":"noun","senses":[{"en":"a large bowl that has taps and is fixed to the wall in a bathroom, used for washing your hands and face in","cn":"（卫生间里的）洗手盆，洗脸盆","ex":{"en":"He washed his shirt in the washbasin.","cn":"他在脸盆里洗了衬衫。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脸盆","en":"A washbasin is a large bowl, usually with taps for hot and cold water, for washing your hands and face."}]},"media":{"uk":"media/uk/washbasin__gb_1.mp3","us":"media/us/washbasin__us_1.mp3"}},"waist-high":{"oxford":{"phon":"ˌweɪst ˈhaɪ","pos":"adjective, adverb","senses":[{"en":"high enough to reach the middle part of the body","cn":"齐腰高（的）；高至腰部（的）","ex":{"en":"waist-high grass","cn":"齐腰高的草"}}]},"media":{"uk":"media/uk/waist_high_1_gb_1.mp3","us":"media/us/waist_high_1_us_1.mp3"},"examples":[{"en":"The grass had grown waist-high.","cn":"草长得齐腰高了。"},{"en":"waist-high grass","cn":"齐腰高的草"}]},"warning":{"media":{"uk":"media/uk/warning__gb_1.mp3","us":"media/us/warning__us_1.mp3"},"oxford":{"phon":"ˈwɔːnɪŋ","pos":"noun","senses":[{"en":"a statement, an event, etc. telling somebody that something bad or unpleasant may happen in the future so that they can try to avoid it","cn":"（就可能发生的意外等提出的）警告，警示；先兆","g":"[countable, uncountable]","ex":{"en":"I had absolutely no warning.","cn":"我没得到一丁点儿警示。"}},{"en":"a statement telling somebody that they will be punished if they continue to behave in a particular way","cn":"（就将要遭受的处罚等提出的）警告，警戒","g":"[countable]","ex":{"en":"to give somebody a verbal/written/final warning","cn":"向某人发出口头／书面／最后警告"}},{"en":"telling or showing somebody that something bad or unpleasant may happen in the future so that they can try to avoid it","cn":"（就可能发生的意外等提出的）警告，警示；先兆","ex":{"en":"She had ignored the warning signs of trouble ahead.","cn":"她忽视了那些麻烦将至的警示信号。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(口头或书面的)警告，警示","en":"A warning is something which is said or written to tell people of a possible danger, problem, or other unpleasant thing that might happen.","ex":{"en":"The minister gave a warning that if war broke out, it would be catastrophic","cn":"部长警告说，战争一旦爆发将会是灾难性的。"}},{"pos":"N-VAR 可变名词","cn":"预告;预兆","en":"A warning is an advance notice of something that will happen, often something unpleasant or dangerous.","ex":{"en":"The soldiers opened fire without warning","cn":"士兵们在没有发出警告的情况下开了枪。"}},{"pos":"ADJ 形容词","cn":"警告的;告诫的","en":"Warning actions or signs give a warning.","ex":{"en":"She ignored the warning signals","cn":"她忽视了一些预警信号。"}}]},"examples":[{"en":"to give sb fair/advance/adequate warning of sth","cn":"就某事向某人发出充分的/预先的/足够的警告"},{"en":"Warning bells began to ring (= it was a sign that sth was wrong) when her letters were returned unopened.","cn":"当她的信原封不动被退回时，不祥之感就来了。"}]},"wagon":{"media":{"uk":"media/uk/wagon__gb_1.mp3","us":"media/us/wagon__us_1.mp3"},"oxford":{"phon":"ˈwæɡən","pos":"noun","senses":[{"en":"a railway truck for carrying goods","cn":"（铁路）货车车厢，车皮","lab":"British English","ex":{"en":"He tried to hide in a container wagon.","cn":"他试图藏到集装箱运输车里。"}},{"en":"a vehicle with four wheels, pulled by horses or oxen and used for carrying heavy loads","cn":"四轮载重马车（或牛车）","lab":"British English also","ex":{"en":"covered wagons rolling across the prairies","cn":"驶过大草原的有篷大马车"}},{"en":"a small table on very small wheels, used for carrying or serving food or drink","cn":"（运或送食品、饮料的）小推车，台车","lab":"both North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"四轮运货马车","en":"A wagon is a strong vehicle with four wheels, usually pulled by horses or oxen and used for carrying heavy loads."},{"pos":"N-COUNT 可数名词","cn":"(火车的)货车车厢，车皮","en":"A wagon is a large container on wheels which is pulled by a train."},{"pos":"PHRASE 短语","cn":"停止喝酒;戒酒","en":"Someone who is on the wagon has stopped drinking alcohol.","ex":{"en":"I'm on the wagon for a while. Cleaning out my system.","cn":"我这段时间正在戒酒，对体内进行大扫除。"}}]}},"wake":{"media":{"uk":"media/uk/wake__gb_1.mp3","us":"media/us/wake__us_1.mp3"},"oxford":{"phon":"weɪk","pos":"verb","senses":[{"en":"to stop sleeping; to make somebody stop sleeping","cn":"醒；醒来；唤醒；弄醒","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"I always wake early in the summer.","cn":"我夏天总是醒得早。"}},{"en":"to make somebody remember something or feel something again","cn":"唤起（记忆）；使再次感觉到","g":"[transitive]","lab":"literary or formal","ex":{"en":"The incident woke memories of his past sufferings.","cn":"这件事唤起了他对往昔苦难的回忆。"}},{"en":"an occasion before or after a funeral when people gather to remember the dead person, traditionally held the night before the funeral to watch over the body before it is buried","cn":"（葬礼前的）守夜；守灵","pos":"noun"},{"en":"the track that a boat or ship leaves behind on the surface of the water","cn":"（船只航行时的）尾流，伴流，航迹","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"醒;醒来;唤醒;弄醒","en":"When you wake or when someone or something wakes you, you become conscious again after being asleep.","ex":{"en":"It was cold and dark when I woke at 6.30","cn":"我6点半醒来时，天又冷又黑。"}},{"pos":"N-COUNT 可数名词","cn":"(航行中的船等留下的)伴流，尾流，航迹","en":"The wake of a boat or other object moving in water is the track of waves that it makes behind it as it moves through the water.","ex":{"en":"The ride was smooth until they got into the merchant ship's wake","cn":"航行一直很顺利，直到他们碰上了商船的尾流。"}},{"pos":"N-COUNT 可数名词","cn":"(葬礼前后的)守夜，守灵","en":"A wake is a gathering or social event that is held before or after someone's funeral.","ex":{"en":"A funeral wake was in progress.","cn":"正在进行葬礼守灵。"}},{"pos":"PREP-PHRASE 短语介词","cn":"随着…而来;作为…的结果","en":"If one thing follows in the wake of another, it happens after the other thing is over, often as a result of it.","ex":{"en":"The governor has enjoyed a huge surge in the polls in the wake of last week's convention","cn":"上周的大会过后，民意调查显示州长支持率大幅上升。"}},{"pos":"PHRASE 短语","cn":"醒着的时间;非睡眠时间","en":"Your waking hours are the times when you are awake rather than asleep.","ex":{"en":"It was work which consumed most of his waking hours","cn":"他醒着的时候大部分时间都在工作。"}},{"pos":"PHRASE 短语","cn":"（留）在…身后","en":"If you leave something or someone in your wake, you leave them behind you as you go.","ex":{"en":"Adam stumbles on, leaving a trail of devastation in his wake","cn":"亚当蹒跚而行，沿路留下毁坏的痕迹。"}},{"pos":"PHRASE 短语","cn":"紧随…;效仿…","en":"If you are following in someone's wake, you are following them or their example.","ex":{"en":"In his wake came a waiter wheeling a trolley.","cn":"一位推着手推车的侍者紧随着他过来。"}},{"pos":"","cn":"","en":"相关词组：wake up wake up to"}]},"examples":[{"en":"There have been demonstrations on the streets in the wake of the recent bomb attack.","cn":"在近来的轰炸之后，大街上随即出现了示威游行。"},{"en":"The incident woke memories of his past sufferings.","cn":"这件事唤起了他对往昔苦难的回忆。"}]},"warmly":{"oxford":{"phon":"ˈwɔːmli","pos":"adverb","senses":[{"en":"in a way that keeps you warm","cn":"暖和地，温暖地","ex":{"en":"They were warmly dressed in coats and scarves.","cn":"他们穿着大衣，戴着围巾，十分暖和。"}},{"en":"in a way that shows enthusiasm, friendship or love","cn":"热情地","ex":{"en":"The play was warmly received by the critics.","cn":"剧评人对这部戏赞誉有加。"}}]},"media":{"uk":"media/uk/warmly__gb_1.mp3","us":"media/us/warmly__us_1.mp3"},"examples":[{"en":"They were warmly dressed in coats and scarves.","cn":"他们身着大衣，围着围巾，穿得暖暖和和。"},{"en":"The play was warmly received by the critics.","cn":"评论家对这出戏反应热烈。"}]},"wanting":{"media":{"uk":"media/uk/wanting__gb_1.mp3","us":"media/us/wanting__us_1.mp3"},"oxford":{"phon":"ˈwɒntɪŋ","pos":"adjective","senses":[{"en":"not having enough of something","cn":"缺少；缺乏；不足","ex":{"en":"The students were certainly not wanting in enthusiasm.","cn":"学生们当然不乏热情。"}},{"en":"not good enough","cn":"欠缺；不够好；不令人满意","ex":{"en":"This explanation is wanting in many respects.","cn":"这一解释在很多方面不能令人满意。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不够格的;未达到应有水准的","en":"If you find something or someone wanting, they are not of as high a standard as you think they should be.","ex":{"en":"He analysed his game and found it wanting","cn":"他分析了他的比赛，发现还有待改进。"}}]},"examples":[{"en":"This explanation is wanting in many respects.","cn":"这一解释在很多方面不能令人满意。"},{"en":"The new system was tried and found wanting.","cn":"这一新系统经测试发现不够好。"}]},"wasting":{"media":{"uk":"media/uk/wasting__gb_1.mp3","us":"media/us/wasting__us_1.mp3"},"oxford":{"phon":"ˈweɪstɪŋ","pos":"adjective","senses":[{"en":"a wasting disease or illness is one that causes somebody to gradually become weaker and thinner","cn":"（指疾病）消耗性的，使消瘦的，使虚弱的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(疾病)使人消瘦衰弱的，消耗性的","en":"A wasting disease is one which makes you gradually become thinner and weaker."}]},"examples":[{"en":"The airline is a wasting asset.","cn":"这家航空公司是个亏本企业。"}]},"watertight":{"media":{"uk":"media/uk/watertight__gb_1.mp3","us":"media/us/watertight__us_1.mp3"},"oxford":{"phon":"ˈwɔːtətaɪt","pos":"adjective","senses":[{"en":"that does not allow water to get in or out","cn":"不透水的；防水的；水密的","ex":{"en":"a watertight container","cn":"不漏水的容器"}},{"en":"carefully prepared so that it contains no mistakes, faults or weaknesses","cn":"严密的；无懈可击的；天衣无缝的","ex":{"en":"a watertight alibi","cn":"无法驳倒的不在犯罪现场证据"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不透水的;水密的","en":"Something that is watertight does not allow water to pass through it, for example because it is tightly sealed.","ex":{"en":"The flask is completely watertight, even when laid on its side","cn":"即使平放，这个真空水杯也是滴水不漏。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(事实、论点或协议)严密的，无懈可击的","en":"A watertight case, argument, or agreement is one that has been so carefully put together that nobody will be able to find a fault in it.","ex":{"en":"The police had a watertight case. They even got his fingerprints from that glass cabinet.","cn":"警方找到了确凿的证据。他们甚至在那个玻璃橱柜上提取到了他的指纹。"}}]},"examples":[{"en":"The case has to be made watertight.","cn":"案由必须做到无懈可击。"},{"en":"a watertight alibi","cn":"无法驳倒的不在犯罪现场证据"}]},"waiting":{"media":{"uk":"media/uk/waiting__gb_1.mp3","us":"media/us/waiting__us_1.mp3"},"oxford":{"phon":"ˈweɪtɪŋ","pos":"noun","senses":[{"en":"the fact of staying where you are or delaying doing something until somebody/something comes or something happens","cn":"等候；等待","ex":{"en":"No waiting (= on a sign at the side of the road, telling vehicles that they must not stop there).","cn":"禁止停车（路牌指示）"}},{"en":"the job of working as a waiter or waitress","cn":"当侍者；当服务员"}]},"examples":[{"en":"No waiting (= on a sign at the side of the road, telling vehicles that they must not stop there).","cn":"禁止停车（路牌指示）"}]},"warns":{"oxford":{"phon":"wɔːn","pos":"verb","senses":[{"en":"to tell sb about sth, especially sth dangerous or unpleasant that is likely to happen, so that they can avoid it","cn":"提醒注意（可能发生的事）；使警惕"},{"en":"to strongly advise sb to do or not to do sth in order to avoid danger or punishment","cn":"劝告（使有所防备）；警告；告诫"}]}},"waste":{"media":{"uk":"media/uk/waste__gb_1.mp3","us":"media/us/waste__us_1.mp3"},"oxford":{"phon":"weɪst","pos":"noun","senses":[{"en":"the act of using something in a careless or unnecessary way, causing it to be lost or destroyed","cn":"浪费；滥用","g":"[uncountable, singular]","sc":"not good use","ex":{"en":"I hate unnecessary waste.","cn":"我憎恨不必要的浪费。"}},{"en":"a situation in which it is not worth spending time, money, etc. on something","cn":"白费；糟蹋","g":"[singular]","sc":"not good use","ex":{"en":"These meetings are a complete waste of time.","cn":"这些会议完全是白费时间。"}},{"en":"materials that are no longer needed and are thrown away","cn":"废料；废物；弃物；垃圾","g":"[uncountable]","sc":"materials","ex":{"en":"household/garden/industrial waste","cn":"生活／园林垃圾；工业废料"}},{"en":"solid or liquid material that the body gets rid of","cn":"粪便","g":"[uncountable]","sc":"materials","ex":{"en":"The farmers use both animal and human waste as fertilizer.","cn":"农民把牲畜和人类的粪便都用作肥料。"}},{"en":"a large area of land where there are very few people, animals or plants","cn":"人烟稀少的地区；荒芜地区；荒原","g":"[plural]","lab":"formal","sc":"land","ex":{"en":"the frozen wastes of Siberia","cn":"西伯利亚的冻土荒原"}},{"en":"to use more of something than is necessary or useful","cn":"浪费；滥用","sc":"not use well","ex":{"en":"Stop wasting time and just get on with it!","cn":"别磨蹭了，抓紧干吧！"},"pos":"verb"},{"en":"to not make good or full use of somebody/something","cn":"未充分利用；使…屈才","g":"[usually passive]","sc":"not use well","ex":{"en":"It was a wasted opportunity.","cn":"这白白浪费了一次机会。"},"pos":"verb"},{"en":"to give, say, use, etc. something good where it is not valued or used in the way that it should be","cn":"白费；糟蹋","sc":"not use well","ex":{"en":"Don't waste your sympathy on him—he got what he deserved.","cn":"别把你的同情心白白浪费在他的身上，他是咎由自取。"},"pos":"verb"},{"en":"to get rid of somebody, usually by killing them","cn":"干掉；把…废了；杀死","lab":"informal, especially North American English，，","sc":"kill somebody","pos":"verb"},{"en":"to defeat somebody very badly in a game or competition","cn":"（游戏或比赛中）大胜，把…打得落花流水","lab":"North American English, informal，，","sc":"defeat somebody","pos":"verb"},{"en":"no longer needed for a particular process and therefore thrown away","cn":"废弃的；丢弃的；无用的","sc":"materials","ex":{"en":"the disposal of waste material","cn":"废弃物的处理"},"pos":"adjective"},{"en":"not suitable for building or growing things on and therefore not used","cn":"荒芜的；废弃的","sc":"land","ex":{"en":"The car was found on a piece of waste ground.","cn":"那辆车是在一块荒地里发现的。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"浪费;白费","en":"If you waste something such as time, money, or energy, you use too much of it doing something that is not important or necessary, or is unlikely to succeed.","ex":{"en":"There could be many reasons and he was not going to waste time speculating on them","cn":"原因可能有很多，他不打算浪费时间对此妄加猜测。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"浪费;滥用;糟蹋","en":"Waste is the use of money or other resources on things that do not need it.","ex":{"en":"The packets are measured to reduce waste","cn":"包裹的大小经过测量以减少浪费。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"废物;废料","en":"Waste is material which has been used and is no longer wanted, for example because the valuable or useful part of it has been taken out.","ex":{"en":"Congress passed a law that regulates the disposal of waste","cn":"国会通过了一项规范废弃物处理的法律。"}},{"pos":"VERB 动词","cn":"错过(机会)","en":"If you waste an opportunity for something, you do not take advantage of it when it is available.","ex":{"en":"Let's not waste an opportunity to see the children","cn":"咱们别错过了看孩子们的机会。"}},{"pos":"VERB 动词","cn":"（因不被接受、理解等而）浪费（建议等）；使徒劳无益","en":"If you say that something is wasted on someone, you mean that there is no point giving it or telling it to them as they will not appreciate, understand, or pay any attention to it.","ex":{"en":"All the well-meant, sincere advice is largely wasted on him.","cn":"他对所有善意、真挚的建议基本都无动于衷。"}},{"pos":"ADJ 形容词","cn":"(尤指市内或市郊的土地)荒芜的，荒废的","en":"Waste land is land, especially in or near a city, which is not used or looked after by anyone, and so is covered by wild plants and rubbish.","ex":{"en":"There was a patch of waste land behind the church","cn":"教堂的后面有一块荒地。"}},{"pos":"N-PLURAL 复数名词","cn":"荒漠;沙漠","en":"Wastes are a large area of land, for example a desert, in which there are very few people, plants, or animals.","ex":{"en":"...the barren wastes of the Sahara.","cn":"贫瘠的撒哈拉沙漠"}},{"pos":"PHRASE 短语","cn":"被浪费;被糟蹋掉","en":"If something goes to waste, it remains unused or has to be thrown away.","ex":{"en":"So much of his enormous effort and talent will go to waste if we are forced to drop one hour of the film","cn":"如果我们被迫把电影缩短1小时，那么他付出的许多努力就会白费，他的才华也将大半被淹没。"}},{"pos":"PHRASE 短语","cn":"摧毁;把…变为荒地","en":"If something or someone lays waste an area or town or lays waste to it, they completely destroy it.","ex":{"en":"The war has laid waste large regions of the countryside.","cn":"这场战争摧毁了大片村庄。"}},{"pos":"PHRASE 短语","cn":"勤俭节约，吃穿不缺","en":"The expression waste not, want not means that if you do not use too much of something now you will have some left later when you need it.","ex":{"en":"...a nation that prides itself on its 'waste not, want not' thrift and its environmental conscience.","cn":"为其“俭以防匮”的节俭作风和环保意识而自豪的国家"}},{"pos":"","cn":"","en":"to waste your breath→see: ; to waste no time→see: ;"},{"pos":"","cn":"","en":"相关词组：waste away"}]},"examples":[{"en":"Don't waste your sympathy on him — he got what he deserved.","cn":"别把你的同情心白白浪费在他的身上，他是咎由自取。"},{"en":"You're wasted as a sales manager — you should have been an actor.","cn":"你当销售经理屈才了，你本应该做演员。"}]},"warming":{"oxford":{"phon":"ˈwɔːmɪŋ","pos":"noun","senses":[{"en":"the process of making something, or of becoming, warm or warmer","cn":"加温；温暖；暖和；变暖","ex":{"en":"atmospheric warming","cn":"大气层变暖"}},{"en":"making something/somebody warmer","cn":"使某物/某人更暖和","ex":{"en":"the warming rays of the sun","cn":"暖融融的阳光"},"pos":"adjective"}]},"media":{"uk":"media/uk/warming__gb_1.mp3","us":"media/us/warming__us_1.mp3"},"examples":[{"en":"the warming rays of the sun","cn":"暖融融的太阳光线"},{"en":"atmospheric warming","cn":"大气层变暖"}]},"waiter":{"media":{"uk":"media/uk/waiter__gb_1.mp3","us":"media/us/waiter__us_1.mp3","img":["media/ldoce/img/waiter.jpg"]},"oxford":{"phon":"ˈweɪtə(r)","pos":"noun","senses":[{"en":"a man whose job is to serve customers at their tables in a restaurant, etc.","cn":"（餐馆等的）服务员，侍者","lab":"British English","ex":{"en":"I'll ask the waiter for the bill.","cn":"我去问服务员要账单。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男侍者;男服务员","en":"A waiter is a man who works in a restaurant, serving people with food and drink."}]},"examples":[{"en":"Waiter, could you bring me some water?","cn":"服务员，给我送点儿水来好吗？"},{"en":"I'll ask the waitress for the bill.","cn":"我要让女服务员拿账单来。"}]},"war":{"media":{"uk":"media/uk/war__gb_1.mp3","us":"media/us/war__us_1.mp3"},"oxford":{"phon":"wɔː(r)","pos":"noun","senses":[{"en":"a situation in which two or more countries or groups of people fight against each other over a period of time","cn":"战争；战争状态","g":"[uncountable, countable]","lab":"formal","ex":{"en":"the Second World War","cn":"第二次世界大战"}},{"en":"a situation in which there is aggressive competition between groups, companies, countries, etc.","cn":"（群体、公司、国家之间的）竞争，斗争，对抗，冲突","g":"[countable, uncountable]","ex":{"en":"The US threatened a trade war with Europe after the breakdown of the talks.","cn":"会谈破裂后，美国威胁说要与欧洲展开贸易战。"}},{"en":"a fight or an effort over a long period of time to get rid of or stop something unpleasant","cn":"（为消灭有害事物的）长期斗争；顽强抵御","g":"[uncountable, singular]","ex":{"en":"The government has declared war on drug dealers.","cn":"政府已向贩毒分子宣战。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"战争","en":"A war is a period of fighting or conflict between countries or states.","ex":{"en":"He spent part of the war in the National Guard","cn":"战争期间，他在国民警卫队呆过一段时间。"}},{"pos":"N-VAR 可变名词","cn":"(国家或组织之间的)经济竞争","en":"War is intense economic competition between countries or organizations.","ex":{"en":"The most important thing is to reach an agreement and to avoid a trade war.","cn":"最重要的是达成协议，避免贸易战。"}},{"pos":"N-VAR 可变名词","cn":"宣战;斗争","en":"If you make war on someone or something that you are opposed to, you do things to stop them succeeding.","ex":{"en":"She has been involved in the war against organised crime.","cn":"她参与了打击有组织犯罪的斗争。"}},{"pos":"PHRASE 短语","cn":"(在打架或事故中)受伤","en":"If someone has been in the wars, they have been injured, for example in a fight or in an accident.","ex":{"en":"Ben has also been in the wars. He is still in plaster after breaking a leg.","cn":"本也受了伤。他摔断了一条腿，现在还打着石膏。"}},{"pos":"PHRASE 短语","cn":"开战;打仗","en":"If a country goes to war, it starts fighting a war.","ex":{"en":"Do you think this crisis can be settled without going to war?","cn":"你认为这场危机能和平解决吗？"}},{"pos":"PHRASE 短语","cn":"论战;口水战","en":"If two people, countries, or organizations have a war of words, they criticize each other because they strongly disagree about something.","ex":{"en":"Animal rights activists have been engaged in an increasingly bitter war of words with many of the nation's zoos.","cn":"动物权利保护者和该国多家动物园展开了越来越激烈的论战。"}},{"pos":"","cn":"","en":"to lose the battle but win the war→see: ;"}]},"examples":[{"en":"The government does not want to go to war (= start a war) unless all other alternatives have failed.","cn":"除非所有其他方法都行不通，否则政府不希望开战。"},{"en":"You look like you've been in the wars — who gave you that black eye?","cn":"看样子你打架受伤了，是谁把你打得鼻青眼肿？"}]},"wait":{"media":{"uk":"media/uk/wait__gb_1.mp3","us":"media/us/wait__us_1.mp3"},"oxford":{"phon":"weɪt","pos":"verb","senses":[{"en":"to stay where you are or delay doing something until somebody/something comes or something happens","cn":"等；等待；等候","g":"[intransitive, transitive]","lab":"especially North American English","ex":{"en":"She rang the bell and waited.","cn":"她按铃后等候着。"}},{"en":"to hope or watch for something to happen, especially for a long time","cn":"（尤指长期地）希望，盼望，期待","g":"[intransitive, transitive]","ex":{"en":"Leeds United had waited for success for eighteen years.","cn":"利兹联队企盼夺冠已经十八年了。"}},{"en":"to be ready for somebody to have or use","cn":"准备妥；在手边；可得到；可使用","g":"[intransitive]","ex":{"en":"Your car is waiting, sir.","cn":"先生，您的车已经在等您了。"}},{"en":"to be left to be dealt with at a later time because immediate action is not needed","cn":"推迟；搁置；延缓","g":"[intransitive]","ex":{"en":"I've got some calls to make but they can wait until tomorrow.","cn":"我有几个电话要打，不过可以等到明天再说。"}},{"en":"an act of waiting; an amount of time waited","cn":"等候；等待；等待的时间","ex":{"en":"The wait seemed interminable.","cn":"等待似乎无休无止。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"等待;等候","en":"When you wait for something or someone, you spend some time doing very little, because you cannot act until that thing happens or that person arrives.","ex":{"en":"I walk to a street corner and wait for the school bus","cn":"我走到街角等校车。"}},{"pos":"N-COUNT 可数名词","cn":"等待;等待的时间","en":"A wait is a period of time in which you do very little, before something happens or before you can do something.","ex":{"en":"...the four-hour wait for the organizers to declare the result.","cn":"组织者宣布结果之前长达4小时的等待"}},{"pos":"VERB 动词","cn":"准备妥当;可获得;可使用","en":"If something is waiting for you, it is ready for you to use, have, or do.","ex":{"en":"There'll be a car waiting for you","cn":"会有辆汽车等你。"}},{"pos":"VERB 动词","cn":"延缓;推迟;搁置","en":"If you say that something can wait, you mean that it is not important or urgent and so you will deal with it or do it later.","ex":{"en":"I want to talk to you, but it can wait","cn":"我想和你谈谈，但可以晚点再说。"}},{"pos":"VERB 动词","cn":"(用于鼓励或威胁)等着","en":"You can use wait when you are trying to make someone feel excited, or to encourage or threaten them.","ex":{"en":"If you think this all sounds very exciting, just wait until you read the book","cn":"如果你觉得所有这些听起来令人兴奋，那就等着去读这本书吧。"}},{"pos":"VERB 动词","cn":"(用于打断讲话)等一下，慢着","en":"Wait is used in expressions such as wait a minute ,wait a second, and wait a moment to interrupt someone when they are speaking, for example because you object to what they are saying or because you want them to repeat something.","ex":{"en":"'Wait a minute!' he broke in. 'This is not giving her a fair hearing!'","cn":"“等一下，”他插嘴说，“这没有给她一个公平的解释机会！”"}},{"pos":"VERB 动词","cn":"服务;服侍;招待","en":"If an employee waits on you, for example in a restaurant or hotel, they take orders from you and bring you what you want.","ex":{"en":"There were plenty of servants to wait on her","cn":"有很多仆人服侍她。"}},{"pos":"PHRASE 短语","cn":"等不及;迫不及待;渴望","en":"If you say that you can't wait to do something or can hardly wait to do it, you are emphasizing that you are very excited about it and eager to do it.","ex":{"en":"We can't wait to get started","cn":"我们迫不及待地想开始。"}},{"pos":"CONVENTION 惯用语","cn":"(让人在命令下达前勿提前做某事)等一等","en":"You say 'wait for it' to stop someone from doing something too soon because you have not yet given them the command to do it.","ex":{"en":"Arms bend. Arms upward. Wait for it. Stretch.","cn":"手臂弯曲。手臂上举。保持一下。伸展。"}},{"pos":"PHRASE 短语","cn":"(表示接下来要说的内容非常有趣或令人惊奇)注意了，听好了","en":"You can use 'wait for it' to indicate that you are about to say something that is amusing or surprising.","ex":{"en":"A cool $500,000 is to be spent on obtaining genuine 17th-century air from the inside of, wait for it, an occupied lead coffin.","cn":"将花费整整50万美元获取货真价实的17世纪的空气，注意了，是从一个内有尸体的铅制棺材里获得。"}},{"pos":"PHRASE 短语","cn":"等着瞧;等等看","en":"If you tell someone to wait and see, you tell them that they must be patient or that they must not worry about what is going to happen in the future because they have no control over it.","ex":{"en":"We'll have to wait and see what happens.","cn":"我们只好等等看将会发生什么。"}},{"pos":"PHRASE 短语","cn":"(表示催促)你还等什么呢？","en":"If you say to someone 'What are you waiting for?' you are telling them to hurry up and do something.","ex":{"en":"Well, what are you waiting for? Do I have to ask you for a kiss?","cn":"那你还等什么呢？难道要我求你吻我吗？"}},{"pos":"","cn":"","en":"an accident waiting to happen→see: ; ready and waiting→see: ;"},{"pos":"","cn":"","en":"相关词组：wait around wait in wait on wait up"}]},"examples":[{"en":"They're off on a trip, to — wait for it — the Maldives!","cn":"他们出去旅行了，去的地方是，听好了，马尔代夫！"},{"en":"I've got some calls to make but they can wait until tomorrow.","cn":"我有几个电话要打，不过可以等到明天再说。"}]},"wasteland":{"media":{"uk":"media/uk/wasteland__gb_1.mp3","us":"media/us/wasteland__us_1.mp3"},"oxford":{"phon":"ˈweɪstlænd","pos":"noun","senses":[{"en":"an area of land that cannot be used or that is no longer used for building or growing things on","cn":"荒地；荒原；不毛之地","lab":"figurative","ex":{"en":"industrial wasteland","cn":"工业废地"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"荒地;荒原;不毛之地","en":"A wasteland is an area of land on which not much can grow or which has been spoiled in some way.","ex":{"en":"The pollution has already turned vast areas into a wasteland.","cn":"污染已经使大片地区沦为不毛之地。"}},{"pos":"N-COUNT 可数名词","cn":"(地方、情形或时期的)沉闷乏味，单调","en":"If you refer to a place, situation, or period in time as a wasteland, you are criticizing it because you think there is nothing interesting or exciting in it.","ex":{"en":"...the cultural wasteland of Franco's repressive rule","cn":"佛朗哥高压统治下的文化贫瘠"}}]},"examples":[{"en":"( figurative ) The mid 1970s are seen as a cultural wasteland for rock music. * 20","cn":"世纪 70 年代中期被视为摇滚乐的文化荒漠。"},{"en":"The mid 1970s are seen as a cultural wasteland for rock music.","cn":""}]},"wash":{"media":{"uk":"media/uk/wash__gb_1.mp3","us":"media/us/wash__us_1.mp3"},"oxford":{"phon":"wɒʃ","pos":"verb","senses":[{"en":"to make something/somebody clean using water and usually soap","cn":"洗；洗涤","g":"[transitive]","ex":{"en":"These jeans need washing.","cn":"这条牛仔裤该洗了。"}},{"en":"to make yourself clean using water and usually soap","cn":"洗澡；洗脸；洗手","g":"[intransitive, transitive]","lab":"especially British English","ex":{"en":"By this time we were already washed and dressed.","cn":"到这个时候我们已经洗漱完毕、穿戴整齐。"}},{"en":"to be able to be washed without losing colour or being damaged","cn":"耐洗；洗后不褪色（或破损）","g":"[intransitive]","ex":{"en":"This sweater washes well.","cn":"这件套头衫很耐洗。"}},{"en":"to flow or carry something/somebody in a particular direction","cn":"（向着某一方向）流动；冲向","g":"[intransitive, transitive]","ex":{"en":"Water washed over the deck.","cn":"水从甲板上流过。"}},{"en":"an act of cleaning somebody/something using water and usually soap","cn":"洗；洗涤；清洗；洗刷","g":"[countable, usually singular]","lab":"especially British English","ex":{"en":"These towels are ready for a wash.","cn":"这些毛巾需要洗了。"},"pos":"noun"},{"en":"an area of water that has waves and is moving a lot, especially after a boat has moved through it; the sound made by this","cn":"（尤指船过后划出的）水流，波浪；波浪拍打声","g":"[singular]","ex":{"en":"The dinghy was rocked by the wash of a passing ferry.","cn":"驶过的渡船掀起的波浪把小艇冲得摇摇晃晃。"},"pos":"noun"},{"en":"a thin layer of a liquid, especially paint, that is put on a surface","cn":"薄涂层（尤指涂料）","g":"[countable]","ex":{"en":"The walls were covered with a pale yellow wash.","cn":"墙壁刷了一层薄的浅黄色涂料。"},"pos":"noun"},{"en":"a liquid containing soap, used for cleaning your skin","cn":"肥皂液","g":"[countable, uncountable]","ex":{"en":"an antiseptic skin wash","cn":"抗菌净肤液"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"洗涤;清洗","en":"If you wash something, you clean it using water and usually a substance such as soap or detergent.","ex":{"en":"He got a job washing dishes in a pizza parlour","cn":"他在比萨店里找到一份洗盘子的工作。"}},{"pos":"VERB 动词","cn":"洗;洗漱","en":"If you wash or if you wash part of your body, especially your hands and face, you clean part of your body using soap and water.","ex":{"en":"They looked as if they hadn't washed in days","cn":"他们看起来好像已经有好些天没洗澡了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(海水或河流)流动，冲刷，冲到","en":"If a sea or river washes somewhere, it flows there gently. You can also say that something carried by a sea or river washes or is washed somewhere.","ex":{"en":"The sea washed against the shore","cn":"海水冲刷着海岸。"}},{"pos":"N-SING 单数名词","cn":"(船只等激起的)浪花","en":"The wash of a boat is the wave that it causes on either side as it moves through the water.","ex":{"en":"...the wash from large ships.","cn":"大船激起的浪花"}},{"pos":"VERB 动词","cn":"(情感)强烈冲击","en":"If a feeling washes over you, you suddenly feel it very strongly and cannot control it.","ex":{"en":"A wave of self-consciousness can wash over her when someone new enters the room","cn":"一有陌生人进房间，她就感到极不自在。"}},{"pos":"N-COUNT 可数名词","cn":"（颜色、光线等的）薄层","en":"A wash of something such as light or colour is a thin layer of it.","ex":{"en":"The lights from the truck sent a wash of pale light over the snow.","cn":"卡车的车灯在雪地上洒下一层淡淡的光。"}},{"pos":"VERB 动词","cn":"令人信服;使人接受","en":"If you say that an excuse or idea will not wash, you mean that people will not accept or believe it.","ex":{"en":"He said her policies didn't work and the excuses didn't wash","cn":"他认为她的政策没有起到效果，而且理由也不能令人信服。"}},{"pos":"PHRASE 短语","cn":"真相大白;水落石出","en":"If you say that something will come out in the wash, you mean that people will eventually find out the truth about it.","ex":{"en":"This will all come out in the wash—I promise you.","cn":"一切终会真相大白的——我向你保证。"}},{"pos":"PHRASE 短语","cn":"正在洗着;将要洗;刚洗过","en":"If you say that something such as an item of clothing is in the wash, you mean that it is being washed, is waiting to be washed, or has just been washed and should therefore not be worn or used.","ex":{"en":"Your jeans are in the wash.","cn":"你的牛仔裤还在洗着呢。"}},{"pos":"","cn":"","en":"to wash your dirty linen in public→see: ; to wash your hands of something→see: ;"},{"pos":"","cn":"","en":"相关词组：wash away wash down wash out wash over wash up"}]},"examples":[{"en":"That blouse shouldn't look like that after only two washes.","cn":"那件女衬衫只洗过两水，不应该变成这个样子。"},{"en":"The dinghy was rocked by the wash of a passing ferry.","cn":"驶过的渡船掀起的波浪把小艇冲得摇摇晃晃。"}]},"waitresses":{"media":{"uk":"media/uk/waitress__gb_1.mp3","us":"media/us/waitress__us_1.mp3"}},"waitress":{"media":{"uk":"media/uk/waitress__gb_1.mp3","us":"media/us/waitress__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女侍者;女服务员","en":"A waitress is a woman who works in a restaurant, serving people with food and drink."},{"pos":"VERB 动词","cn":"做女侍者;当女服务员","en":"A woman who waitresses works in a restaurant serving food and drink.","ex":{"en":"She had been working in a pub, cooking and waitressing.","cn":"她之前在酒吧工作，负责烹饪和招待。"}}]},"oxford":{"phon":"ˈweɪtrəs","pos":"noun","senses":[{"en":"a woman whose job is to serve customers at their tables in a restaurant, etc.","cn":"（餐馆等的）服务员，侍者","lab":"British English","ex":{"en":"I'll ask the waitress for the bill.","cn":"我要让女服务员拿账单来。"}}]}},"warmth":{"media":{"uk":"media/uk/warmth__gb_1.mp3","us":"media/us/warmth__us_1.mp3"},"oxford":{"phon":"wɔːmθ","pos":"noun","senses":[{"en":"the state or quality of being warm, rather than hot or cold","cn":"温暖；暖和","ex":{"en":"She felt the warmth of his arms around her.","cn":"她感到了他双臂搂着她的温暖。"}},{"en":"the state or quality of being enthusiastic and/or friendly","cn":"热情；友情","ex":{"en":"They were touched by the warmth of the welcome.","cn":"他们受到了热情欢迎，很感动。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"温度;温暖;热度","en":"The warmth of something is the heat that it has or produces.","ex":{"en":"She went further into the room, drawn by the warmth of the fire","cn":"暖暖的炉火吸引着她继续向前走进那间屋子。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"保暖","en":"The warmth of something such as a garment or blanket is the protection that it gives you against the cold.","ex":{"en":"The blanket will provide additional warmth and comfort in bed.","cn":"毛毯能让你睡得更温暖、更舒适。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"热情;亲切；友好","en":"Someone who has warmth is friendly and enthusiastic in their behaviour towards other people.","ex":{"en":"He greeted us both with warmth and affection.","cn":"他热情且友好地迎接了我们俩。"}}]},"examples":[{"en":"He led the child into the warmth and safety of the house.","cn":"他把这孩子领到家里享受温暖和安全。"},{"en":"She felt the warmth of his arms around her.","cn":"她感到了他双臂搂着她的温暖。"}]},"was":{"media":{"uk":"media/uk/was__gb_1.mp3","us":"media/us/was__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"(be的第一和第三人称单数过去式）","en":"Was is the first and third person singular of the past tense of be ."}]}},"walk":{"media":{"uk":"media/uk/walk__gb_1.mp3","us":"media/us/walk__us_1.mp3"},"oxford":{"phon":"wɔːk","pos":"verb","senses":[{"en":"to move or go somewhere by putting one foot in front of the other on the ground, but without running","cn":"走；行走；步行","g":"[intransitive, transitive]","ex":{"en":"The baby is just learning to walk.","cn":"这孩子刚学走路。"}},{"en":"to spend time walking for pleasure","cn":"徒步旅行；散步","g":"[intransitive, transitive]","lab":"both especially British English","ex":{"en":"I like an active holiday, so I walk.","cn":"我喜欢活跃的假期，所以我步行。"}},{"en":"to go somewhere with somebody on foot, especially in order to make sure they get there safely","cn":"陪伴…走；护送…走","g":"[transitive]","ex":{"en":"He always walked her home.","cn":"他经常护送她走回家。"}},{"en":"to take an animal for a walk; to make an animal walk somewhere","cn":"牵着（动物）走；遛；赶着…走","g":"[transitive]","ex":{"en":"They walk their dogs every day.","cn":"他们每天遛狗。"}},{"en":"to disappear; to be taken away","cn":"没了；被偷","g":"[intransitive]","lab":"informal","ex":{"en":"Lock up any valuables. Things tend to walk here (= be stolen).","cn":"把贵重物品锁起来。这里的东西常会不翼而飞。"}},{"en":"to appear","cn":"出现；出没；显灵","g":"[intransitive]","lab":"literary"},{"en":"when a batsman walks, he/she leaves the field without waiting for the umpire to say that he/she is out","cn":"走路：当击球手走路时，他/她离开田野而无需等待裁判员说他/她不在","g":"[intransitive]","ex":{"en":"He knew he was out, so he walked.","cn":"他知道自己出去了，所以他就走了。"}},{"en":"to reach first base without having to do anything because the pitcher failed to throw the ball correctly four times and you didn't try to hit it; to enable a batter to walk","cn":"轻易获得；轻易取胜","g":"[intransitive, transitive]","ex":{"en":"He walked 60 times in 57 games.","cn":"他在 57 场比赛中保送了 60 次。"}},{"en":"a journey on foot, usually for pleasure or exercise","cn":"行走；步行；徒步旅行；散步","g":"[countable]","ex":{"en":"Let's go for a walk.","cn":"咱们去散散步吧。"},"pos":"noun"},{"en":"a path or route for walking, usually for pleasure; an organized event when people walk for pleasure","cn":"散步的小路；步行的路径；（为游玩而组织的）徒步旅行","g":"[countable]","ex":{"en":"I'm going on a sponsored walk to raise money for cancer research.","cn":"我要去参加一场有赞助的慈善徒步活动，为癌症研究募捐。"},"pos":"noun"},{"en":"a way or style of walking; the act or speed of walking rather than running","cn":"步态；步行；步行速度","g":"[singular]","ex":{"en":"I recognized him by his walk.","cn":"我根据他走路的样子认出了他。"},"pos":"noun"},{"en":"a sidewalk or path","cn":"人行道；小路","g":"[countable]","lab":"North American English","pos":"noun"},{"en":"a sports event in which people compete to walk a long distance as fast as possible without running","cn":"竞走","g":"[countable]","ex":{"en":"the 20k walk","cn":"20 公里竞走"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"走;行走;走路","en":"When you walk, you move forward by putting one foot in front of the other in a regular way.","ex":{"en":"Rosanna and Forbes walked in silence for some while","cn":"罗莎娜和福布斯默不作声地走了一会儿。"}},{"pos":"N-COUNT 可数名词","cn":"漫步;散步","en":"A walk is a journey that you make by walking, usually for pleasure.","ex":{"en":"I went for a walk","cn":"我去散步了。"}},{"pos":"N-SING 单数名词","cn":"步行的距离(或路程)","en":"A walk of a particular distance is the distance which a person has to walk to get somewhere.","ex":{"en":"It was only a three-mile walk to Kabul from there","cn":"从那里到喀布尔只需走上3英里。"}},{"pos":"N-COUNT 可数名词","cn":"步行小径;(适宜散步的)小径，道路","en":"A walk is a route suitable for walking along for pleasure.","ex":{"en":"There is a 2 mile coastal walk from Craster to Newton.","cn":"从克拉斯特到牛顿有一条两英里的海滨小径。"}},{"pos":"N-SING 单数名词","cn":"走;行走;步行","en":"A walk is the action of walking rather than running.","ex":{"en":"She slowed to a steady walk.","cn":"她放慢脚步，徐徐而行。"}},{"pos":"N-SING 单数名词","cn":"步态;走路的样子","en":"Someone's walk is the way that they walk.","ex":{"en":"George, despite his great height and gangling walk, was a keen dancer.","cn":"乔治尽管长得过高，走路姿势难看，但却热衷于跳舞。"}},{"pos":"VERB 动词","cn":"陪同;陪伴护送","en":"If you walk someone somewhere, you walk there with them in order to show politeness or to make sure that they get there safely.","ex":{"en":"She walked me to my car","cn":"她陪我走到我的车旁。"}},{"pos":"VERB 动词","cn":"遛(狗);带(狗)溜达","en":"If you walk your dog, you take it for a walk in order to keep it healthy.","ex":{"en":"I walk my dog each evening around my local streets.","cn":"我每晚在家附近的街道上遛狗。"}},{"pos":"","cn":"","en":"to be walking on air→see: ; to walk tall→see: ;"},{"pos":"","cn":"","en":"相关词组：walk away walk away with walk in on walk into walk off with walk out walk over"}]},"examples":[{"en":"She spent the morning padding about the house in her slippers.","cn":"她一个早上都穿着拖鞋在房子里轻轻地走来走去。"},{"en":"Lock up any valuables. Things tend to walk here (= be stolen).","cn":"把贵重物品锁起来。这里的东西常会不翼而飞。"}]},"wage":{"media":{"uk":"media/uk/wage__gb_1.mp3","us":"media/us/wage__us_1.mp3"},"oxford":{"phon":"weɪdʒ","pos":"noun","senses":[{"en":"a regular amount of money that you earn, usually every week or every month, for work or services","cn":"（通常按周或月领的）工资，工钱","lab":"British English also","ex":{"en":"wages of £300 a week","cn":"周薪 300 英镑"}},{"en":"to begin and continue a war, a battle, etc.","cn":"开始，发动，进行，继续（战争、战斗等）","ex":{"en":"The rebels have waged a guerrilla war since 2007.","cn":"叛乱分子自 2007 年以来一直在进行游击战。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工资;工钱","en":"Someone's wages are the amount of money that is regularly paid to them for the work that they do.","ex":{"en":"His wages have gone up","cn":"他涨工资了。"}},{"pos":"VERB 动词","cn":"开展，发动(运动或战争)","en":"If a person, group, or country wages a campaign or a war, they start it and continue it over a period of time.","ex":{"en":"...the three factions that had been waging a civil war","cn":"发动内战的三个派别"}}]},"examples":[{"en":"The rebels have waged a guerrilla war since 2007.","cn":"叛乱分子自 2007 年以来一直在进行游击战。"},{"en":"He alleged that a press campaign was being waged against him.","cn":"他声称有人正在对他发起新闻攻势。"}]},"warmed":{"oxford":{"phon":"wɔːm","pos":"adjective","senses":[{"en":"at a fairly high temperature in a way that is pleasant, rather than being hot or cold","cn":"温暖的；暖和的"},{"en":"keeping you warm or staying warm in cold weather","cn":"保暖的；保温的"}]}},"wages":{"oxford":{"phon":"weɪdʒ","pos":"noun","senses":[{"en":"a regular amount of money that you earn, usually every week, for work or services （","cn":"通常指按周领的）工资，工钱"},{"en":"to begin and continue a war, a battle, etc.","cn":"开始，发动，进行，继续（战争、战斗等）"}]}},"wants":{"oxford":{"phon":"wɒnt","pos":"verb","senses":[{"en":"to have a desire or a wish for sth","cn":"要；想要；希望"},{"en":"Notice that you cannot say ‘want that … ’.","cn":"注意不能说 want that ...："}]}},"waiters":{"oxford":{"phon":"ˈweɪtə(r)","pos":"noun","senses":[{"en":"a person whose job is to serve customers at their tables in a restaurant, etc. （","cn":"餐馆等的）服务员，侍者"}]}},"walkers":{"oxford":{"phon":"ˈwɔːkə(r)","pos":"noun","senses":[{"en":"( especially BrE ) a person who walks, usually for pleasure or exercise","cn":"步行者；散步的人；徒步旅行者"},{"en":"a person who walks fast, slow, etc.","cn":"走路快（或慢等）的人"}]}},"wanderers":{"oxford":{"phon":"ˈwɒndərə(r)","pos":"noun","senses":[{"en":"a person who keeps travelling from place to place with no permanent home","cn":"漂泊者；漫游者；流浪者"}]}},"wandered":{"oxford":{"phon":"ˈwɒndə(r)","pos":"verb","senses":[{"en":"to walk slowly around or to a place, often without any particular sense of purpose or direction","cn":"闲逛；漫游；游荡"},{"en":"to move away from the place where you ought to be or the people you are with","cn":"偏离（正道）；走失；离散"}]}},"waits":{"oxford":{"phon":"weɪt","pos":"verb","senses":[{"en":"to stay where you are or delay doing sth until sb/sth comes or sth happens","cn":"等；等待；等候"},{"en":"to hope or watch for sth to happen, especially for a long time （","cn":"尤指长期地）希望，盼望，期待"}]}},"watched":{"oxford":{"phon":"wɒtʃ","pos":"verb","senses":[{"en":"to look at sb/sth for a time, paying attention to what happens","cn":"看；注视；观看；观察"},{"en":"to take care of sb/sth for a short time （","cn":"短时间）照看，看护，照管"}]}},"walked":{"oxford":{"phon":"wɔːk","pos":"verb","senses":[{"en":"to move or go somewhere by putting one foot in front of the other on the ground, but without running","cn":"走；行走；步行"},{"en":"to spend time walking for pleasure","cn":"徒步旅行；散步"}]}},"waited":{"oxford":{"phon":"weɪt","pos":"verb","senses":[{"en":"to stay where you are or delay doing sth until sb/sth comes or sth happens","cn":"等；等待；等候"},{"en":"to hope or watch for sth to happen, especially for a long time （","cn":"尤指长期地）希望，盼望，期待"}]}},"warnings":{"oxford":{"phon":"ˈwɔːnɪŋ","pos":"noun","senses":[{"en":"a statement, an event, etc. telling sb that sth bad or unpleasant may happen in the future so that they can try to avoid it （","cn":"就可能发生的意外等提出的）警告，警示；先兆"},{"en":"a statement telling sb that they will be punished if they continue to behave in a particular way （","cn":"就将要遭受的处罚等提出的）警告，警戒"}]}},"walks":{"oxford":{"phon":"wɔːk","pos":"verb","senses":[{"en":"to move or go somewhere by putting one foot in front of the other on the ground, but without running","cn":"走；行走；步行"},{"en":"to spend time walking for pleasure","cn":"徒步旅行；散步"}]}},"wallets":{"oxford":{"phon":"ˈwɒlɪt","pos":"noun","senses":[{"en":"a small flat folding case made of leather or plastic used for keeping paper money and credit cards in （","cn":"放钞票、信用卡的）钱包，皮夹子"},{"en":"( BrE ) a flat leather, plastic or cardboard case for carrying documents in （","cn":"携带文件用的）皮夹，塑料夹，硬纸夹"}]}},"watches":{"oxford":{"phon":"wɒtʃ","pos":"verb","senses":[{"en":"to look at sb/sth for a time, paying attention to what happens","cn":"看；注视；观看；观察"},{"en":"to take care of sb/sth for a short time （","cn":"短时间）照看，看护，照管"}]}},"waters":{"oxford":{"phon":"ˈwɔːtə(r)","pos":"noun","senses":[{"en":"a liquid without colour, smell or taste that falls as rain, is in lakes, rivers and seas, and is used for drinking, washing, etc.","cn":"水"},{"en":"an area of water, especially a lake, river, sea or ocean","cn":"大片的水；水域；（尤指）江，河，湖，海"}]}},"warriors":{"oxford":{"phon":"ˈwɒriə(r)","pos":"noun","senses":[{"en":"(especially in the past) a person who fights in a battle or war （","cn":"尤指旧时的）武士，勇士，斗士"}]}},"walls":{"oxford":{"phon":"wɔːl","pos":"noun","senses":[{"en":"a long vertical solid structure, made of stone, brick or concrete, that surrounds, divides or protects an area of land","cn":"城墙；围墙"},{"en":"any of the vertical sides of a building or room","cn":"墙；壁；墙壁"}]}},"washed":{"oxford":{"phon":"wɒʃ","pos":"verb","senses":[{"en":"to make sth/sb clean using water and usually soap","cn":"洗；洗涤"},{"en":"( especially BrE ) to make yourself clean using water and usually soap","cn":"洗澡；洗脸；洗手"}]}},"waves":{"oxford":{"phon":"weɪv","pos":"noun","senses":[{"en":"a raised line of water that moves across the surface of the sea, ocean, etc.","cn":"海浪；波浪；波涛"},{"en":"a sudden increase in a particular activity or feeling","cn":"汹涌的行动（或思想）态势；心潮；风潮"}]}},"waddled":{"oxford":{"phon":"ˈwɒdl","pos":"verb","senses":[{"en":"to walk with short steps, swinging from side to side, like a duck （","cn":"鸭子似地）蹒跚行走，摇摆地行走"}]}},"watching":{"oxford":{"phon":"wɒtʃ","pos":"verb","senses":[{"en":"to look at sb/sth for a time, paying attention to what happens","cn":"看；注视；观看；观察"},{"en":"to take care of sb/sth for a short time （","cn":"短时间）照看，看护，照管"}]}},"waists":{"oxford":{"phon":"weɪst","pos":"noun","senses":[{"en":"the area around the middle of the body between the ribs and the hips, often narrower than the areas above and below","cn":"腰；腰部；腰围"},{"en":"the part of a piece of clothing that covers the waist （","cn":"衣服的）腰部，腰"}]}},"ways":{"oxford":{"phon":"weɪz","pos":"suffix","senses":[{"en":"in the direction of","cn":"在…方向（的）；朝…方向（的）","ex":{"en":"lengthways","cn":"纵向的"}}]}},"watered":{"oxford":{"phon":"ˈwɔːtə(r)","pos":"noun","senses":[{"en":"a liquid without colour, smell or taste that falls as rain, is in lakes, rivers and seas, and is used for drinking, washing, etc.","cn":"水"},{"en":"an area of water, especially a lake, river, sea or ocean","cn":"大片的水；水域；（尤指）江，河，湖，海"}]}},"wandering":{"oxford":{"phon":"ˈwɒndə(r)","pos":"verb","senses":[{"en":"to walk slowly around or to a place, often without any particular sense of purpose or direction","cn":"闲逛；漫游；游荡"},{"en":"to move away from the place where you ought to be or the people you are with","cn":"偏离（正道）；走失；离散"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"流浪的;漂泊的","en":"Wandering is used to describe people who travel around rather than staying in one place for a long time.","ex":{"en":"...a band of wandering musicians.","cn":"一群漂泊的音乐人"}}]}},"waterways":{"oxford":{"phon":"ˈwɔːtəweɪ","pos":"noun","senses":[{"en":"a river, canal , etc. along which boats can travel","cn":"水路；航道"}]}},"watercourse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"河道；运河；溪流","en":"A watercourse is a stream or river, or the channel that it flows along."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where water flows, for example a river or canal","cn":"水道﹔河道﹔渠道"},{"en":"a long thin hole for water to flow through","cn":"排水口"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41watercourse.mp3","us":"media/ldoce/hwd/ame/9/watercourse.mp3"},"examples":[{"en":"chemicals that pollute the local watercourse","cn":"污染当地河道的化学品"}],"oxford":{"phon":"ˈwɔːtəkɔːs","pos":"noun","senses":[{"en":"a stream or an artificial channel for water","cn":"河道；水道；沟渠；渠道","ex":{"en":"Our priority is to control pollution in direct discharges to watercourses.","cn":"我们的首要任务是控制直接排放到水道的污染。"}}]}},"wadding":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"软填料;填絮","en":"Wadding is soft material which is put around things to protect them, for example in packing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"soft material used for packing or to protect a wound","cn":"软填料﹔〔医用〕敷料"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41wadding.mp3","us":"media/ldoce/hwd/ame/a/wadding.mp3"},"oxford":{"phon":"ˈwɒdɪŋ","pos":"noun","senses":[{"en":"soft material that you wrap around things to protect them","cn":"（柔软的）填料，填絮，衬垫"}]}},"warship":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"军舰; 战船","en":"A warship is a ship with guns that is used for fighting in wars."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a military ship with guns, used in a war","cn":""},{"en":"the largest type of ship used in war, with very big guns on it","cn":""},{"en":"a military ship that planes can fly from or land on","cn":""}]},"collocations":{"phrases":["ADJ. modern | surface | naval | nuclear","QUANT. fleet","VERB + WARSHIP build | command | lose Germany lost two warships during this attack.","PREP. aboard/on/on board a ~ He is serving on a warship in the Pacific."]},"media":{"uk":"media/ldoce/hwd/bre/9/warship_las3_br.mp3","us":"media/ldoce/hwd/ame/e/warship.mp3"},"oxford":{"phon":"ˈwɔːʃɪp","pos":"noun","senses":[{"en":"a ship that has weapons and that is used in war","cn":"军舰；舰艇","ex":{"en":"A total of 18 warships were sunk or heavily damaged.","cn":"总共有 18 艘军舰被击沉或严重受损。"}}]}},"watercress":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"水田芥，水芥子(长于溪流或池塘中，叶子可作色拉生食)","en":"Watercress is a small plant with white flowers which grows in streams and pools. Its leaves taste hot and are eaten raw in salads."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small green plant with strong-tasting leaves that grows in water","cn":"豆瓣菜﹐西洋菜﹐水田芥〔水生植物﹐叶辛辣〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/watercress0205.mp3","us":"media/ldoce/hwd/ame/8/watercress.mp3"},"examples":[{"en":"a bunch of watercress","cn":"一把水田芥"}],"oxford":{"phon":"ˈwɔːtəkres","pos":"noun","senses":[{"en":"a water plant with small round green leaves and thin stems. It has a strong taste and is often eaten raw in salads.","cn":"水田芥，豆瓣菜，西洋菜（水生植物，有辛香味）"}]}},"watermark":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水印（常用于钞票上以防伪）","en":"A watermark is a design which is put into paper when it is made, and which you can only see if you hold the paper up to the light. Banknotes often have a watermark, to make them harder to copy illegally."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special design put onto paper, especially bank notes, that can only be seen when you hold it up to the light 〔","cn":"尤指纸币上的〕水印"},{"en":"a special mark contained in electronic documents, pictures, music etc that is used to stop people from copying them 〔","cn":"防止电子文件﹑图片﹑音乐等被复制的〕水印"},{"en":"the high watermark of a particular process is its most successful time or achievement","cn":"辉煌[鼎盛]时期"}]},"media":{"uk":"media/ldoce/hwd/bre/2/watermark0205.mp3","us":"media/ldoce/hwd/ame/0/watermark.mp3"},"examples":[{"en":"The sheet bears the watermark ‘1836’.","cn":"纸上有“1836”的水印。"},{"en":"The card has a digital watermark detectable only by electronic cash dispensers.","cn":"这种卡上带有只能被电子取款机识别的数码水印。"}],"oxford":{"phon":"ˈwɔːtəmɑːk","pos":"noun","senses":[{"en":"a symbol or design in some types of paper, which can be seen when the paper is held against the light","cn":"（纸张上的）水印"}]}},"wayside":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路边","en":"The wayside is the side of the road.","ex":{"en":"...groups of men playing cards by lamplight at the wayside.","cn":"在路边就着路灯玩牌的一群群人"}},{"pos":"PHRASE 短语","cn":"中途停止;半路夭折","en":"If a person or plan falls by the wayside, they fail or stop before they complete what they set out to do.","ex":{"en":"Amateurs fall by the wayside when the going gets tough","cn":"业余爱好者遇到困难时往往半途而废。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the side of a road","cn":"路边"}]},"media":{"uk":"media/ldoce/hwd/bre/1/wayside0205.mp3","us":"media/ldoce/hwd/ame/0/l3wayside.mp3"},"examples":[{"en":"wild flowers growing by the wayside","cn":"路旁长的野花"},{"en":"a wayside inn","cn":"路边的客店"}],"oxford":{"phon":"ˈweɪsaɪd","pos":"noun","senses":[{"en":"the area at the side of a road or path","cn":"路边；路旁","ex":{"en":"a wayside inn","cn":"路边的客店"}}]}},"wax":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"蜡","en":"Wax is a solid, slightly shiny substance made of fat or oil which is used to make candles and polish. It melts when it is heated.","ex":{"en":"There were coloured candles which had spread pools of wax on the furniture","cn":"彩色蜡烛在家具上留下一摊摊蜡油。"}},{"pos":"VERB 动词","cn":"给…上蜡","en":"If you wax a surface, you put a thin layer of wax onto it, especially in order to polish it.","ex":{"en":"We'd have long talks while she helped me wax the floor.","cn":"她帮我给地板打蜡时我们谈了很久。"}},{"pos":"VERB 动词","cn":"用蜡给（皮肤）除毛","en":"If you have your legs waxed, you have the hair removed from your legs by having wax put on them and then pulled off quickly.","ex":{"en":"She has just had her legs waxed at the local beauty parlour","cn":"她刚在当地一家美容院除了腿毛。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"耳垢;耳屎","en":"Wax is the sticky yellow substance found in your ears."},{"pos":"VERB 动词","cn":"畅谈","en":"If you say that someone, for example, waxes lyrical or waxes indignant about a subject, you mean that they talk about it in an enthusiastic or indignant way.","ex":{"en":"He waxed lyrical about the skills and commitment of his employees","cn":"他津津乐道于员工的技能和敬业精神。"}},{"pos":"PHRASE 短语","cn":"兴衰;盛衰","en":"If something waxes and wanes, it first increases and then decreases over a period of time.","ex":{"en":"Portugal and Spain had possessed vast empires that waxed and waned.","cn":"葡萄牙和西班牙都曾是经历了兴衰的大帝国。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a solid substance made of fat or oil and used to make candle s , polish etc","cn":"蜡"},{"en":"a natural sticky substance in your ears","cn":"耳垢"},{"en":"to rub a layer of wax into a floor, surface etc to protect it or make it shine","cn":"给…打蜡"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"The verb wax is most often found in the company of its opposite, \"wane.\" To wax is to grow larger or increase, whereas wane means to grow smaller or decrease."}]},"media":{"img":["media/ldoce/img/candle.jpg"],"uk":"media/ldoce/hwd/bre/d/brelasdewax.mp3","us":"media/ldoce/hwd/ame/4/wax1.mp3"},"examples":[{"en":"He waxed lyrical on the food at the new restaurant.","cn":"他对这家新餐馆的菜肴越说越来劲。"},{"en":"to wax your legs/to have your legs waxed","cn":"用蜡除去你腿上的毛"}],"oxford":{"phon":"wæks","pos":"noun","senses":[{"en":"a solid substance that is made from beeswax or from various fats and oils and used for making candles, polish, models, etc. It becomes soft when it is heated.","cn":"蜡；蜂蜡；动物蜡；植物蜡；石蜡","ex":{"en":"styling wax for the hair","cn":"定型发蜡"}},{"en":"a soft, sticky yellow-brown substance that is found in your ears","cn":"耳垢；耳屎"},{"en":"to polish something with wax","cn":"给…打蜡","g":"[transitive]","pos":"verb"},{"en":"to cover something with wax","cn":"给…上蜡；给…涂蜡","g":"[transitive, usually passive]","ex":{"en":"waxed paper","cn":"蜡纸"},"pos":"verb"},{"en":"to remove hair from a part of the body using wax","cn":"用蜡除去…上的毛","g":"[transitive, often passive]","ex":{"en":"to wax your legs/to have your legs waxed","cn":"用蜡除去你腿上的毛"},"pos":"verb"},{"en":"to seem to get gradually bigger until its full form can be seen","cn":"渐圆；渐满","g":"[intransitive]","pos":"verb"},{"en":"to become lyrical, etc. when speaking or writing","cn":"说话变得（热情、雄辩、伤感等）起来","g":"[intransitive]","lab":"formal","ex":{"en":"He waxed lyrical on the food at the new restaurant.","cn":"他对这家新餐馆的菜肴越说越来劲。"},"pos":"verb"}]}},"watchdog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"监察人(员);监察委员会","en":"A watchdog is a person or committee whose job is to make sure that companies do not act illegally or irresponsibly.","ex":{"en":"...an anti-crime watchdog group funded by New York businesses.","cn":"由纽约商界资助的反犯罪监察团体"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or group of people whose job is to protect the rights of people who buy things and to make sure companies do not do anything illegal or harmful 〔","cn":"保护购买者权利﹐确保公司不从事非法或有害活动的〕监察人员﹐监察委员会"},{"en":"a guard dog","cn":"看门狗"}]},"collocations":{"phrases":["ADJ. consumer | financial, health, industry, pollution, safety | government, independent, official","VERB + WATCHDOG act as, be","WATCHDOG + NOUN body, group, organization | role","PREP. ~ for a consumer watchdog for transport | ~ on the government's official watchdog on nature conservation | ~ over The committee acts a"]},"media":{"uk":"media/ldoce/hwd/bre/0/watchdog0205.mp3","us":"media/ldoce/hwd/ame/8/watchdog.mp3"},"examples":[{"en":"a consumer watchdog","cn":"消费者监察人"}],"oxford":{"phon":"ˈwɒtʃdɒɡ","pos":"noun","senses":[{"en":"a person or group of people whose job is to check that companies are not doing anything illegal or ignoring people’s rights","cn":"（监督公司活动及监护人们权利的）监察人，监察团体","ex":{"en":"She is a member of the consumer watchdog for transport in London and Southern England.","cn":"她是消费者监察团体的成员，监督伦敦和英格兰南部运输业。"}},{"en":"a dog that is kept to guard a building","cn":"看门狗"}]}},"warpath":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"盛怒并准备寻衅;大发脾气","en":"If you say that someone is or has gone on the warpath, you mean that they are angry and getting ready for a fight or conflict.","ex":{"en":"I had warned the children that daddy was on the warpath.","cn":"我警告过孩子们爸爸就要大发雷霆了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"so angry that it is difficult for you to think clearly or speak properly","cn":""},{"en":"extremely angry, but unable or unwilling to show it","cn":""},{"en":"extremely angry about something someone has done, and ready to react very strongly or violently","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A warpath is either the road to a battle or a hostile, agrressive mood. There's probably going to be trouble when someone is on either warpath ."}]},"media":{"uk":"media/ldoce/hwd/bre/3/warpath0205.mp3","us":"media/ldoce/hwd/ame/9/warpath.mp3"}},"warlord":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(国家或组织的)军阀式领袖，暴君","en":"If you describe a leader of a country or organization as a warlord, you are critical of them because they have achieved power by behaving in an aggressive and violent way.","ex":{"en":"He had been a dictator and a warlord who had oppressed and degraded the people of the South.","cn":"他既独裁又好战，压迫侮辱南方人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the leader of an unofficial military group fighting against a government, king, or different group","cn":"军阀"}]},"media":{"uk":"media/ldoce/hwd/bre/e/warlord0205.mp3","us":"media/ldoce/hwd/ame/3/warlord.mp3"},"oxford":{"phon":"ˈwɔːlɔːd","pos":"noun","senses":[{"en":"the leader of a military group that is not official and that fights against other groups within a country or an area","cn":"军阀"}]}},"watchman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"巡夜者;看守人","en":"A watchman is a person whose job is to guard a building or area."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to guard a place","cn":"守门人﹔警卫"}]},"media":{"uk":"media/ldoce/hwd/bre/3/watchman0205.mp3","us":"media/ldoce/hwd/ame/f/watchman.mp3"},"oxford":{"phon":"ˈwɒtʃmən","pos":"noun","senses":[{"en":"a man whose job is to guard a building, for example a bank, an office building or a factory, especially at night","cn":"（夜间）保安员，看守人，警卫员"}]}},"wally":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"笨蛋;傻瓜","en":"If you refer to someone as a wally, you think that they are stupid or foolish."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does something very stupid or embarrassing","cn":""},{"en":"someone who behaves in a stupid and annoying way","cn":""},{"en":"someone who is a little stupid and annoying, and who does not care if they upset or hurt other people","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/wally0205.mp3","us":"media/ldoce/hwd/ame/9/ld41wally.mp3"},"examples":[{"en":"Stop being such a wally!","cn":"别犯傻了！"}],"oxford":{"phon":"ˈwɒli","pos":"noun","senses":[{"en":"a stupid person","cn":"笨蛋；傻瓜"}]}},"waddle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"蹒跚行走;摇摇晃晃地行走","en":"To waddle somewhere means to walk there with short, quick steps, swinging slightly from side to side. A person or animal that waddles usually has short legs and a fat body.","ex":{"en":"McGinnis pushed himself laboriously out of the chair and waddled to the window","cn":"麦金尼斯吃力地从椅子上站起来，摇摇晃晃地走到了窗前。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk with short steps, with your body moving from one side to the other – used especially about people or birds with fat bodies and short legs 〔","cn":"尤指体胖腿短的人或鸟〕摇摇摆摆地走"}]},"vocab":{"pos":"v n","senses":[{"en":"A duck's walk is a waddle . To imitate it, turn your feet away from each other and take short clumsy steps that make you swing unsteadily from side to side."}]},"media":{"uk":"media/ldoce/hwd/bre/0/waddle0205.mp3","us":"media/ldoce/hwd/ame/5/waddle.mp3"},"examples":[{"en":"She walked with a waddle.","cn":"她走起路来步履蹒跚。"},{"en":"Half a dozen ducks waddled up the bank.","cn":"六只鸭子摇摇摆摆地上了岸。"}],"oxford":{"phon":"ˈwɒdl","pos":"noun","senses":[{"en":"a way of walking with short steps, moving your body from side to side, like a duck","cn":"（鸭子似的）蹒跚行走，摇摆地行走","ex":{"en":"She walked with a waddle.","cn":"她步履蹒跚。"}},{"en":"to walk with short steps, moving your body from side to side, like a duck","cn":"（鸭子似的）蹒跚行走，摇摆地行走","ex":{"en":"A short plump man came waddling towards me.","cn":"一个矮胖的男人摇摇晃晃地向我走来。"},"pos":"verb"}]}},"walkover":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"轻易取得的胜利；一边倒的比赛","en":"If you say that a competition or contest is a walkover, you mean that it is won very easily."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which you win a battle, game, election, or dispute","cn":""},{"en":"a victory in a sports game or in a competition","cn":""},{"en":"an important victory, especially in war or politics","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41walkover.mp3","us":"media/ldoce/hwd/ame/a/walkover.mp3"},"oxford":{"phon":"ˈwɔːkəʊvə(r)","pos":"noun","senses":[{"en":"an easy victory in a game or competition","cn":"（比赛或竞赛中的）轻易取得的胜利","ex":{"en":"The game was a walkover for the visiting team.","cn":"这场比赛客队轻松获胜。"}},{"en":"a victory given to a player or team because their opponent did not take part","cn":"（因对手无法参赛的）不战而胜"}]}},"waterwheel":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large wheel that is turned by water and is used to drive machinery 〔","cn":"用于驱动机器的〕水轮﹐水车"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41waterwheel.mp3","us":"media/ldoce/hwd/ame/5/ld41waterwheel.mp3"},"oxford":{"phon":"ˈwɔːtəwiːl","pos":"noun","senses":[{"en":"a wheel turned by the movement of water, used, especially in the past, to drive machines","cn":"（尤指旧时的）水轮，水车"}]}},"walkway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(常高于地面的)人行道，通道","en":"A walkway is a passage or path for people to walk along. Walkways are often raised above the ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an outdoor path built for people to walk along, often above the ground","cn":"人行通道﹐连廊〔建于户外﹐常高出地面〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/walkway0205.mp3","us":"media/ldoce/hwd/ame/d/walkway.mp3"},"examples":[{"en":"The airport hotel will be linked to the terminal building by a covered walkway.","cn":"机场酒店将由一条有顶通道和航站楼相连。"}],"oxford":{"phon":"ˈwɔːkweɪ","pos":"noun","senses":[{"en":"a passage or path for walking along, often outside and raised above the ground","cn":"（常为户外高出地面的）人行通道，走道","ex":{"en":"A covered walkway joins the two buildings.","cn":"一条有顶蓬的走道将两座建筑连接起来。"}}]}},"wartime":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"战时;战争时期","en":"Wartime is a period of time when a war is being fought.","ex":{"en":"The government will commandeer ships only in wartime.","cn":"政府只会在战争期间征募船只。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"during or relating to the time when there is a war","cn":""},{"en":"the time when there is a war","cn":""},{"en":"during the particular war that you are talking about","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/wartime0205.mp3","us":"media/ldoce/hwd/ame/7/wartime.mp3"},"examples":[{"en":"Fruit was a luxury in wartime Britain.","cn":"在战时的英国，水果是一种奢侈品。"},{"en":"Different rules applied in wartime.","cn":"战时实施不同的规定。"}],"oxford":{"phon":"ˈwɔːtaɪm","pos":"noun","senses":[{"en":"the period during which a country is fighting a war","cn":"战时","ex":{"en":"Different rules applied in wartime.","cn":"战时实施不同的规定。"}},{"en":"from or connected with a period during which a country is fighting a war","cn":"战时","ex":{"en":"Fruit was a luxury in wartime Britain.","cn":"在战时的英国，水果是奢侈品。"},"pos":"adjective"}]}},"wallflower":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"桂竹香","en":"A wallflower is a plant that is grown in gardens and has sweet-smelling yellow, red, orange, or purple flowers."},{"pos":"N-COUNT 可数名词","cn":"墙花(在社交场合因害羞而没有舞伴或不与人交谈的人）","en":"If you say that someone is a wallflower, you mean that they are shy and do not get involved in dancing or talking to people at social events.","ex":{"en":"I was something of a wallflower; I was terribly shy.","cn":"我算是朵墙花，因为我特别害羞。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone at a party, dance etc who is not asked to dance or take part in the activities","cn":"壁花〔指在聚会﹑舞会等中没被邀请跳舞或参加活动的人〕"},{"en":"a sweet-smelling garden plant with yellow and red flowers","cn":"桂竹香〔庭园植物﹐气味清香﹐开黄色和红色的花〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41wallflower.mp3","us":"media/ldoce/hwd/ame/8/wallflower.mp3"},"oxford":{"phon":"ˈwɔːlflaʊə(r)","pos":"noun","senses":[{"en":"a garden plant with yellow, orange or red flowers with a sweet smell that appear in late spring","cn":"桂竹香（一种园艺植物，暮春开花，呈黄、橙或红色）"},{"en":"a person who does not dance at a party because they do not have somebody to dance with or because they are too shy","cn":"（舞会或聚会上因无舞伴或腼腆）待在一旁的人，壁花","lab":"informal"}]}},"wasted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"徒劳的;无用的","en":"A wasted action is one that is unnecessary.","ex":{"en":"I'm sorry you had a wasted journey.","cn":"非常抱歉让你白跑了一趟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(常指因病而)憔悴的，疲惫不堪的","en":"Someone who is wasted is very tired and weak, often because of an illness.","ex":{"en":"They look too wasted to care about much.","cn":"他们看上去疲惫不堪,以至于顾不上太多。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very drunk and very noisy","cn":""},{"en":"very drunk","cn":""},{"en":"very drunk","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdewasted.mp3","us":"media/ldoce/hwd/ame/f/wasted.mp3"},"examples":[{"en":"We had a wasted trip — they weren't in.","cn":"我们白跑了一趟，他们不在。"},{"en":"thin wasted legs","cn":"枯瘦的双腿"}],"oxford":{"phon":"ˈweɪstɪd","pos":"adjective","senses":[{"en":"unsuccessful because it does not produce the result you wanted","cn":"徒劳无功的；白费的","g":"[only before noun]","ex":{"en":"We had a wasted trip—they weren't in.","cn":"我们白跑了一趟，他们不在。"}},{"en":"too thin, especially because of illness","cn":"（尤指因病）瘦骨嶙峋的，瘦弱的","ex":{"en":"thin wasted legs","cn":"枯瘦的双腿"}},{"en":"strongly affected by alcohol or drugs","cn":"极度迷醉的","lab":"slang"}]}},"wafer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"威化饼，薄脆饼(常与冰激凌同吃)","en":"A wafer is a thin crisp biscuit which is usually eaten with ice cream."},{"pos":"N-COUNT 可数名词","cn":"(基督教圣餐仪式上牧师发放的)圣饼","en":"A wafer is a circular, thin piece of special bread which the priest gives people to eat in the Christian service of Holy Communion."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very thin biscuit","cn":"威化饼干﹐薄脆饼"},{"en":"a thin round piece of bread eaten with wine in the Christian communion ceremony 〔","cn":"基督教圣餐仪式上用的〕圣饼"},{"en":"a very thin flat piece of a hard substance 〔","cn":"坚硬物质的〕薄片"}]},"media":{"uk":"media/ldoce/hwd/bre/4/wafer0205.mp3","us":"media/ldoce/hwd/ame/6/wafer.mp3"},"examples":[{"en":"wafers of silicon","cn":"硅片"}],"oxford":{"phon":"ˈweɪfə(r)","pos":"noun","senses":[{"en":"a thin, light biscuit, often eaten with ice cream","cn":"威化饼，薄脆饼（常与冰激凌同吃）","ex":{"en":"The sundae was topped with chocolate and a wafer.","cn":"圣代上面放着巧克力和威化饼。"}},{"en":"a very thin round piece of special bread given by the priest during Communion","cn":"圣饼；圣体；面饼"},{"en":"a very thin piece of something","cn":"薄片"}]}},"waterside":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"水边;河畔；湖滨；海滨","en":"The waterside is the area beside a stretch of water such as a river or lake.","ex":{"en":"Her garden stretches down to the waterside.","cn":"她的花园一直延伸到河畔。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the area at the edge of a lake, river etc","cn":"水边﹔湖边﹔河边"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41waterside.mp3","us":"media/ldoce/hwd/ame/5/waterside.mp3"},"examples":[{"en":"They strolled down to the waterside.","cn":"他们漫步向水边走去。"},{"en":"a waterside cafe","cn":"一家水滨小餐馆"}],"oxford":{"phon":"ˈwɔːtəsaɪd","pos":"noun","senses":[{"en":"the area at the edge of a river, lake, etc.","cn":"水边；河边；湖滨；海滨","ex":{"en":"They strolled down to the waterside.","cn":"他们漫步向水边走去。"}}]}},"warm-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"准备活动;热身活动","en":"A warm-up is something that prepares you for an activity or event, usually because it is a short practice or example of what the activity or event will involve.","ex":{"en":"The exercises can be fun and a good warm-up for the latter part of the programme","cn":"这些练习很有趣，而且为该课程后面的部分做了很好的铺垫。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of gentle exercises you do to prepare your body for sport, dancing etc 〔","cn":"运动﹑跳舞等前做的〕热身运动﹐准备活动"},{"en":"clothes that you wear when you are doing exercises to prepare your body for playing a sport or dancing","cn":"热身运动服"},{"en":"a warm-up match, game, or race is held to give the sportsmen or players practice before a big event 〔","cn":"比赛〕热身的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/warm_up_n0205.mp3","us":"media/ldoce/hwd/ame/8/warm-up.mp3"},"examples":[{"en":"warm-up exercises","cn":"热身练习"},{"en":"a warm-up act","cn":"暖场表演"}],"oxford":{"phon":"ˈwɔːm ʌp","pos":"noun","senses":[{"en":"a short practice or a series of gentle exercises that you do to prepare yourself for doing a particular sport or activity","cn":"（体育运动等前的）适应性活动，准备活动；热身练习","ex":{"en":"warm-up exercises","cn":"热身练习"}},{"en":"a short performance of music, comedy, etc. that is intended to prepare the audience for the main show","cn":"暖场表演（正式表演开始前上演的短小音乐、喜剧等节目）","ex":{"en":"a warm-up act","cn":"暖场表演"}}]}},"wagtail":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鹡鸰","en":"A wagtail is a type of small bird which moves its tail quickly up and down as it walks."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small European bird that moves its tail quickly up and down when it walks","cn":"鹡鸰〔一种欧洲小鸟﹐行走时尾巴上下快速摆动〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41wagtail.mp3","us":"media/ldoce/hwd/ame/2/ld41wagtail.mp3"},"oxford":{"phon":"ˈwæɡteɪl","pos":"noun","senses":[{"en":"a small bird with a long tail that moves up and down when the bird is walking","cn":"鹡鸰（走动时长尾上下摆动）"}]}},"wattle":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(用以编筑篱笆及围墙的)枝条构架","en":"Wattle is a framework made by weaving thin sticks through thick sticks which is used for making fences and walls.","ex":{"en":"...the native huts of mud and wattle.","cn":"当地用泥巴和枝条盖起的小屋"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a frame made from sticks woven together","cn":"编条结构"},{"en":"the red flesh that grows on the head or neck of some birds, such as chickens 〔","cn":"某些禽类头部或颈部的〕红色肉垂"}]},"media":{"uk":"media/ldoce/hwd/bre/5/wattle0205.mp3","us":"media/ldoce/hwd/ame/0/wattle.mp3"},"examples":[{"en":"walls made of wattle and daub","cn":"泥笆墙"},{"en":"walls made of wattle and daub (= this frame covered with clay )","cn":"抹灰篱笆墙"}],"oxford":{"phon":"ˈwɒtl","pos":"noun","senses":[{"en":"sticks woven together as a material for making fences, walls, etc.","cn":"编条结构（用于编筑篱笆、围墙等）","g":"[uncountable]","ex":{"en":"walls made of wattle and daub","cn":"泥笆墙"}},{"en":"a piece of red skin that hangs down from the throat of a bird such as a turkey","cn":"（火鸡等禽类喉部的）红色肉垂","g":"[countable]"},{"en":"a name for various types of acacia tree","cn":"金合欢树","g":"[countable, uncountable]","lab":"especially Australian English"}]}},"waterway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"运河;水路;航道","en":"A waterway is a canal, river, or narrow channel of sea which ships or boats can sail along."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a river or canal that boats travel on","cn":"水路﹐航道"}]},"media":{"uk":"media/ldoce/hwd/bre/c/waterway0205.mp3","us":"media/ldoce/hwd/ame/8/waterway.mp3"},"examples":[{"en":"a navigable waterway","cn":"可通航的水路"},{"en":"inland waterways","cn":"内河航道"}],"oxford":{"phon":"ˈwɔːtəweɪ","pos":"noun","senses":[{"en":"a river, canal, etc. along which boats can travel","cn":"水路；航道","ex":{"en":"inland waterways","cn":"内河航道"}}]}},"wavy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)微卷的","en":"Wavy hair is not straight or curly, but curves slightly.","ex":{"en":"She had short, wavy brown hair.","cn":"她留着微卷的褐色短发。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"波纹状的;波浪形的","en":"A wavy line has a series of regular curves along it.","ex":{"en":"The boxes were decorated with a wavy gold line.","cn":"这些盒子上饰有波浪形的金边。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"no longer straight","cn":""},{"en":"having a bent shape that turns around – used especially when something has been damaged or is old and has lost its natural straight shape","cn":""},{"en":"bent in the shape of part of a circle, especially naturally or because something has been made that way","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/wavy0205.mp3","us":"media/ldoce/hwd/ame/b/wavy.mp3","img":["media/thumb/wavy.jpg"]},"examples":[{"en":"a pattern of wavy lines","cn":"波浪形线条图案"},{"en":"brown wavy hair","cn":"棕色鬈发"}],"oxford":{"phon":"ˈweɪvi","pos":"adjective","senses":[{"en":"having curves; not straight","cn":"起伏不平的；波浪形的；拳曲的","ex":{"en":"brown wavy hair","cn":"棕色波浪发"}}]}},"walkabout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(国王、女王或其他要人为亲近民众在公共场所进行的)巡行","en":"A walkabout is a walk by a king, queen, or other important person through a public place in order to meet people in an informal way.","ex":{"en":"He was ambushed by angry protesters during a walkabout in Bolton.","cn":"他在博尔顿巡行时遭到愤怒的抗议者的围攻。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when an important person walks through a crowd, talking informally to people 〔","cn":"重要人物〕深入群众闲话家常"},{"en":"to get lost – used humorously","cn":"消失﹐不翼而飞〔幽默用法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41walkabout.mp3","us":"media/ldoce/hwd/ame/a/ld41walkabout.mp3"},"examples":[{"en":"My rucksack seems to have gone walkabout.","cn":"我的旅行包好像是丢了。"},{"en":"The press conference was followed by a walkabout and a factory visit.","cn":"新闻发布会之后是亲民活动和参观工厂。"}],"oxford":{"phon":"ˈwɔːkəbaʊt","pos":"noun","senses":[{"en":"an occasion when an important person walks among ordinary people to meet and talk to them","cn":"（要人的）出巡","lab":"British English","ex":{"en":"The prince met local people during a walkabout in Glasgow’s George Square.","cn":"王子在格拉斯哥乔治广场出巡时遇到了当地人。"}},{"en":"a traditional journey (originally on foot) in Australian Aboriginal culture, made as part of the process of becoming an adult","cn":"（澳洲土著为过传统生活而进行的）短期丛林流浪","lab":"Australian English"}]}},"watermelon":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"西瓜","en":"A watermelon is a large round fruit with green skin, pink flesh, and black seeds."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large round fruit with hard green skin, red flesh, and black seeds","cn":"西瓜"}]},"media":{"uk":"media/ldoce/hwd/bre/5/watermelon0205.mp3","us":"media/ldoce/hwd/ame/a/watermelon.mp3","img":["media/thumb/watermelon.jpg"]},"oxford":{"phon":"ˈwɔːtəmelən","pos":"noun","senses":[{"en":"a type of large melon, with hard, dark-green skin, that is red inside and has black seeds","cn":"西瓜"}]}},"waken":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"醒来;唤醒","en":"When you waken, or when someone or something wakens you, you wake from sleep.","ex":{"en":"The noise of a door slamming wakened her","cn":"砰的摔门声把她吵醒了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to wake up, or to wake someone up","cn":"醒来﹔唤醒﹐弄醒"}]},"media":{"uk":"media/ldoce/hwd/bre/b/waken0205.mp3","us":"media/ldoce/hwd/ame/2/waken.mp3"},"examples":[{"en":"The dream wakened a forgotten memory.","cn":"那梦唤起了一段忘却的记忆。"},{"en":"I was wakened by a knock at the door.","cn":"敲门声把我吵醒了。"}],"oxford":{"phon":"ˈweɪkən","pos":"verb","senses":[{"en":"to wake, or make somebody wake, from sleep","cn":"醒来；睡醒；唤醒；弄醒","g":"[intransitive, transitive]","ex":{"en":"The child had just wakened.","cn":"这孩子刚醒。"}},{"en":"to make somebody remember something or feel something again","cn":"唤起（记忆）；使再次感觉到","g":"[transitive]","ex":{"en":"The dream wakened a forgotten memory.","cn":"那梦唤起了一段忘却的记忆。"}}]}},"warren":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兔子窝","en":"A warren is a group of holes in the ground which are connected by tunnels and which rabbits live in."},{"pos":"N-COUNT 可数名词","cn":"过道狭窄的建筑;街道狭窄而密集的街区","en":"If you describe a building or an area of a city as a warren, you mean that there are many narrow passages or streets.","ex":{"en":"...a warren of narrow streets.","cn":"狭窄拥挤的街道"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the underground home of rabbits 〔","cn":"地下的〕兔穴"},{"en":"a place with so many streets, rooms etc that it is difficult to find the place that you want 〔","cn":"因街道﹑房间等过多而〕迷宫似的地方"}]},"vocab":{"pos":"n","senses":[{"en":"When Bugs Bunny outruns Elmer Fudd and vanishes down his rabbit hole, he's escaping into a warren — a network of underground tunnels where rabbits live."}]},"media":{"uk":"media/ldoce/hwd/bre/f/warren0205.mp3","us":"media/ldoce/hwd/ame/7/warren.mp3"},"examples":[{"en":"( figurative ) The offices were a warren of small rooms and passages.","cn":"这些办公室房间小，通道窄。"},{"en":"a warren of tiny streets","cn":"地下迷宫似的狭窄街巷"}],"oxford":{"phon":"ˈwɒrən","pos":"noun","senses":[{"en":"a system of holes and underground tunnels where wild rabbits live","cn":"野兔繁殖区（由地下交错相连的洞穴组成）"},{"en":"a building or part of a city with many narrow passages or streets","cn":"有许多狭小通道的建筑；街道狭窄而密集的城区","lab":"disapproving","ex":{"en":"The offices were a warren of small rooms and passages.","cn":"这些办公室房间小，通道窄。"}},{"en":"a first name for boys","cn":"沃伦（男子名）","pos":""}]}},"watershed":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"转折点;分水岭","en":"If something such as an event is a watershed in the history or development of something, it is very important because it represents the beginning of a new stage in it.","ex":{"en":"The election of Mary Robinson in 1990 was a watershed in Irish politics","cn":"1990年玛丽·鲁宾逊的当选是爱尔兰政治上的一个转折点。"}},{"pos":"N-COUNT 可数名词","cn":"(成人电视节目播出前的)分水岭时间","en":"The watershed is a time before which television broadcasters have agreed not to show programmes unsuitable for children, for example programmes that contain scenes of sex or violence.","ex":{"en":"Bad language before the watershed is widely resented","cn":"在成人节目时间之前出现的脏话深为众人憎恶。"}},{"pos":"N-COUNT 可数名词","cn":"分水线；分水岭","en":"A watershed is an area of high ground which divides two or more river systems, so that all streams on one side flow into one river and those on the other side flow into a different river."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an event or time when important changes happen in history or in your life 〔","cn":"历史或人生的〕转折点﹐重要关头"},{"en":"the time in the evening after which television programmes that are not considered suitable for children may be shown in Britain （9","cn":"点钟）分水线〔英国晚间允许成人电视节目播放的起始时间〕"},{"en":"the high land separating two river systems","cn":"分水岭﹐分水线"}]},"vocab":{"pos":"n","senses":[{"en":"A watershed is a turning point, or historic moment. The day you got your braces off might have been a watershed moment in your life."}]},"collocations":{"phrases":["ADJ. important, major, significant | cultural, historical, political","VERB + WATERSHED be, mark, represent | reach","WATERSHED + VERB divide sth Darwin's theory of evolution was a watershed dividing the old way of thinking from the new.","PREP. ~ between The 19th century marked a watershed between the country's agricultural past and its industrial future. | ~ for The granting "]},"media":{"uk":"media/ldoce/hwd/bre/b/watershed0205.mp3","us":"media/ldoce/hwd/ame/3/watershed.mp3"},"examples":[{"en":"The middle decades of the 19th century marked a watershed in Russia's history. * 19","cn":"世纪中叶标志着俄国历史的转折点。"},{"en":"the 9 o'clock watershed","cn":"可开播儿童不宜电视节目的晚上 9 点钟时限"}],"oxford":{"phon":"ˈwɔːtəʃed","pos":"noun","senses":[{"en":"an event or a period of time that marks an important change","cn":"转折点，分界线，分水岭（标志着重大变化的事件或时期）","g":"[countable]","ex":{"en":"The middle decades of the 19th century marked a watershed in Russia's history.","cn":"19 世纪中叶标志着俄国历史的转折点。"}},{"en":"a line of high land where streams on one side flow into one river, and streams on the other side flow into a different river","cn":"分水线；分水岭；分水界","g":"[countable]"},{"en":"(in the UK) the time before which programmes that are not considered suitable for children may not be shown on television","cn":"（英国）儿童不宜节目可在电视上播放的起始时间","g":"[singular]","ex":{"en":"the 9 o’clock watershed","cn":"可播放儿童不宜电视节目的晚上 9 点钟时限"}}]}},"waxwork":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指名人的）蜡像","en":"A waxwork is a model of a person, especially a famous person, made out of wax."},{"pos":"N-COUNT 可数名词","cn":"（名人）蜡像馆","en":"A waxworks is a place where waxworks are displayed for the public to look at. Waxworks is both the singular and the plural form."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where you can see models of famous people made of wax 〔","cn":"名人〕蜡像馆"},{"en":"a wax model of a person","cn":"蜡像"}]},"media":{"uk":"media/ldoce/hwd/bre/c/waxwork0205.mp3","us":"media/ldoce/hwd/ame/1/laadwaxwork.mp3"},"oxford":{"phon":"ˈwækswɜːk","pos":"noun","senses":[{"en":"a model of a person that is made of wax","cn":"蜡像；蜡人"},{"en":"a museum where you can see wax models of famous people","cn":"蜡像馆","lab":"especially British English"}]}},"watery":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"微弱的;淡薄的;无力的","en":"Something that is watery is weak or pale.","ex":{"en":"A watery light began to show through the branches","cn":"一缕微弱的光线透过树枝。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"水分过多;(味)太淡的","en":"If you describe food or drink as watery, you dislike it because it contains too much water, or has no flavour.","ex":{"en":"...a plateful of watery soup.","cn":"一盘寡淡无味的汤"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"含水的;似水的;由水组成的","en":"Something that is watery contains, resembles, or consists of water.","ex":{"en":"There was a watery discharge from her ear","cn":"她耳朵里流出水样分泌物。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a thin liquid flows very easily - use this about liquids that are often thick","cn":""},{"en":"food that is runny is liquid but should be thicker than it is","cn":""},{"en":"food or drink that is watery contains too much water, so that it does not taste or look good","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/watery0205.mp3","us":"media/ldoce/hwd/ame/0/watery.mp3"},"examples":[{"en":"( literary ) She was rescued from a watery grave (= saved from drowning ).","cn":"她从龙王爷那里被救了回来。"},{"en":"His eyes were red and watery.","cn":"他两眼发红，泪水汪汪。"}],"oxford":{"phon":"ˈwɔːtəri","pos":"adjective","senses":[{"en":"of or like water; containing a lot of water","cn":"水的；似水的；含水的；水分很多的","lab":"literary","ex":{"en":"a watery fluid","cn":"稀薄的流体"}},{"en":"weak and/or pale","cn":"虚弱的；苍白无力的","ex":{"en":"a watery sun","cn":"惨淡的太阳"}},{"en":"containing too much water; thin and having no taste","cn":"水分过多的；稀薄无味的","ex":{"en":"The vegetables were watery and tasteless.","cn":"蔬菜水汪汪的，没有味道。"}}]}},"wastebasket":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 wastepaper basket","en":"A wastebasket is the same as a wastepaper basket ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small container for holding paper, cans etc that are not wanted","cn":"废纸篓"}]},"media":{"img":["media/ldoce/img/wastepaper_bin.jpg"],"uk":"media/ldoce/hwd/bre/1/brelasdewastebasket.mp3","us":"media/ldoce/hwd/ame/0/wastebasket.mp3"},"oxford":{"phon":"ˈweɪstbɑːskɪt","pos":"noun","senses":[{"en":"a basket or other container for waste paper, etc.","cn":"废纸篓；废纸箱","ex":{"en":"She threw the letter into the wastebasket.","cn":"她将信扔进废纸篓。"}}]}},"waxy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"似蜡的;光滑的","en":"Something that is waxy looks or feels like wax.","ex":{"en":"Choose small waxy potatoes for the salad.","cn":"选些个头小、表皮光滑的土豆做色拉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"like wax , or made of wax","cn":"似蜡的﹔蜡制的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/waxy0205.mp3","us":"media/ldoce/hwd/ame/8/waxy.mp3"},"examples":[{"en":"the waxy blossoms of the water lily","cn":"睡莲那如蜡一般晶莹的花朵"},{"en":"young men with waxy faces","cn":"面如白蜡的青年男子"}],"oxford":{"phon":"ˈwæksi","pos":"adjective","senses":[{"en":"made of wax; looking or feeling like wax","cn":"蜡制的；似蜡的；质地光滑的","ex":{"en":"The cheese has a red waxy rind.","cn":"这种干酪有一层红色光滑外皮。"}}]}},"wanderer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"流浪汉;闲逛者","en":"A wanderer is a person who travels around rather than settling in one place."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person who moves from place to place and has no permanent home","cn":"漂泊者﹐流浪者"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41wanderer.mp3","us":"media/ldoce/hwd/ame/4/ld41wanderer.mp3"},"oxford":{"phon":"ˈwɒndərə(r)","pos":"noun","senses":[{"en":"a person who keeps travelling from place to place with no permanent home","cn":"漂泊者；漫游者；流浪者","ex":{"en":"‘So, I see the wanderer has returned!’ he sneered.","cn":"“所以，我看到流浪者回来了！”他冷笑道。"}}]}},"wand":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同magic wand","en":"A wand is the same as a magic wand .","ex":{"en":"You can't simply wave a wand and get rid of nuclear weapons.","cn":"你们不要以为魔杖一挥便能消除核武器。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin stick that you hold in your hand to do magic tricks 〔","cn":"表演魔术用的〕魔棒"},{"en":"a tool that looks like a thin stick","cn":"细棒状工具"},{"en":"to move a small scanner over something or someone 〔","cn":"用扫描器〕扫描"}]},"media":{"img":["media/ldoce/img/magician.jpg"],"uk":"media/ldoce/hwd/bre/c/wand0205.mp3","us":"media/ldoce/hwd/ame/7/wand.mp3"},"examples":[{"en":"You can't expect me to just wave a (magic) wand and make everything all right again.","cn":"你不能指望我挥动一下魔杖，便一切又平安无事了。"},{"en":"The fairy waved her wand and the table disappeared.","cn":"那仙女魔杖一挥，桌子不翼而飞。"}],"oxford":{"phon":"wɒnd","pos":"noun","senses":[{"en":"a straight, thin stick that is held by somebody when performing magic or magic tricks","cn":"魔杖","ex":{"en":"The fairy waved her wand and the table disappeared.","cn":"那仙女魔杖一挥，桌子不翼而飞。"}},{"en":"any object in the shape of a straight, thin stick","cn":"棍；棒；杆；杖","ex":{"en":"a mascara wand","cn":"睫毛刷"}}]}},"warring":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"交战的;敌对的;冲突的","en":"Warring is used to describe groups of people who are involved in a conflict or quarrel with each other.","ex":{"en":"The warring factions have not yet turned in all their heavy weapons.","cn":"敌对双方尚未将其重型武器悉数上缴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to take part in a war or battle","cn":""},{"en":"if two armies or groups clash , they suddenly start fighting each other, especially for a short time - used especially in news reports:","cn":""},{"en":"if two countries are at war with each other, they are fighting a war against each other","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/warring0205.mp3","us":"media/ldoce/hwd/ame/0/warring.mp3"},"examples":[{"en":"A ceasefire has been agreed by the country's three warring factions.","cn":"这个国家的交战三方已达成停火协议。"}],"oxford":{"phon":"ˈwɔːrɪŋ","pos":"adjective","senses":[{"en":"involved in a war","cn":"战争的；交战的；敌对的","ex":{"en":"A ceasefire has been agreed by the country's three warring factions.","cn":"这个国家的交战三方已达成停火协议。"}}]}},"washcloth":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"毛巾;面巾","en":"A washcloth is a small cloth that you use for washing yourself."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small square cloth used for washing your hands and face 〔","cn":"洗脸和洗手用的〕毛巾"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41washcloth.mp3","us":"media/ldoce/hwd/ame/6/washcloth.mp3"},"oxford":{"phon":"ˈwɒʃklɒθ","pos":"noun","senses":[{"en":"a small piece of cloth used for washing yourself","cn":"（洗擦身体用的）小毛巾","ex":{"en":"She wiped his forehead with a wet washcloth.","cn":"她用湿毛巾擦他的额头。"}}]}},"washroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盥洗室;洗手间","en":"A washroom is a room with toilets and washing facilities, situated in a large building such as a factory or an office block."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room containing a toilet","cn":""},{"en":"a toilet, especially in someone's house","cn":""},{"en":"a toilet","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/washroom0205.mp3","us":"media/ldoce/hwd/ame/5/washroom.mp3"},"oxford":{"phon":"ˈwɒʃruːm","pos":"noun","senses":[{"en":"a toilet, especially one that is in a public building","cn":"（尤指公共建筑物内的）洗手间，厕所"}]}},"wardrobe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"衣柜;衣橱","en":"A wardrobe is a tall cupboard or cabinet in which you can hang your clothes."},{"pos":"N-COUNT 可数名词","cn":"(某人的)全部服装","en":"Someone's wardrobe is the total collection of clothes that they have.","ex":{"en":"Her wardrobe consists primarily of huge cashmere sweaters and tiny Italian sandals.","cn":"她的衣物主要是宽大的开司米毛衣和小巧的意大利凉鞋。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(剧团演员的)全部戏装，行头","en":"The wardrobe in a theatre company is the actors' and actresses' costumes.","ex":{"en":"In the wardrobe department were rows of costumes.","cn":"戏装部有一排排的戏装。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things you wear to cover your body or keep you warm. Clothes is always plural","cn":""},{"en":"used when talking in general about a type of clothes, or about making or selling clothes. Also used in the phrase a piece/item/article of clothing (= one of the things that someone wears )","cn":""},{"en":"one thing that you wear. Also used when talking about buying and selling clothes","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"All of the clothes in your closet make up your wardrobe . If you're tired of your wardrobe , it just might be time to go shopping."}]},"collocations":{"phrases":["ADJ. built-in, fitted | double | walk-in","VERB + WARDROBE open | close","WARDROBE + NOUN door","PREP. in a/the ~ She hung the dress up in the wardrobe. 2 sb's collection of clothes","ADJ. new | extensive | autumn, spring, etc.","VERB + WARDROBE have | buy I want to buy a whole new summer wardrobe."]},"media":{"img":["media/ldoce/img/wardrobe.jpg"],"uk":"media/ldoce/hwd/bre/a/wardrobe0205.mp3","us":"media/ldoce/hwd/ame/b/wardrobe.mp3"},"examples":[{"en":"everything you need for your summer wardrobe","cn":"需要的所有夏装"},{"en":"a fitted wardrobe","cn":"入墙衣柜"}],"oxford":{"phon":"ˈwɔːdrəʊb","pos":"noun","senses":[{"en":"a large cupboard for hanging clothes in, which is either a piece of furniture or (in British English) built into the wall","cn":"衣柜；衣橱；（英国）放置衣物的壁橱","ex":{"en":"a fitted wardrobe","cn":"入墙衣柜"}},{"en":"the clothes that a person has","cn":"（一个人的）全部衣物","g":"[usually singular]","lab":"North American English also","ex":{"en":"We have everything you need for your summer wardrobe.","cn":"你需要的所有夏装我们都有。"}},{"en":"the department in a theatre or television company that takes care of the clothes that actors wear","cn":"（剧院或电视公司的）服装部，戏装保管室","g":"[usually singular]"}]}},"waif":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"极瘦弱的人；无家可归者;流浪儿","en":"If you refer to a child or young woman as a waif, you mean that they are very thin and look as if they have nowhere to live.","ex":{"en":"...a dirty-faced waif of some five or six years","cn":"五六岁大、脸上脏兮兮的流浪儿"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a child, who is pale and thin and looks as if they do not have a home","cn":"苍白瘦弱的人〔似为无家可归者﹐尤指小孩〕"},{"en":"children or animals who do not have a home","cn":"无家可归的小孩[动物]"}]},"vocab":{"pos":"n","senses":[{"en":"No matter how cold-hearted you are, it's tough not to feel sympathy for a waif — a neglected or orphaned child."}]},"media":{"uk":"media/ldoce/hwd/bre/5/waif0205.mp3","us":"media/ldoce/hwd/ame/d/waif.mp3"},"examples":[{"en":"the waifs and strays of our society (= people with no home)","cn":"我们社会的弃儿"},{"en":"waif-like young girls","cn":"面黄肌瘦的女孩子"}],"oxford":{"phon":"weɪf","pos":"noun","senses":[{"en":"a small, thin person, usually a child, who looks as if they do not have enough to eat","cn":"瘦小的人；（通常指）面黄肌瘦的小孩","ex":{"en":"the waifs and strays of our society (= people with no home)","cn":"我们社会的弃儿"}}]}},"warder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"监狱看守;狱吏","en":"A warder is someone who works in a prison supervising the prisoners."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works in a prison guarding the prisoners 〔","cn":"监狱的〕看守﹐狱吏"}]},"media":{"uk":"media/ldoce/hwd/bre/3/warder0205.mp3","us":"media/ldoce/hwd/ame/0/ld41warder.mp3"},"oxford":{"phon":"ˈwɔːdə(r)","pos":"noun","senses":[{"en":"a person who guards prisoners in a prison","cn":"（监狱的）看守；狱吏"}]}},"walker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指在乡间休闲或锻炼的)散步者，步行者","en":"A walker is a person who walks, especially in the countryside for pleasure or in order to keep healthy."},{"pos":"N-COUNT 可数名词","cn":"(帮助婴儿、残疾人或病人走路的)助行架","en":"A walker is a special kind of frame which is designed to help babies or disabled or ill people to walk.","ex":{"en":"She eventually used a cane, then a walker, and finally was confined to the house.","cn":"结果她拄上了拐杖，后来又用上了助行架，最后连房门都出不了了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is walking in a town, rather than travelling in a car, bus etc","cn":""},{"en":"someone who walks long distances in the countryside for pleasure","cn":""},{"en":"someone who walks for pleasure or exercise 〔","cn":"以自娱或锻炼为目的的〕步行者"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41walker.mp3","us":"media/ldoce/hwd/ame/7/walker.mp3"},"examples":[{"en":"The coastal path is a popular route for walkers.","cn":"这条海滨小路是散步者很喜欢走的路径。"},{"en":"He now needs a walker to get around.","cn":"他现在走动需要助行架。"}],"oxford":{"phon":"ˈwɔːkə(r)","pos":"noun","senses":[{"en":"a person who walks, usually for pleasure or exercise","cn":"步行者；散步的人；徒步旅行者","lab":"especially British English","ex":{"en":"The coastal path is a popular route for walkers.","cn":"这条海滨小路是散步者很喜欢走的路径。"}},{"en":"a person who walks fast, slow, etc.","cn":"走路快（或慢等）的人"},{"en":"a metal frame that people use to support them when they are walking, for example people who are old or who have a problem with their legs","cn":"齐默式助行架","lab":"North American English","ex":{"en":"He now needs a walker to get around.","cn":"他现在走动需要助行架。"}},{"en":"a frame with wheels and a harness that enables a baby to walk around a room, supported by the frame","cn":"（幼儿）学步车","lab":"North American English"}]}},"waver":{"collins":{"senses":[{"pos":"VERB 动词","cn":"动摇;犹豫","en":"If you waver, you cannot decide about something or you consider changing your mind about something.","ex":{"en":"Some military commanders wavered over whether to support the coup","cn":"军队的一些指挥官在犹豫是否支持政变。"}},{"pos":"VERB 动词","cn":"摇晃;摇曳","en":"If something wavers, it shakes with very slight movements or changes.","ex":{"en":"The shadows of the dancers wavered continually","cn":"舞者的身影在轻轻晃动着。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not be sure whether you should do something or whether it is good or right","cn":""},{"en":"to feel that some things about a plan, idea etc are not good or right, so that you think there may be problems or difficulties","cn":""},{"en":"to not be sure whether something is good or right, because you are worried about what will happen if it is done","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 n","senses":[{"en":"To waver is to move back and forth, like when you waver , one minute thinking you'll stay home, planning to go meet your friends the next, until you finally make your decision."}]},"media":{"uk":"media/ldoce/hwd/bre/7/waver0205.mp3","us":"media/ldoce/hwd/ame/8/waver.mp3"},"examples":[{"en":"She's wavering between buying a house in the city or moving away.","cn":"她举棋不定，不知是在这个城市里买所房子，还是迁居他处。"},{"en":"The strength of his argument convinced the waverers.","cn":"他以有力的论据说服了那些摇摆不定的人。"}],"oxford":{"phon":"ˈweɪvə(r)","pos":"verb","senses":[{"en":"to be or become weak or unsteady","cn":"减弱；动摇；颤抖","g":"[intransitive]","ex":{"en":"His voice wavered with emotion.","cn":"他激动得嗓音发抖。"}},{"en":"to hesitate and be unable to make a decision or choice","cn":"踌躇；犹豫不决；举棋不定","g":"[intransitive]","ex":{"en":"She's wavering between buying a house in the city or moving away.","cn":"她举棋不定，不知是在这个城市里买所房子，还是迁居他处。"}},{"en":"to move in an unsteady way","cn":"摇曳；闪烁；忽明忽暗","g":"[intransitive]"}]}},"waveband":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(无线电)波段","en":"A waveband is a group of radio waves of similar length which are used for particular types of radio communication."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of sound waves of a particular length, used to broadcast radio programmes 〔","cn":"无线电的〕波段"}]},"media":{"uk":"media/ldoce/hwd/bre/3/waveband0205.mp3","us":"media/ldoce/hwd/ame/3/laadwaveband.mp3"},"examples":[{"en":"a radio set with medium and short wavebands","cn":"中短波段收音机"}],"oxford":{"phon":"ˈweɪvbænd","pos":"noun","senses":[{"en":"a range of radio waves","cn":"波段","ex":{"en":"a radio set with medium and short wavebands","cn":"中短波段收音机"}}]}},"walk-on":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（角色）跑龙套的","en":"A walk-on part in a play or film is a very small part which usually does not involve any speaking.","ex":{"en":"He and his family have walk-on parts in the latest film.","cn":"他和家人在最新的这部电影中有跑龙套的角色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small acting part with no words to say in a play or film, or an actor who has a part like this 〔","cn":"戏剧或影片的〕跑龙套角色﹐无台词的小角色﹔龙套演员"},{"en":"someone who plays for a college sports team without having been given a sports scholarship 〔","cn":"未获得体育奖学金的〕大学运动队成员"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41walk-on.mp3","us":"media/ldoce/hwd/ame/2/walk-on.mp3"},"oxford":{"phon":"ˈwɔːk ɒn","pos":"adjective","senses":[{"en":"used to describe a very small part in a play or film, without any words to say","cn":"（指戏剧或电影中无台词的）小角色，龙套角色"}]}},"wallow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"沉溺（于不快的境况）","en":"If you say that someone is wallowing in an unpleasant situation, you are criticizing them for being deliberately unhappy.","ex":{"en":"His tired mind continued to wallow in self-pity","cn":"他疲惫的心继续沉溺于自哀自怜之中。"}},{"pos":"VERB 动词","cn":"(在水或泥浆中)躺卧，打滚","en":"If a person or animal wallows in water or mud, they lie or roll about in it slowly for pleasure.","ex":{"en":"Never have I had such a good excuse for wallowing in deep warm baths","cn":"我从来没找到过如此好的理由，可以美美地泡个热水澡。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to enjoy something that most people would not like","cn":""},{"en":"to enjoy doing something, especially something that is difficult, dangerous, or unkind","cn":""},{"en":"to very much enjoy doing something that is difficult or hurts other people","cn":""}]},"vocab":{"pos":"1 n v 2 v 3 v","senses":[{"en":"To wallow is to roll about in something, as a pig wallows in mud or a billionaire wallows in money."}]},"media":{"uk":"media/ldoce/hwd/bre/4/wallow0205.mp3","us":"media/ldoce/hwd/ame/b/wallow1.mp3"},"examples":[{"en":"She wallowed in the luxury of the hotel.","cn":"她沉湎于旅馆豪华奢侈的享乐之中。"},{"en":"He loves to wallow in a hot bath after a game.","cn":"他在比赛后喜欢泡个热水澡。"}],"oxford":{"phon":"ˈwɒləʊ","pos":"verb","senses":[{"en":"to lie and roll about in water or mud, to keep cool or for pleasure","cn":"（为保持凉爽或嬉戏在烂泥、水里）打滚，翻滚","g":"[intransitive]","ex":{"en":"hippos wallowing in the river","cn":"在河里打滚的河马"}},{"en":"to enjoy something that causes you pleasure","cn":"沉湎；放纵","g":"[intransitive]","lab":"often disapproving","ex":{"en":"She wallowed in the luxury of the hotel.","cn":"她沉湎于旅馆豪华奢侈的享乐之中。"}},{"en":"an act of wallowing","cn":"（在烂泥或水里的）打滚嬉戏，翻滚","ex":{"en":"pigs having a wallow in the mud","cn":"在烂泥中打滚的猪"},"pos":"noun"}]}},"warlike":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好战的","en":"Warlike people seem aggressive and eager to start a war.","ex":{"en":"The Scythians were a fiercely warlike people.","cn":"西徐亚人勇猛好战。"}},{"pos":"ADJ 形容词","cn":"作战用的;打仗用的","en":"A warlike object or activity relates to fighting a war.","ex":{"en":"They were armed with spears and other warlike implements.","cn":"他们用矛和其他作战工具武装自己。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"liking war and being skilful in it","cn":"好战的﹐尚武的﹔善战的"},{"en":"threatening war or attack","cn":"以战争相威胁的﹐进行战争恫吓的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/warlike0205.mp3","us":"media/ldoce/hwd/ame/c/warlike.mp3"},"examples":[{"en":"a warlike nation","cn":"好战的民族"},{"en":"warlike preparations","cn":"战备"}],"oxford":{"phon":"ˈwɔːlaɪk","pos":"adjective","senses":[{"en":"aggressive and wanting to fight","cn":"好战的；好斗的；尚武的","ex":{"en":"a warlike nation","cn":"好战的民族"}},{"en":"connected with fighting wars","cn":"战争的；与战争有关的；军事的","ex":{"en":"warlike preparations","cn":"战备"}}]}},"walk-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无电梯的公寓大楼;无电梯直通的公寓","en":"A walk-up is a tall apartment block which has no lift. You can also refer to an apartment in such a block as a walk-up .","ex":{"en":"She lives in a tiny fifth floor walk-up in New York's East Village.","cn":"她居住在纽约东村一幢公寓楼5层的一间没有电梯直达的狭小公寓里。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tall building with apartments in it that does not have an elevator","cn":"无电梯的公寓大楼"},{"en":"an apartment, office etc in a building like this","cn":"无电梯大楼里的公寓房[办公室等]"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41walk-up.mp3","us":"media/ldoce/hwd/ame/6/walk-up.mp3"},"oxford":{"phon":"ˈwɔːk ʌp","pos":"noun","senses":[{"en":"a tall building with stairs but no elevator; an office or apartment in such a building","cn":"无电梯的大楼；无电梯大楼中的办公室（或公寓套房）"}]}},"watercolour":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"水彩","en":"Watercolours are coloured paints, used for painting pictures, which you apply with a wet brush or dissolve in water first.","ex":{"en":"...a collection of rich paintings in watercolour, acrylic and oil.","cn":"一批色彩饱满生动的水彩画、丙烯画和油画藏品"}},{"pos":"N-COUNT 可数名词","cn":"水彩画","en":"A watercolour is a picture which has been painted with watercolours.","ex":{"en":"...a lovely watercolour by J. M. W. Turner.","cn":"一幅由J.M.W.特纳创作的漂亮的水彩画"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of paint that you mix with water","cn":"水彩颜料"},{"en":"a picture painted using watercolours","cn":"水彩画"}]},"media":{"img":["media/ldoce/img/watercolours.jpg"],"uk":"media/ldoce/hwd/bre/c/watercolour0205.mp3","us":"media/ldoce/hwd/ame/d/watercolor.mp3"},"examples":[{"en":"Margaret began experimenting with watercolor.","cn":"玛格丽特开始尝试使用水彩颜料。"},{"en":"a watercolour of the castle","cn":"那座城堡的水彩画"}],"oxford":{"phon":"ˈwɔːtəkʌlə(r)","pos":"noun","senses":[{"en":"paints that you mix with water, not oil, and use for painting pictures","cn":"水彩（颜料）","g":"[uncountable]","lab":"US English","ex":{"en":"He worked in watercolour, ink and crayon.","cn":"他用水彩、墨水和蜡笔作画。"}},{"en":"a picture painted with these paints","cn":"水彩画","g":"[countable]","ex":{"en":"a watercolour of Lake Albano by John Cozens","cn":"约翰·科曾斯 (John Cozens) 绘制的阿尔巴诺湖水彩画"}}]}},"washing-up":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"洗餐具","en":"To do the washing-up means to wash the plates, cups, cutlery, and pans which have been used for cooking and eating a meal.","ex":{"en":"Martha volunteered to do the washing-up.","cn":"玛莎主动提出去洗餐具。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"待洗的餐具","en":"Washing-up is the plates, cups, cutlery, and pans which you have to wash after a meal.","ex":{"en":"...a brimming bowl of washing-up.","cn":"一满盆待洗的餐具"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the washing of plates, dishes, knives etc","cn":"洗餐具"},{"en":"the dirty pans, plates, dishes, knives etc that have to be washed","cn":"待洗的餐具"}]},"media":{"uk":"media/ldoce/hwd/bre/8/washing_up0205.mp3","us":"media/ldoce/hwd/ame/6/amelasdewashing-up.mp3"},"examples":[{"en":"The sink was still full of last night's washing-up.","cn":"洗涤槽里仍然摆满了昨天晚上没洗刷的餐具。"},{"en":"If you cook, I'll do the washing-up.","cn":"如果你做饭，我就洗碗。"}],"oxford":{"phon":"ˌwɒʃɪŋ ˈʌp","pos":"noun","senses":[{"en":"the act of washing plates, glasses, pans, etc. after a meal","cn":"（饭后）刷洗餐具","ex":{"en":"If you cook, I'll do the washing-up.","cn":"如果你做饭，我就洗碗。"}},{"en":"the dirty plates, glasses, pans, etc. that have to be washed after a meal","cn":"（饭后的）待洗餐具","ex":{"en":"The sink was still full of last night's washing-up.","cn":"洗涤槽里仍然摆满了昨天晚上没洗刷的餐具。"}}]}},"warehouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"仓库;货栈","en":"A warehouse is a large building where raw materials or manufactured goods are stored until they are exported to other countries or distributed to shops to be sold."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large building for storing large quantities of goods","cn":"仓库﹐货栈"}]},"vocab":{"pos":"n v","senses":[{"en":"A warehouse is a place where a company stores things they are going to sell. If you order a book online, it is almost certainly shipped from a warehouse to your house."}]},"collocations":{"phrases":["ADJ. 30,000 sq ft, etc. | bonded The whisky was taken to bonded warehouses at Port Dundee. | distribution, retail, wholesale | furniture, go","VERB + WAREHOUSE burn down","WAREHOUSE + VERB burn down","WAREHOUSE + NOUN foreman, manager, staff, worker He's a warehouse foreman for a removals firm."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdewarehouse.mp3","us":"media/ldoce/hwd/ame/0/warehouse.mp3","img":["media/thumb/warehouse.jpg"]},"oxford":{"phon":"ˈweəhaʊs","pos":"noun","senses":[{"en":"a building where large quantities of goods are stored, especially before they are sent to shops to be sold","cn":"仓库；货栈；货仓","ex":{"en":"Police are investigating a fire at a furniture warehouse.","cn":"警方正在调查发生在家具仓库的一起大火。"}}]}},"wafer-thin":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极薄的;极扁薄的","en":"Wafer-thin means extremely thin and flat.","ex":{"en":"Cut the fennel into wafer-thin slices.","cn":"把茴香切成薄薄的小片。"}},{"pos":"ADJ 形容词","cn":"（优势）极微弱的","en":"If you succeed by a wafer-thin margin, you succeed by a very small amount.","ex":{"en":"...a prime minister with a divided party and a wafer-thin majority.","cn":"来自一个分裂的政党、仅以微弱多数票当选的首相"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wide","cn":""},{"en":"thin, especially in a way that looks attractive","cn":""},{"en":"tall or long and thin, in a way that looks attractive, but is often not very strong","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41wafer-thin.mp3","us":"media/ldoce/hwd/ame/6/wafer-thin.mp3"},"examples":[{"en":"wafer-thin chocolates","cn":"薄片巧克力"}],"oxford":{"phon":"ˌweɪfə ˈθɪn","pos":"adjective","senses":[{"en":"very thin","cn":"很薄的","ex":{"en":"wafer-thin mints","cn":"很薄的薄荷糖"}}]}},"wank":{"collins":{"senses":[{"pos":"VERB 动词","cn":"手淫","en":"To wank means to masturbate."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to masturbate","cn":"手淫"},{"en":"an act of masturbation","cn":"手淫"},{"en":"something which you think is very stupid, useless, or of bad quality","cn":"愚蠢的东西﹔无用之物﹔讨厌的东西"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41wank2.mp3","us":"media/ldoce/hwd/ame/0/ld41wank2.mp3"},"examples":[{"en":"This music’s a load of wank.","cn":"这音乐糟透了。"}],"oxford":{"phon":"wæŋk","pos":"verb","senses":[{"en":"to masturbate","cn":"手淫"},{"en":"an act of masturbation","cn":"手淫","pos":"noun"}]}},"wader":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"涉禽","en":"A wader is a bird with long legs and a long neck, which lives near water and feeds on fish. There are several different kinds of waders."},{"pos":"N-COUNT 可数名词","cn":"(涉水捕鱼时穿的)长筒靴","en":"Waders are long rubber boots which cover all of the legs and are worn by fishermen when they are standing in water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bird that has long legs and a long neck, and that walks around in water to find its food","cn":"涉禽"},{"en":"high rubber boots that you wear for walking in deep water, usually when fishing 〔","cn":"涉水用的〕高筒防水胶靴"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41wader.mp3","us":"media/ldoce/hwd/ame/3/ld41wader.mp3"},"examples":[{"en":"a pair of waders","cn":"一双高筒防水胶靴"}],"oxford":{"phon":"ˈweɪdə(r)","pos":"noun","senses":[{"en":"any of several different types of bird with long legs that feed in shallow water","cn":"涉禽；涉水鸟","g":"[countable]"},{"en":"long rubber boots that reach up to your thigh, that you wear for standing in water, especially when fishing","cn":"（涉水捕鱼等穿的）高筒防水胶靴","g":"[plural]","ex":{"en":"a pair of waders","cn":"一双高筒防水胶靴"}}]}},"waterfowl":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水鸟，水禽(尤指鸭、鹅、天鹅等)","en":"Waterfowl are birds that swim in water, especially ducks, geese, and swans."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wild bird that swims and lives near water","cn":"水鸟﹐水禽"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41waterfowl.mp3","us":"media/ldoce/hwd/ame/8/waterfowl.mp3"},"examples":[{"en":"the varied waterfowl of North America","cn":"北美洲种类繁多的水鸟"}],"oxford":{"phon":"ˈwɔːtəfaʊl","pos":"noun","senses":[{"en":"a bird that can swim and lives near water, especially a duck or goose","cn":"水鸟；水禽（尤指鸭或鹅）"}]}},"watchful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"警觉的;警惕的","en":"Someone who is watchful notices everything that is happening.","ex":{"en":"The best thing is to be watchful and see the family doctor for any change in your normal health","cn":"最佳的做法是保持警惕，一旦你的身体状况有任何变化就立即去看家庭医生。"}},{"pos":"PHRASE 短语","cn":"在(某人)的警觉目光下；在…的监视下","en":"If you do something under the watchful eye of someone who has authority over you, they watch you carefully to make sure there are no problems.","ex":{"en":"There were demonstrations in the streets today, under the watchful eye of police","cn":"今天，在警方的监视下大街上进行了游行。"}},{"pos":"PHRASE 短语","cn":"看护;提防","en":"If you keep a watchful eye on someone or something, you watch carefully to make sure there are no problems.","ex":{"en":"Keep a watchful eye on babies and toddlers.","cn":"要看好婴儿和刚会走路的孩子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is alert is always watching, and notices if anything strange or unusual happens","cn":""},{"en":"to watch carefully because you think that something bad might happen","cn":""},{"en":"say this to tell someone to keep watching carefully so that they will see something that they are hoping or expecting to see","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be watchful is to be alert and aware. A watchful dog might keep an eye on the sidewalk in front of your house all afternoon."}]},"media":{"uk":"media/ldoce/hwd/bre/9/watchful0205.mp3","us":"media/ldoce/hwd/ame/d/watchful.mp3"},"examples":[{"en":"Her expression was watchful and alert.","cn":"她露出一副察言观色、处处提防的表情。"},{"en":"The children played under the watchful eye of their teacher.","cn":"孩子们在老师的看护下玩耍。"}],"oxford":{"phon":"ˈwɒtʃfl","pos":"adjective","senses":[{"en":"paying attention to what is happening in case of danger, accidents, etc.","cn":"注意的；警惕的；提防的","ex":{"en":"Her expression was watchful and alert.","cn":"她露出一副察言观色、处处提防的表情。"}}]}},"warthog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"疣猪(一种非洲野猪)","en":"A warthog is a wild pig with two large teeth that curve upwards at the sides of its mouth. Warthogs live in Africa."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an African wild pig with long front teeth that stick out of the side of its mouth","cn":"疣猪〔非洲的一种野猪﹐长有獠牙〕"}]},"media":{"img":["media/ldoce/img/warthog.jpg"],"uk":"media/ldoce/hwd/bre/2/ld41warthog.mp3","us":"media/ldoce/hwd/ame/a/warthog.mp3"},"oxford":{"phon":"ˈwɔːthɒɡ","pos":"noun","senses":[{"en":"an African wild pig with two large outer teeth called tusks and growths like warts on its face","cn":"疣猪（非洲野猪，有一对獠牙，脸部有疣）"}]}},"warrior":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指旧时的)勇士，武士","en":"A warrior is a fighter or soldier, especially one in former times who was very brave and experienced in fighting."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soldier or fighter who is brave and experienced – used about people in the past 〔","cn":"昔日的〕武士﹐战士﹐勇士"}]},"vocab":{"pos":"n","senses":[{"en":"Although logically linked with someone engaged in war, a warrior can be anyone who fights the good fight, whether in politics, on the job, or just as a \"weekend warrior \" trying to accomplish multiple tasks during off-hours at home."}]},"collocations":{"phrases":["ADJ. formidable, great, mighty, noble | brave, valiant | famous, renowned","QUANT. band","WARRIOR + VERB fight"]},"media":{"uk":"media/ldoce/hwd/bre/4/warrior0205.mp3","us":"media/ldoce/hwd/ame/5/warrior.mp3"},"examples":[{"en":"a warrior nation (= whose people are skilled in fighting)","cn":"善战的民族"},{"en":"a Zulu warrior","cn":"祖鲁人的勇士"}],"oxford":{"phon":"ˈwɒriə(r)","pos":"noun","senses":[{"en":"(especially in the past) a person who fights in a battle or war","cn":"（尤指旧时的）武士，勇士，斗士","ex":{"en":"a warrior nation (= whose people are skilled in fighting)","cn":"善战的民族"}},{"en":"a person who leads or takes part in a campaign for a political or social cause, especially in an aggressive way that other people think is bad","cn":"斗士（指政治或社会运动的首领或参与者，尤其是寻衅滋事者）","lab":"often disapproving","ex":{"en":"These social justice warriors want to apply their politically correct standards and rules to others' speech.","cn":"这些社会正义斗士希望将他们的政治正确标准和规则应用到他人的言论中。"}}]}},"walkie-talkie":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无线电对话机;步话机","en":"A walkie-talkie is a small portable radio which you can talk into and hear messages through so that you can communicate with someone far away."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of a pair of radios that you can carry with you, and use to speak to the person who has the other radio","cn":"步话机﹐无线电对讲机"}]},"media":{"uk":"media/ldoce/hwd/bre/f/walkie_talkie0205.mp3","us":"media/ldoce/hwd/ame/4/walkie-talkie.mp3"},"oxford":{"phon":"ˌwɔːki ˈtɔːki","pos":"noun","senses":[{"en":"a small radio that you can carry with you and use to send or receive messages","cn":"步话机；无线电通话机"}]}},"waive":{"collins":{"senses":[{"pos":"VERB 动词","cn":"放弃（合法权利等）","en":"If you waive your right to something, for example legal representation, you choose not to have it or do it.","ex":{"en":"He pleaded guilty to the murders of three boys and waived his right to appeal.","cn":"他承认谋杀了3个男孩，并放弃上诉。"}},{"pos":"VERB 动词","cn":"（特定情况下）不强求执行(规则等)","en":"If someone waives a rule, they say that people do not have to obey it in a particular situation.","ex":{"en":"The art gallery waives admission charges on Sundays","cn":"美术馆周日免收门票。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to let someone do something that is slightly different from what the rules allow, especially when you do not officially tell anyone about it","cn":""},{"en":"to allow someone to do something that is not usually allowed","cn":""},{"en":"a special right that a particular group of people are allowed to have, for example, by the government or by their employer","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To waive is to give up one's right to do something. If you waive your right to help name your family's new puppy, you can't complain if he ends up being called \"Mr. Tinkerbell Sweetheart Lovey-Face.\""}]},"media":{"uk":"media/ldoce/hwd/bre/f/waive0205.mp3","us":"media/ldoce/hwd/ame/6/waive.mp3"},"examples":[{"en":"She waived her right to a lawyer.","cn":"她放弃了请律师的权利。"}],"oxford":{"phon":"weɪv","pos":"verb","senses":[{"en":"to choose not to demand something in a particular case, even though you have a legal or official right to do so","cn":"放弃（权利、要求等）","ex":{"en":"He waived his right to appeal against the verdict.","cn":"他放弃了对判决提出上诉的权利。"}}]}},"wallop":{"collins":{"senses":[{"pos":"VERB 动词","cn":"重击;狠揍","en":"If you wallop someone or something, you hit them very hard, often causing a dull sound.","ex":{"en":"Once, she walloped me over the head with a frying pan.","cn":"有一次，她用煎锅狠狠地砸了我的头。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit someone or something very hard, especially with your hand 〔","cn":"尤指用手〕猛击"}]},"media":{"uk":"media/ldoce/hwd/bre/7/wallop0205.mp3","us":"media/ldoce/hwd/ame/5/wallop1.mp3"},"examples":[{"en":"We walloped them 6–0.","cn":"我们以 6:0 把他们打得落花流水。"}],"oxford":{"phon":"ˈwɒləp","pos":"noun","senses":[{"en":"a heavy, powerful hit","cn":"痛打；猛击"},{"en":"to hit somebody/something very hard","cn":"猛打；重击；狠揍","ex":{"en":"My father used to wallop me if I told lies.","cn":"如果我说谎，我父亲就会打我。"},"pos":"verb"},{"en":"to defeat somebody completely in a contest, match, etc.","cn":"（在竞赛、比赛等中）彻底击败，大胜","ex":{"en":"We walloped them 6–0.","cn":"我们以 6:0 把他们打得落花流水。"},"pos":"verb"}]}},"wan":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"苍白的;有倦容的;疲惫的","en":"If you describe someone as wan, you mean that they look pale and tired.","ex":{"en":"He looked wan and tired","cn":"他脸色苍白，面带倦容。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"looking pale, weak, or tired","cn":"苍白的﹔虚弱的﹔倦怠的"}]},"vocab":{"pos":"adj v","senses":[{"en":"Someone who is wan is visibly unwell and lacking in energy. If you’ve had the flu for over a week, and you finally get out of bed looking pale and tired, your mother might say that you look wan ."}]},"media":{"uk":"media/ldoce/hwd/bre/5/wan0205.mp3","us":"media/ldoce/hwd/ame/b/wan.mp3"},"examples":[{"en":"She gave me a wan smile (= showing no energy or enthusiasm).","cn":"她勉强向我微微一笑。"},{"en":"He smiled wanly.","cn":"他惨然一笑。"}],"oxford":{"phon":"wɒn","pos":"adjective","senses":[{"en":"looking pale and weak","cn":"苍白无力的；无血色的；憔悴的","ex":{"en":"his grey, wan face","cn":"他那苍白憔悴的面孔"}},{"en":"a system in which computers in different places are connected, usually over a large area (the abbreviation for ‘wide area network’)","cn":"广域网（将大范围内不同地方的计算机联网的系统，全写为 wide area network）","pos":"noun"}]}},"washstand":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脸盆架","en":"A washstand is a piece of furniture designed to hold a bowl for washing your hands and face in, which was used in former times before washbasins had taps on them.","ex":{"en":"...a Victorian marble-topped washstand.","cn":"维多利亚时代的大理石台面脸盆架"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a table in a bedroom, used in the past for holding the things needed for washing your face 〔","cn":"旧时卧室里放置盥洗用具的〕脸盆架﹐盥洗台"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41washstand.mp3","us":"media/ldoce/hwd/ame/3/washstand.mp3"},"oxford":{"phon":"ˈwɒʃstænd","pos":"noun","senses":[{"en":"(especially in the past) a special table in a bedroom that holds a basin for washing yourself in","cn":"（尤指旧时卧室内的）盥洗台"}]}},"waylay":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拦截;伏击","en":"If someone waylays you, they stop you when you are going somewhere, for example in order to talk to you, to steal something from you, or to attack you.","ex":{"en":"She was forever waylaying him in odd holes and corners of the hotel","cn":"她总是在酒店的犄角旮旯里截住他。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if someone waylays you, they stop you when you are going somewhere, for example to attack you or talk to you 〔","cn":"为了袭击或谈话〕拦下〔某人〕"},{"en":"if you are waylaid, you are delayed when you are doing something – often used humorously to say why you are late","cn":"耽搁〔常为幽默用法﹐说明为何迟到〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you waylay someone, you stop them from doing what they were going to do, either by using violence or some other tactic."}]},"media":{"uk":"media/ldoce/hwd/bre/7/waylay0205.mp3","us":"media/ldoce/hwd/ame/0/waylay.mp3"},"examples":[{"en":"I got waylaid on my way here.","cn":"我在来这里的路上遭到了拦路抢劫。"},{"en":"They used to waylay him as he came out of the factory.","cn":"他们以前总是在他从工厂出来的时候上去纠缠他。"}],"oxford":{"phon":"weɪˈleɪ","pos":"verb","senses":[{"en":"to stop somebody who is going somewhere, especially in order to talk to them or attack them","cn":"拦截（尤其是为了谈话或袭击）；拦路","ex":{"en":"I got waylaid on my way here.","cn":"我在来这里的路上遭到了拦路抢劫。"}}]}},"way-out":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极不寻常的;十分古怪的","en":"If you describe someone or something as way-out, you are critical of them because they are very unusual, often in a way that is very modern or fashionable.","ex":{"en":"They will not allow your more way-out ideas to pass unchallenged","cn":"他们不会放过你这些古怪的念头的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very modern, unusual, and strange","cn":"时髦的﹔不寻常的﹔新奇的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeway-out.mp3","us":"media/ldoce/hwd/ame/9/way-out.mp3"},"examples":[{"en":"way-out ideas","cn":"离奇的想法"}],"oxford":{"phon":"ˌweɪ ˈaʊt","pos":"noun","senses":[{"en":"a door used for leaving a building","cn":"（建筑物的）出口","lab":"British English"},{"en":"a way of escaping from a difficult situation","cn":"（困境的）出路","ex":{"en":"She was in a mess and could see no way out.","cn":"她陷入困境，找不到出路。"}},{"en":"unusual or strange","cn":"稀奇的；非传统的；前卫的","ex":{"en":"way-out ideas","cn":"离奇的想法"},"pos":"adjective"}]}},"waterlogged":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（土地等）水涝的，水浸的，积水的","en":"Something such as soil or land that is waterlogged is so wet that it cannot absorb any more water, so that a layer of water remains on its surface.","ex":{"en":"The match is off because of a waterlogged pitch.","cn":"由于场地积水太多比赛被取消了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very wet all the way through – used especially about people and their clothes","cn":""},{"en":"very wet – used about a person or area after a lot of rain or water has fallen on them","cn":""},{"en":"extremely wet, and unable to take in any more water or liquid","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdewaterlogged.mp3","us":"media/ldoce/hwd/ame/9/waterlogged.mp3"},"examples":[{"en":"They couldn't play because the pitch was waterlogged.","cn":"因球场泡水他们未能进行比赛。"},{"en":"Heavy rain meant the pitch was waterlogged.","cn":"大雨意味着球场浸水。"}],"oxford":{"phon":"ˈwɔːtəlɒɡd","pos":"adjective","senses":[{"en":"so full of water that it cannot hold any more and becomes covered by a large amount of it","cn":"水浸的；水涝的；水淹的","ex":{"en":"They couldn't play because the pitch was waterlogged.","cn":"因球场积水他们未能进行比赛。"}},{"en":"so full of water that it can no longer float","cn":"进水满舱的；浸满水下沉的"}]}},"warehousing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"入库;仓库贮存","en":"Warehousing is the act or process of storing large quantities of goods so that they can be sold or used at a later date.","ex":{"en":"All donations go towards the cost of warehousing.","cn":"所有捐款都用作仓储费用。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the business or practice of storing large quantities of goods, especially in warehouses","cn":"仓储业﹔仓储"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41warehousing.mp3","us":"media/ldoce/hwd/ame/d/laadwarehousing.mp3"},"examples":[{"en":"warehousing costs","cn":"仓储成本"},{"en":"warehousing and distribution","cn":"仓储和分销"}],"oxford":{"phon":"ˈweəhaʊzɪŋ","pos":"noun","senses":[{"en":"the practice or business of storing things in a warehouse","cn":"仓储；仓储业"}]}},"water-soluble":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"水溶性的;可溶于水的","en":"Something that is water-soluble dissolves in water.","ex":{"en":"Vitamin C is water soluble.","cn":"维生素C可溶于水。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a water-soluble substance is solid but becomes liquid when mixed with water","cn":"能溶解于水的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/water_soluble0205.mp3","us":"media/ldoce/hwd/ame/0/water-soluble.mp3"},"oxford":{"phon":"ˌwɔːtə ˈsɒljəbl","pos":"adjective","senses":[{"en":"that can be dissolved in water","cn":"能溶解于水的，水溶性的","ex":{"en":"The paint is water-soluble.","cn":"这种油漆是水溶性的。"}}]}},"warhead":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(炸弹或导弹的)弹头","en":"A warhead is the front part of a bomb or missile where the explosives are carried.","ex":{"en":"...nuclear warheads.","cn":"核弹头"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the explosive part at the front of a missile","cn":"导弹弹头"}]},"media":{"uk":"media/ldoce/hwd/bre/0/warhead0205.mp3","us":"media/ldoce/hwd/ame/7/warhead.mp3"},"examples":[{"en":"nuclear warheads","cn":"核弹头"}],"oxford":{"phon":"ˈwɔːhed","pos":"noun","senses":[{"en":"the explosive part of a missile","cn":"（导弹的）弹头","ex":{"en":"nuclear warheads","cn":"核弹头"}}]}},"washer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"垫圈","en":"A washer is a thin flat ring of metal or rubber which is placed over a bolt before the nut is screwed on."},{"pos":"N-COUNT 可数名词","cn":"同washing machine","en":"A washer is the same as a washing machine ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin flat ring of plastic, metal, rubber etc that is put over a bolt before the nut is put on, or between two pipes, to make a tighter joint 〔","cn":"用于螺母上或管子间的〕垫圈"},{"en":"a washing machine","cn":"洗衣机"}]},"media":{"uk":"media/ldoce/hwd/bre/e/washer0205.mp3","us":"media/ldoce/hwd/ame/6/washer.mp3"},"oxford":{"phon":"ˈwɒʃə(r)","pos":"noun","senses":[{"en":"a small flat ring made of rubber, metal or plastic placed between two surfaces, for example under a nut to make a connection tight","cn":"（螺母等的）垫圈"},{"en":"a washing machine","cn":"洗衣机","lab":"informal"}]}},"wail":{"collins":{"senses":[{"pos":"VERB 动词","cn":"哀号;悲鸣;恸哭","en":"If someone wails, they make long, loud, high-pitched cries which express sorrow or pain.","ex":{"en":"The women began to wail in mourning.","cn":"女人们开始哀哭起来。"}},{"pos":"VERB 动词","cn":"哀诉;哀号着说","en":"If you wail something, you say it in a loud, high-pitched voice that shows that you are unhappy or in pain.","ex":{"en":"'Now look what you've done!' Shirley wailed","cn":"“看看你干的好事！”雪莉哭诉道。"}},{"pos":"VERB 动词","cn":"(警报器等)尖叫，尖啸","en":"If something such as a siren or an alarm wails, it makes a long, loud, high-pitched sound.","ex":{"en":"Police cars, their sirens wailing, accompanied the lorries","cn":"警车护送着大卡车，一路警笛长鸣。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to produce tears from your eyes","cn":""},{"en":"to cry a lot and for a long time","cn":""},{"en":"to be crying","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To wail is to let loose a long loud cry. If you're feeling truly miserable, take a deep breath and wail as loudly as possible."}]},"collocations":{"phrases":["ADV. almost | helplessly","VERB + WAIL begin to | hear sb","PREP. for wailing for her dead husband | with She wailed with despair.","PHRASES weeping and wailing A crowd of women followed the coffin, weeping and wailing."]},"media":{"uk":"media/ldoce/hwd/bre/f/wail0205.mp3","us":"media/ldoce/hwd/ame/a/wail.mp3"},"examples":[{"en":"There's no point wailing about something that happened so long ago.","cn":"事情早已发生，痛哭流涕也于事无补。"},{"en":"The little girl was wailing miserably.","cn":"那小女孩难过得号啕大哭。"}],"oxford":{"phon":"weɪl","pos":"verb","senses":[{"en":"to make a long, loud, high noise because you are sad or in pain","cn":"（因悲伤或疼痛）哭号，恸哭","g":"[intransitive]","ex":{"en":"The little girl was wailing miserably.","cn":"那小女孩难过得号啕大哭。"}},{"en":"to cry or complain about something in a loud high voice","cn":"大声呼叫；哀号；高声抱怨","g":"[transitive, intransitive]","ex":{"en":"The cat was wailing to be let out.","cn":"那只猫号叫着想要出去。"}},{"en":"to make a long, loud, high sound","cn":"发出尖厉的声音；呼啸","g":"[intransitive]","ex":{"en":"Ambulances raced by with sirens wailing.","cn":"救护车高声鸣笛疾驰而过。"}},{"en":"a long, loud, high cry expressing pain or very sad feelings; a sound similar to this","cn":"（疼痛或悲伤时发出的）号啕，哀号","ex":{"en":"a wail of despair","cn":"绝望的哀号"},"pos":"noun"}]}},"walkman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"随身听","en":"A Walkman is a small cassette player with light headphones which people carry around so that they can listen to music, for example while they are travelling."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small MP3 player with headphones , that you carry with you so that you can listen to music","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41walkman.mp3","us":"media/ldoce/hwd/ame/6/walkman.mp3"},"oxford":{"phon":"ˈwɔːkmən","pos":"noun","senses":[{"en":"a type of personal stereo","cn":"随身听（小型立体声音响）"}]}},"waistcoat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"背心;马甲","en":"A waistcoat is a sleeveless piece of clothing with buttons which people usually wear over a shirt."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of clothing without sleeve s that has buttons down the front and is worn over a shirt, often under a jacket as part of a man’s suit","cn":"马甲﹐西服背心"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld44waistcoat.mp3","us":"media/ldoce/hwd/ame/6/waistcoat.mp3"},"oxford":{"phon":"ˈweɪskəʊt","pos":"noun","senses":[{"en":"a short piece of clothing with buttons down the front but no arms, usually worn over a shirt and under a jacket, often forming part of a formal suit","cn":"（西服的）背心","ex":{"en":"He always wore a brightly-coloured waistcoat under his dark grey suit.","cn":"他总是在深灰色西装里面穿上颜色鲜艳的马甲。"}}]}},"warble":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(鸟)啭鸣，啁啾","en":"When a bird warbles, it sings pleasantly.","ex":{"en":"The bird continued to warble","cn":"鸟儿继续啁啾。"}},{"pos":"VERB 动词","cn":"用颤音唱","en":"If someone warbles, they sing in a high-pitched, rather unsteady voice.","ex":{"en":"She warbled as she worked.","cn":"她边工作边用颤音唱歌。"}},{"pos":"VERB 动词","cn":"(电话等)发出颤音","en":"When machines such as telephones warble, they make high-pitched sounds.","ex":{"en":"The telephone on his desk warbled.","cn":"他桌上的电话叮铃铃响了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to sing with a high continuous but quickly changing sound, the way a bird does","cn":"用颤音高声唱﹔〔鸟〕啭鸣"},{"en":"to sing, especially not very well – used humorously","cn":"唱〔尤指唱得不好﹔幽默用法〕"}]},"vocab":{"pos":"1 v 2 n","senses":[{"en":"To warble is to sing in an uneven, quavering voice. You won't win any singing contests if you warble the songs."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41warble.mp3","us":"media/ldoce/hwd/ame/4/warble.mp3"},"examples":[{"en":"He warbled his way through the song.","cn":"整个歌曲他是用高颤音唱的。"},{"en":"Mills warbled a few notes.","cn":"米尔斯凑合着唱了几个音。"}],"oxford":{"phon":"ˈwɔːbl","pos":"verb","senses":[{"en":"to sing, especially in a high voice that is not very steady","cn":"（尤指用颤音高声）唱","g":"[transitive, intransitive]","lab":"humorous","ex":{"en":"He warbled his way through the song.","cn":"整个歌曲他是用高颤音唱的。"}},{"en":"to sing with rapidly changing notes","cn":"啭鸣","g":"[intransitive, transitive]"},{"en":"a high singing voice, especially one that is not very steady","cn":"（尤指用颤音高声）唱","lab":"humorous","ex":{"en":"I heard the faint warble of Laura’s voice.","cn":"我听到劳拉微弱的声音。"},"pos":"noun"},{"en":"the sound of a bird singing with rapidly changing notes","cn":"啭鸣","ex":{"en":"You will hear the chirp and warble of many birds.","cn":"您会听到许多鸟儿的鸣叫声和鸣叫声。"},"pos":"noun"}]}},"wart":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"疣;肉赘","en":"A wart is a small lump which grows on your skin."},{"pos":"PHRASE 短语","cn":"不隐瞒缺点地;毫不遮丑地","en":"If you describe someone or accept them warts and all, you describe them or accept them as they are, including all their faults.","ex":{"en":"Lyn loves him warts and all","cn":"琳恩爱他的全部。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark on your skin that spoils its appearance","cn":""},{"en":"a small dark, sometimes raised, mark on your skin","cn":""},{"en":"small light brown marks on your skin, especially on your face but also on your arms, shoulders etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/wart0205.mp3","us":"media/ldoce/hwd/ame/0/wart.mp3"},"examples":[{"en":"She still loves him, warts and all.","cn":"她仍然爱他，不管他有什么缺点。"},{"en":"Well, you married him – warts and all.","cn":"哎呀﹐他再不好﹐你都已经嫁给他了。"}],"oxford":{"phon":"wɔːt","pos":"noun","senses":[{"en":"a small hard spot that grows on your skin and that is caused by a virus","cn":"疣；瘊子；肉赘"},{"en":"a small hard spot like a wart on the bottom of the foot, which can be easily spread from person to person","cn":"（长在脚底上，容易传染的）疣","lab":"both North American English"}]}},"waterfront":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滨水区;码头区;水边地","en":"A waterfront is a street or piece of land which is next to an area of water, for example a harbour or the sea.","ex":{"en":"They went for a stroll along the waterfront.","cn":"他们沿着滨水区漫步。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a town or an area of land next to the sea, a river etc 〔","cn":"城镇等的〕滨水地区﹐水边土地"}]},"media":{"uk":"media/ldoce/hwd/bre/2/waterfront0205.mp3","us":"media/ldoce/hwd/ame/3/waterfront.mp3"},"examples":[{"en":"a waterfront apartment","cn":"一套滨水公寓"},{"en":"The hotel is down on the waterfront.","cn":"这家酒店位于低处的滨水区。"}],"oxford":{"phon":"ˈwɔːtəfrʌnt","pos":"noun","senses":[{"en":"a part of a town or an area that is next to water, for example in a harbour","cn":"滨水路；滨水区；码头区","ex":{"en":"a waterfront apartment","cn":"一套滨水公寓"}}]}},"wannabe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"效颦者","en":"If you call someone a wannabe, you are saying in an unkind way that they are trying very hard to be like another person or group of people.","ex":{"en":"...a feeble James Dean wannabe.","cn":"詹姆斯·迪安的拙劣模仿者"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who tries to look or behave like someone famous or like a particular type of successful person, because they want to be like them – usually used to show disapproval","cn":"仿效名人[富人]的人〔一般含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdewannabe.mp3","us":"media/ldoce/hwd/ame/0/wannabe.mp3"},"examples":[{"en":"a load of Michael Schumacher wannabes trying to show what they can do on the track","cn":"许多想像迈克尔•舒马赫那样在赛车场上一展身手的人"},{"en":"wannabe pop stars","cn":"想当流行歌星的人"}],"oxford":{"phon":"ˈwɒnəbi","pos":"noun","senses":[{"en":"a person who behaves, dresses, etc. like somebody famous because they want to be like them","cn":"（名人的）崇拜模仿者","ex":{"en":"a rock star wannabe","cn":"模仿摇滚歌星的人"}}]}},"watchtower":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"瞭望塔;岗楼","en":"A watchtower is a high building which gives a person a good view of the area around the place that they are guarding."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a high tower used for watching and guarding a place","cn":"岗楼﹐瞭望塔"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41watchtower.mp3","us":"media/ldoce/hwd/ame/7/watchtower.mp3"},"oxford":{"phon":"ˈwɒtʃtaʊə(r)","pos":"noun","senses":[{"en":"a tall tower from which soldiers, etc. watch when they are guarding a place","cn":"瞭望塔；岗楼"}]}},"waistline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腰围","en":"Your waistline is your waist measurement.","ex":{"en":"A passion for cooking does not necessarily have to be bad for your waistline.","cn":"热衷于做菜并不一定会导致腰围增粗。"}},{"pos":"N-COUNT 可数名词","cn":"(衣服的)腰身","en":"The waistline of a piece of clothing is the place where the upper and lower parts are sewn together, which is near to your waist when you wear it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount you measure around the waist, especially used to judge how fat or thin you are","cn":"腰围"},{"en":"the position of the waist of a piece of clothing 〔","cn":"衣服的〕腰身部分"}]},"collocations":{"phrases":["ADJ. expanding","VERB + WAISTLINE watch Low-fat foods are ideal for people who are watching their waistline. 2 part of a piece of clothing","ADJ. high, low"]},"media":{"uk":"media/ldoce/hwd/bre/b/waistline0205.mp3","us":"media/ldoce/hwd/ame/b/waistline.mp3"},"examples":[{"en":"an expanding waistline","cn":"逐渐增大的腰围"},{"en":"a trim waistline","cn":"苗条的腰身"}],"oxford":{"phon":"ˈweɪstlaɪn","pos":"noun","senses":[{"en":"the amount that a person measures around the middle part of their body, used to talk about how fat or thin they are","cn":"腰围","ex":{"en":"an expanding waistline","cn":"逐渐增大的腰围"}},{"en":"the part of a piece of clothing where your waist is","cn":"（衣服的）腰部，腰"}]}},"wangle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"用计弄到;哄骗","en":"If you wangle something that you want, you manage to get it by being clever or persuading someone.","ex":{"en":"We managed to wangle a few days' leave","cn":"我们设法骗到了几天的假。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get something that is rare or difficult to find","cn":""},{"en":"to get something that you want or need very much, or have been trying hard to get","cn":""},{"en":"to get a job etc that was difficult to get - use this especially when someone was very lucky to do this","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Wangle means to get something through deception or devious coaxing, like the time you tried to wangle your way into a concert by pretending to be the singer's sister."}]},"media":{"uk":"media/ldoce/hwd/bre/4/wangle0205.mp3","us":"media/ldoce/hwd/ame/a/wangle.mp3"},"examples":[{"en":"We should be able to wangle it so that you can start tomorrow.","cn":"我们应该能设法安排你明天启程。"},{"en":"I'll try to wangle some money out of my parents.","cn":"我要设法从父母那里哄出些钱来。"}],"oxford":{"phon":"ˈwæŋɡl","pos":"verb","senses":[{"en":"to get something that you or another person wants, but do not really have a right to have, by persuading somebody or by a clever plan","cn":"把…弄到手；设法获得；搞到","ex":{"en":"She had wangled an invitation to the opening night.","cn":"她弄到了一张首映之夜的请柬。"}}]}},"wallaby":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"沙袋鼠(产于澳大利亚和新几内亚)","en":"A wallaby is an animal similar to a small kangaroo. Wallabies live in Australia and New Guinea."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an Australian animal like a small kangaroo","cn":"沙袋鼠〔产于澳大利亚〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41wallaby.mp3","us":"media/ldoce/hwd/ame/f/wallaby.mp3"},"oxford":{"phon":"ˈwɒləbi","pos":"noun","senses":[{"en":"an Australian animal like a small kangaroo, that moves by jumping on its strong back legs and keeps its young in a pouch (= a pocket of skin) on the front of the mother’s body","cn":"沙袋鼠（袋鼠科动物，产于澳大利亚）"}]}},"wad":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卷;叠;捆","en":"A wad of something such as paper or cloth is a tight bundle or ball of it.","ex":{"en":"...a wad of banknotes.","cn":"一沓钞票"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"several things of the same type, for example papers, clothes, or sticks, that are fastened or tied together","cn":""},{"en":"a group of flowers, keys etc fastened, tied, or held together","cn":""},{"en":"a number of sheets of paper, especially paper money, that are held or tied together","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/wad_n0205.mp3","us":"media/ldoce/hwd/ame/a/wad.mp3"},"examples":[{"en":"He pulled a thick wad of £10 notes out of his pocket.","cn":"他从衣袋里掏出厚厚的一沓面额 10 英镑的钞票。"},{"en":"The nurse used a wad of cotton wool to stop the bleeding.","cn":"护士用了一团脱脂棉止血。"}],"oxford":{"phon":"wɒd","pos":"noun","senses":[{"en":"a thick pile of pieces of paper, paper money, etc. folded or rolled together","cn":"（纸张、钞票等的）卷，沓，捆","lab":"British English, slang，，","ex":{"en":"He pulled a thick wad of £10 notes out of his pocket.","cn":"他从衣袋里掏出厚厚的一沓面额 10 英镑的钞票。"}},{"en":"a mass of soft material, used for blocking something or keeping something in place","cn":"用以填塞（或填衬等）的软材料；填料；填絮；衬料","ex":{"en":"The nurse used a wad of cotton wool to stop the bleeding.","cn":"护士用了一团脱脂棉止血。"}},{"en":"to fold or press something into a tight wad","cn":"将…揉成团；使成沓；使成卷","lab":"especially North American English","pos":"verb"},{"en":"to fill something with soft material to make it warmer or to protect it","cn":"（用柔软的材料）填塞，填充，衬垫","pos":"verb"}]}},"wary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"小心的;提防的","en":"If you are wary of something or someone, you are cautious because you do not know much about them and you believe they may be dangerous or cause problems.","ex":{"en":"People did not teach their children to be wary of strangers","cn":"过去人们不会教育孩子提防陌生人。"}},{"pos":"PHRASE 短语","cn":"小心观察;警惕察看","en":"If you keep a wary eye on something or someone, you are cautious about them and watch them to see what they will do or what will happen to them.","ex":{"en":"Bankers are keeping a wary eye on the outcome.","cn":"银行家们对结果保持高度警惕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is careful tries to avoid danger, risks, or accidents","cn":""},{"en":"someone who is cautious does not like taking risks and is always very careful to avoid them","cn":""},{"en":"if you do something with care or with caution , you do it carefully in order to avoid accidents","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Describe yourself as wary if you don't quite trust someone or something and want to proceed with caution. Be wary of risky things like wild mushrooms and Internet deals!"}]},"collocations":{"phrases":["VERBS be, feel, look, seem | become, get, grow | remain | make sb The strange look in his eyes made me wary of accepting his offer.","ADV. decidedly, deeply, extremely, very | increasingly | a bit, a little, rather, slightly | instinctively | suddenly Paula frowned, suddenl","PREP. about Be wary about these so-called special offers. | of You should be very wary of people offering cheap tickets.","PHRASES keep a wary eye on sb/sth (often figurative) The Venetians knew to keep a wary eye on Spanish imperial ambitions."]},"media":{"uk":"media/ldoce/hwd/bre/b/wary0205.mp3","us":"media/ldoce/hwd/ame/7/wary.mp3"},"examples":[{"en":"Be wary of strangers who offer you a ride.","cn":"提防那些主动让你搭车的陌生人。"},{"en":"The police will need to keep a wary eye on this area of town (= watch it carefully, in case there is trouble).","cn":"警方必须密切注意这一带城区。"}],"oxford":{"phon":"ˈweəri","pos":"adjective","senses":[{"en":"careful when dealing with somebody/something because you think that there may be a danger or problem","cn":"（对待人或事物时）小心的，谨慎的，留神的，小心翼翼的","ex":{"en":"Be wary of strangers who offer you a ride.","cn":"提防那些主动让你搭车的陌生人。"}}]}},"wane":{"collins":{"senses":[{"pos":"VERB 动词","cn":"衰落;减少","en":"If something wanes, it becomes gradually weaker or less, often so that it eventually disappears. wax and wane→see: ;","ex":{"en":"While his interest in these sports began to wane, a passion for rugby developed.","cn":"他对这些运动项目的兴趣开始减退，倒是对橄榄球开始有了热情。"}},{"pos":"PHRASE 短语","cn":"减弱;衰落","en":"If something is on the wane, it is becoming weaker or less.","ex":{"en":"He was nominally Deputy Prime Minister, certainly, but his influence was clearly on the wane","cn":"当然，他名义上是副首相，但是显然他的影响力正在下降。"}},{"pos":"VERB 动词","cn":"(月)缺，亏","en":"When the moon is waning, it is showing a smaller area of brightness each day as it changes from a full moon to a new moon.","ex":{"en":"The moon was waning, and each day it rose later.","cn":"月亮渐亏，每天出现的时间也越来越晚。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something such as fear, anxiety, trouble or laughter subsides , it gradually decreases","cn":""},{"en":"if something such as people's liking or support for something or someone wanes , that feeling gradually becomes slightly less and will probably continue to decrease","cn":""},{"en":"if a possibility or chance recedes , it gradually becomes less and less likely","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Things that wax and wane grow larger and smaller, like the moon. Things that wane simply grow smaller. \"My initial enthusiasm for helping waned when I saw the pile of envelopes that needed licking.\""}]},"collocations":{"phrases":["ADV. a little, somewhat Her popularity was waning somewhat. | gradually, rapidly","VERB + WANE begin to Her initial enthusiasm was clearly beginning to wane.","PHRASES wax and wane (= grow and then decrease) Public interest in the issue has waxed and waned over the years."]},"media":{"uk":"media/ldoce/hwd/bre/b/wane_v0205.mp3","us":"media/ldoce/hwd/ame/f/wane1.mp3"},"examples":[{"en":"Her enthusiasm for the whole idea was waning rapidly.","cn":"她对整个想法的热情迅速冷淡了下来。"},{"en":"Her popularity has been on the wane for some time.","cn":"她的人气一段时间以来江河日下。"}],"oxford":{"phon":"weɪn","pos":"verb","senses":[{"en":"to become gradually weaker or less important","cn":"衰落；衰败；败落；减弱","g":"[intransitive]","ex":{"en":"Her enthusiasm for the whole idea was waning rapidly.","cn":"她对整个想法的热情迅速冷淡了下来。"}},{"en":"to appear slightly smaller each day after being round and full","cn":"缺；亏","g":"[intransitive]"}]}},"waggle":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）来回摇摆;（使）上下移动","en":"If you waggle something, or if something waggles, it moves up and down or from side to side with short quick movements.","ex":{"en":"He was waggling his toes in his socks","cn":"他的脚趾在袜子里动来动去。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move your toes, fingers, bottom etc with a series of small movements","cn":""},{"en":"to move part of your body, especially your bottom, legs, or toes, from side to side or up and down, with fairly large movements","cn":""},{"en":"if a dog wags its tail, it moves its tail from side to side; if a person wags their finger or head, they shake it repeatedly, especially in order to show that they do not like something that someone has done","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/waggle0205.mp3","us":"media/ldoce/hwd/ame/3/waggle.mp3"},"examples":[{"en":"Can you waggle your ears?","cn":"你能让耳朵来回动吗？"}],"oxford":{"phon":"ˈwæɡl","pos":"noun","senses":[{"en":"a short movement from side to side or up and down","cn":"（使）上下移动，来回摆动","ex":{"en":"a waggle of his eyebrow","cn":"他的眉毛一动"}},{"en":"to make something move with short movements from side to side or up and down; to move in this way","cn":"（使）上下移动，来回摆动","ex":{"en":"Can you waggle your ears?","cn":"你能让耳朵来回动吗？"},"pos":"verb"}]}},"waxen":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(脸色等)苍白的，无生气的","en":"A waxen face is very pale and looks very unhealthy.","ex":{"en":"Her eyes were fixed on the waxen face of her son, willing him to live.","cn":"她凝视着儿子苍白的脸，盼着他好起来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"pale and shiny like wax 〔","cn":"像蜡般〕苍白的﹐光亮的"},{"en":"made from wax","cn":"蜡制的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41waxen.mp3","us":"media/ldoce/hwd/ame/d/waxen.mp3"},"examples":[{"en":"a waxen face","cn":"苍白的脸"},{"en":"waxen images","cn":"蜡像"}],"oxford":{"phon":"ˈwæksn","pos":"adjective","senses":[{"en":"made of wax","cn":"蜡的；蜡制的；涂蜡的","lab":"formal","ex":{"en":"waxen images","cn":"蜡像"}},{"en":"pale and looking ill","cn":"苍白的；病态的","lab":"literary","ex":{"en":"a waxen face","cn":"苍白的脸"}}]}},"wager":{"collins":{"senses":[{"pos":"VERB 动词","cn":"押(赌注);打赌","en":"If you wager on the result of a horse race, football match, or other event, you give someone a sum of money which they give you back with extra money if the result is what you predicted, or which they keep if it is not.","ex":{"en":"Just because people wagered on the Yankees did not mean that they liked them","cn":"人们将赌注下在扬基队上并不说明就喜欢他们。"}},{"pos":"VERB 动词","cn":"(表示很确定)打赌，保证","en":"If you say that you will wager that something is the case, you mean you are confident that it is the case.","ex":{"en":"She was willing to wager that he didn't own the apartment he lived in","cn":"她愿意打赌他居住的公寓并不属于他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an agreement in which you win or lose money according to the result of something such as a race","cn":"打赌"},{"en":"to agree to win or lose an amount of money on the result of something such as a race","cn":"押〔赌注〕﹐打赌"},{"en":"used to say that you are confident that something is true","cn":"我敢打赌"}]},"vocab":{"pos":"n v","senses":[{"en":"To wager is to bet: you might say to your fellow train passengers, \"I'll wager ten dollars that we won't get to Chicago on time.\""}]},"media":{"uk":"media/ldoce/hwd/bre/5/wager_v0205.mp3","us":"media/ldoce/hwd/ame/d/wager1.mp3"},"examples":[{"en":"I had wagered a great deal of money that I would beat him.","cn":"我下了大赌注打赌，这次比赛我会赢他的。"},{"en":"She always wagered on an outsider.","cn":"她总是把赌注押在不大可能获胜的马上。"}],"oxford":{"phon":"ˈweɪdʒə(r)","pos":"noun","senses":[{"en":"an arrangement to risk money on the result of a particular event","cn":"打赌"},{"en":"to bet money","cn":"打赌；押（赌注）","g":"[intransitive, transitive]","ex":{"en":"She always wagered on an outsider.","cn":"她总是把赌注押在不大可能获胜的马上。"},"pos":"verb"},{"en":"used to say that you are so confident that something is true or will happen that you would be willing to bet money on it","cn":"打赌；打包票","g":"[transitive]","ex":{"en":"I'll wager that she knows more about it than she's saying.","cn":"我敢打赌，她知道的比她说的要多。"},"pos":"verb"}]}},"watchword":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"口号;格言","en":"Someone's watchword is a word or phrase that sums up their attitude or approach to a particular subject or to things in general.","ex":{"en":"Caution has been one of Mr Allan's watchwords","cn":"“小心谨慎”是艾伦先生的座右铭。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word or phrase that expresses an attitude or belief","cn":"口号﹔标语﹔格言"}]},"media":{"uk":"media/ldoce/hwd/bre/1/watchword0205.mp3","us":"media/ldoce/hwd/ame/e/watchword.mp3"},"examples":[{"en":"Quality is our watchword.","cn":"质量是我们的口号。"},{"en":"Environmental quality will be the watchword for the 21st century.","cn":"环境质量将是21世纪的口号。"}],"oxford":{"phon":"ˈwɒtʃwɜːd","pos":"noun","senses":[{"en":"a word or phrase that expresses somebody’s beliefs or attitudes, or that explains what somebody should do in a particular situation","cn":"口号；标语；格言","ex":{"en":"Quality is our watchword.","cn":"品质至上是我们的口号。"}}]}},"wade":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(艰难地)涉，蹚，跋涉","en":"If you wade through something that makes it difficult to walk, usually water or mud, you walk through it.","ex":{"en":"Rescuers had to wade across a river to reach them","cn":"救援者必须蹚过一条河才能靠近他们。"}},{"pos":"VERB 动词","cn":"费力地阅读;艰难地处理","en":"To wade through a lot of documents or pieces of information means to spend a lot of time and effort reading them or dealing with them.","ex":{"en":"It has taken a long time to wade through the 'incredible volume' of evidence","cn":"看完这一大卷“长篇累牍”的证词花费了很长的时间。"}},{"pos":"","cn":"","en":"相关词组：wade in"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move forward by putting one foot in front of the other","cn":""},{"en":"to walk without any clear purpose or direction","cn":""},{"en":"to walk with long steps in a determined, confident, or angry way","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To wade is to walk through water. If you've been fishing without a boat, chances are you've gone for a wade to reach your precious prize (and if it got away, exaggerated how big it was.)"}]},"collocations":{"phrases":["ADV. ashore The men waded ashore. | out","PREP. across, in, into, through We waded across the stream.","PHRASES wade knee-deep/waist-deep Rescuers had to wade waist-deep in flood water."]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdewade.mp3","us":"media/ldoce/hwd/ame/3/wade.mp3"},"examples":[{"en":"You shouldn't have waded in with all those unpleasant accusations.","cn":"你本不该插一杠子，横加指责，让人难受。"},{"en":"Sometimes they had to wade waist-deep through mud.","cn":"有时他们得通过齐腰深的泥浆。"}],"oxford":{"phon":"weɪd","pos":"verb","senses":[{"en":"to walk with an effort through something, especially water or mud","cn":"跋涉，涉，蹚（水或淤泥等）","g":"[intransitive, transitive]","ex":{"en":"He waded into the water to push the boat out.","cn":"他蹚进水里把船推出来。"}},{"en":"to walk or stand with no shoes or socks in shallow water in the sea, a lake, etc.","cn":"蹚水；赤足涉水","g":"[intransitive]","lab":"North American English"}]}},"waterline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(船的)吃水线;(船的)水平线","en":"The waterline is a line, either real or imaginary, on the side of a ship representing the level the water reaches when the ship is at sea.","ex":{"en":"Ray painted below the waterline with a special anti-rust paint.","cn":"雷用专门的防锈涂料涂船的吃水线以下的部位。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the level that water reaches on the side of a ship etc 〔","cn":"船的〕吃水线"},{"en":"the edge of a large area of water, especially the sea, where it joins the land","cn":"水位线﹔〔尤指〕海岸线"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41waterline.mp3","us":"media/ldoce/hwd/ame/c/waterline.mp3"},"examples":[{"en":"Two torpedoes struck below the waterline.","cn":"两颗鱼雷击中船身吃水线以下部位。"},{"en":"As the waterline advanced, the vegetation was swamped.","cn":"随着海岸线的前移﹐植被被淹没了。"}]},"water-resistant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"抗水的；不易被水损坏的","en":"Something that is water-resistant does not allow water to pass through it easily, or is not easily damaged by water.","ex":{"en":"Microfibre fabrics are both water resistant and windproof","cn":"微纤维织物既防水又防风。"}}]},"examples":[{"en":"a water-resistant jacket","cn":"防水上衣"}],"oxford":{"phon":"ˈwɔːtə rɪzɪstənt","pos":"adjective","senses":[{"en":"that does not let water through easily","cn":"有抗水作用的；防水的","ex":{"en":"a water-resistant jacket","cn":"防水上衣"}}]}},"washrag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 washcloth","en":"A wash-rag is the same as a washcloth ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a washcloth","cn":"毛巾"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld44washrag.mp3","us":"media/ldoce/hwd/ame/2/ld42washrag.mp3"}},"walrus":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海象","en":"A walrus is a large, fat animal which lives in the sea. It has two long teeth called tusks that point downwards."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large sea animal with two long tusk s (= things like teeth ) coming down from the sides of its mouth","cn":"海象"}]},"media":{"uk":"media/ldoce/hwd/bre/d/walrus0205.mp3","us":"media/ldoce/hwd/ame/b/walrus.mp3"},"oxford":{"phon":"ˈwɔːlrəs","pos":"noun","senses":[{"en":"an animal like a large seal (= a sea animal with thick fur, that eats fish and lives around coasts), that has two long outer teeth called tusks and lives in Arctic regions","cn":"海象（形似海豹，獠牙较长，栖息在北极海域）"}]}},"wanderlust":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"漫游癖;旅行癖","en":"Someone who has wanderlust has a strong desire to travel.","ex":{"en":"His wanderlust would not allow him to stay long in one spot.","cn":"他酷爱旅游，无法在一个地方久留。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong desire to travel and to experience life in other countries","cn":""},{"en":"the desire to travel, which makes it difficult for you to stay in one place for very long","cn":""},{"en":"a strong desire to travel to different places","cn":"旅游癖﹐漫游癖"}]},"vocab":{"pos":"n","senses":[{"en":"A strong desire to travel is called a wanderlust . If you dream of backpacking through Europe, you have a wanderlust . (You probably also have unwashed dreadlocked hair and a wardrobe nearly entirely made of fleece. If not, you will soon.)"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41wanderlust.mp3","us":"media/ldoce/hwd/ame/3/wanderlust.mp3"},"oxford":{"phon":"ˈwɒndəlʌst","pos":"noun","senses":[{"en":"a strong desire to travel","cn":"漫游癖；旅行癖"}]}},"wag":{"collins":{"senses":[{"pos":"VERB 动词","cn":"摇动，摇摆(尾巴)","en":"When a dog wags its tail, it repeatedly waves its tail from side to side.","ex":{"en":"The dog was biting, growling and wagging its tail.","cn":"这条狗撕咬着，咆哮着，摇晃着尾巴。"}},{"pos":"VERB 动词","cn":"(通常指由于厌恶而)左右摇晃(手指)","en":"If you wag your finger, you shake it repeatedly and quickly from side to side, usually because you are annoyed with someone.","ex":{"en":"He wagged a disapproving finger","cn":"他摇晃着手指表示不同意。"}},{"pos":"VERB 动词","cn":"(常指因不高兴而)摇(头)","en":"If you wag your head, you move it from side to side, often because you are unhappy about a situation.","ex":{"en":"He wags his head unhappily.","cn":"他不高兴地摇着头。"}},{"pos":"N-COUNT 可数名词","cn":"爱说笑的人；幽默的人","en":"A wag is someone who makes jokes.","ex":{"en":"He's a bit of a wag, his dad","cn":"他爸爸这个人说话相当风趣。"}},{"pos":"PHRASE 短语","cn":"嚼舌头;议论纷纷","en":"If tongues are wagging, people are talking a lot about someone and their behaviour.","ex":{"en":"What set tongues wagging was the age difference between the two partners.","cn":"这对伴侣年龄上的差异招来了不少闲话。"}},{"pos":"","cn":"","en":"the tail is wagging the dog→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move your toes, fingers, bottom etc with a series of small movements","cn":""},{"en":"to move part of your body, especially your bottom, legs, or toes, from side to side or up and down, with fairly large movements","cn":""},{"en":"if a dog wags its tail, it moves its tail from side to side; if a person wags their finger or head, they shake it repeatedly, especially in order to show that they do not like something that someone has done","cn":""}]},"collocations":{"phrases":["ADV. furiously The dog raced ahead, its tail wagging furiously."]},"media":{"uk":"media/ldoce/hwd/bre/a/wag_n0205.mp3","us":"media/ldoce/hwd/ame/5/wag1.mp3"},"examples":[{"en":"Wags at the World Cup","cn":"世界杯足球赛中的太太女友团"},{"en":"Are WAGs good role models for girls?","cn":"体坛明星的娇妻﹑女友是女孩们的榜样吗？"}],"oxford":{"phon":"wæɡ","pos":"verb","senses":[{"en":"if a dog wags its tail, or its tail wags, its tail moves from side to side several times","cn":"（狗）摇，摆动（尾巴）；（狗尾巴）摇，摆动","g":"[transitive, intransitive]","ex":{"en":"The dog raced ahead, its tail wagging furiously.","cn":"狗向前冲去，尾巴猛烈地摇摆着 。"}},{"en":"to shake your finger or your head from side to side or up and down, often because you do not approve of something","cn":"摆动，摇（头或手指，常表示不赞成）","g":"[transitive]","ex":{"en":"‘Just remember what I said,’ she repeated, wagging her finger at him.","cn":"“记住我的话。”她重复道，朝他挥动了一下手指。"}},{"en":"to stay away from school without permission","cn":"旷课；逃学","g":"[transitive]","lab":"Australian English, New Zealand English，，","ex":{"en":"to wag school","cn":"逃学"}},{"en":"a person who enjoys making jokes","cn":"老开玩笑的人；爱闹着玩的人","lab":"especially British English, old-fashioned，，","pos":"noun"},{"en":"a wagging movement","cn":"摇摆；摆动","ex":{"en":"Flossie managed a feeble wag of her tail.","cn":"弗洛茜无力地摇了摇尾巴。"},"pos":"noun"},{"en":"one of a group of ‘wives and girlfriends’ of famous men, especially members of a sports team","cn":"（名人的，尤指运动队明星的）妻子女友团成员","ex":{"en":"Wags at the World Cup","cn":"世界杯足球赛中的太太女友团"},"pos":"noun"}]}},"waistband":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"裤腰;裙腰","en":"A waistband is a narrow piece of material which is sewn on to a pair of trousers, a skirt, or other item of clothing at the waist in order to strengthen it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a skirt, trousers etc that fastens around your waist","cn":"腰带﹔裙带﹔裤带"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41waistband.mp3","us":"media/ldoce/hwd/ame/b/waistband.mp3"},"examples":[{"en":"an elasticated waistband","cn":"松紧腰身"}],"oxford":{"phon":"ˈweɪstbænd","pos":"noun","senses":[{"en":"the piece of cloth that forms the waist of a piece of clothing, especially at the top of a skirt or pair of trousers","cn":"衣服腰；腰头；（尤指）裙腰，裤腰","ex":{"en":"an elasticated waistband","cn":"松紧腰身"}}]}},"waspish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尖刻的;脾气坏的","en":"A waspish remark or sense of humour is sharp and critical.","ex":{"en":"...a lawyer with an inventive mind and a waspish sense of humour.","cn":"一个富有创造力和尖锐幽默感的律师"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"bad-tempered and cruel in the things that you say","cn":"脾气暴躁的﹔言语刻薄的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41waspish.mp3","us":"media/ldoce/hwd/ame/c/waspish.mp3"},"examples":[{"en":"waspish remarks","cn":"恶毒的话语"}],"oxford":{"phon":"ˈwɒspɪʃ","pos":"adjective","senses":[{"en":"expressing criticism or showing that somebody is annoyed","cn":"尖刻的；恼怒的","ex":{"en":"a waspish remark","cn":"刻毒的话"}}]}},"warrant":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使显得必要(或正当)","en":"If something warrants a particular action, it makes the action seem necessary or appropriate for the circumstances.","ex":{"en":"The allegations are serious enough to warrant an investigation","cn":"这些指控很严重，有必要进行一番调查。"}},{"pos":"N-COUNT 可数名词","cn":"搜查令;拘捕令；令状","en":"A warrant is a legal document that allows someone to do something, especially one that is signed by a judge or magistrate and gives the police permission to arrest someone or search their house.","ex":{"en":"Police confirmed that they had issued a warrant for his arrest.","cn":"警方证实他们已经签发了对他的拘捕令。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"正当理由","en":"If you say that there is no warrant for something, you mean that there is no good reason to justify it.","ex":{"en":"There is some warrant for holding back on full-scale aid.","cn":"有理由不进行全面援助。"}},{"pos":"VERB 动词","cn":"保证;担保","en":"If you warrant that something is true or will happen, you say officially that it is true, or guarantee that it will happen.","ex":{"en":"All entrants must warrant that their entry is entirely their own work","cn":"所有参赛者必须保证其参赛作品完全是自己创作的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official document that gives you permission to do something, for example permission to work somewhere or visit somewhere","cn":""},{"en":"an official document that allows you to do something, for example to drive a car or own a gun","cn":""},{"en":"a document giving the police permission to take someone in order to ask them questions, or to search inside a building","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you watch cop shows, you know that a warrant is something police need to get into your house — a permission slip from a judge."}]},"collocations":{"phrases":["ADJ. arrest, death, search The king refused to sign the death warrant for his old friend. | royal","VERB + WARRANT authorize, grant, issue, serve, sign The commissioner has issued a warrant for her arrest. The police served a warrant on him","WARRANT + NOUN card","PHRASES without a ~ In certain circumstances, police may enter premises without a warrant. | ~ for"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdewarrant.mp3","us":"media/ldoce/hwd/ame/4/warrant1.mp3"},"examples":[{"en":"The situation scarcely warrants their/them being dismissed.","cn":"这种情况很难证明解雇他们是正当的。"},{"en":"They had a warrant to search the house.","cn":"他们有搜查这座房子的搜查令。"}],"oxford":{"phon":"ˈwɒrənt","pos":"noun","senses":[{"en":"a legal document that is signed by a judge and gives the police authority to do something","cn":"执行令；授权令","g":"[countable]","ex":{"en":"an arrest warrant","cn":"逮捕证"}},{"en":"a document that gives you the right to receive money, services, etc.","cn":"（接受款项、服务等的）凭单，许可证","g":"[countable]","ex":{"en":"the issue of warrants for equity shares","cn":"发行认股权证"}},{"en":"an acceptable reason for doing something","cn":"（做某事的）正当理由，依据","g":"[uncountable]","lab":"formal","ex":{"en":"There is no warrant for such criticism.","cn":"这种批评毫无根据。"}},{"en":"to make something necessary or appropriate in a particular situation","cn":"使有必要；使正当；使恰当","ex":{"en":"Further investigation is clearly warranted.","cn":"进一步调查显然是必要的。"},"pos":"verb"}]}},"warden":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"监督员;管理员","en":"A warden is a person who is responsible for a particular place or thing, and for making sure that the laws or regulations that relate to it are obeyed.","ex":{"en":"He was a warden at the local parish church","cn":"他是当地教堂的管理员。"}},{"pos":"N-COUNT 可数名词","cn":"监狱长;典狱长","en":"The warden of a prison is the person in charge of it.","ex":{"en":"A new warden took over the prison.","cn":"一位新的监狱长接管了这所监狱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person who is responsible for a particular place and whose job is to make sure its rules are obeyed 〔","cn":"监督规章制度执行的〕监察员﹐管理人"},{"en":"the person in charge of a prison","cn":"监狱长"},{"en":"someone who takes care of a building and the people in it, for example a place such as a home for old people 〔","cn":"养老院等的〕管理员﹐监管员"}]},"vocab":{"pos":"n","senses":[{"en":"The person who works at a jail as the boss of all the prison guards is called the warden ."}]},"collocations":{"phrases":["ADJ. chief, head | deputy | church, college, prison | park | game He is chief game warden of the Masai Mara game reserve in Kenya. | traffic"]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41warden.mp3","us":"media/ldoce/hwd/ame/c/warden.mp3"},"examples":[{"en":"the Warden of Wadham College, Oxford","cn":"牛津大学沃德姆学院院长"},{"en":"( BrE ) the warden of a youth hostel","cn":"青年旅舍的管理员"}],"oxford":{"phon":"ˈwɔːdn","pos":"noun","senses":[{"en":"a person who is responsible for taking care of a particular place and making sure that the rules are obeyed","cn":"管理人；看守人；监护人","lab":"British English","ex":{"en":"a forest warden","cn":"护林员"}},{"en":"the person in charge of a prison","cn":"监狱长","lab":"especially North American English"},{"en":"(especially in England), a title given to the head of some colleges and institutions","cn":"（英国）学院院长，协会会长，机构主管","ex":{"en":"the Warden of Wadham College, Oxford","cn":"牛津大学沃德姆学院院长"}}]}},"walkout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"罢工","en":"A walkout is a strike."},{"pos":"N-COUNT 可数名词","cn":"(会议上表示反对的)离席，退场","en":"If there is a walkout during a meeting, some or all of the people attending it leave in order to show their disapproval of something that has happened at the meeting.","ex":{"en":"The commission's proceedings have been wrecked by tantrums and walkouts.","cn":"委员会的议程因与会者的撒泼捣乱和离席抗议而受阻。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when people stop working or leave a meeting as a protest 〔","cn":"表示抗议的〕罢工﹐退席﹐退场"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41walkout.mp3","us":"media/ldoce/hwd/ame/6/walkout.mp3"},"examples":[{"en":"Members of the Irish delegation staged a walk-out .","cn":"爱尔兰代表团成员全体退席表示抗议。"}],"oxford":{"phon":"ˈwɔːkaʊt","pos":"noun","senses":[{"en":"a sudden strike by workers","cn":"（突然的）罢工","ex":{"en":"200 employees staged a walkout in protest at the new pay deal.","cn":"200名员工举行罢工，抗议新的薪酬协议。"}},{"en":"the act of suddenly leaving a meeting as a protest against something","cn":"（为表示抗议而突然的）退场，退席"}]}},"ward":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"病房;病室","en":"A ward is a room in a hospital which has beds for many people, often people who need similar treatment.","ex":{"en":"A toddler was admitted to the emergency ward with a wound in his chest.","cn":"一个蹒跚学步的小孩因胸部受伤被送进急救室。"}},{"pos":"N-COUNT 可数名词","cn":"区;行政区;选区","en":"A ward is a district which forms part of a political constituency or local council.","ex":{"en":"...the marginal wards of Reading Kentwood and Tilehurst West.","cn":"边缘选区雷丁肯特伍德和西泰尔赫斯特"}},{"pos":"N-COUNT 可数名词","cn":"被监护人","en":"A ward or a ward of court is a child who is the responsibility of a person called a guardian, or of a court of law, because their parents are dead or because they are believed to be in need of protection.","ex":{"en":"Alex was made a ward of court.","cn":"亚历克斯由法院监护。"}},{"pos":"","cn":"","en":"相关词组：ward off"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a hospital where people who are injured or who need urgent treatment are brought","cn":""},{"en":"a room in a hospital where operations are done","cn":""},{"en":"the part of a hospital where people who are very seriously ill or badly injured are cared for","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A ward is a group of rooms or a section in a hospital or prison; in a hospital, different wards deal with different needs, like the psychiatric ward or maternity ward ."}]},"collocations":{"phrases":["ADJ. open, public | private | hospital | maternity, surgical, etc.","VERB + WARD be admitted to He was admitted to the casualty ward. | be discharged from","WARD + NOUN nurse, sister, staff | round The doctor was doing her morning ward round.","PREP. in a/the ~ She spent five days in the maternity ward. | on the ~ How many midwives are on the ward?"]},"media":{"uk":"media/ldoce/hwd/bre/f/ward_v0205.mp3","us":"media/ldoce/hwd/ame/f/ward1.mp3"},"examples":[{"en":"He worked as a nurse on the children's ward.","cn":"他在儿科病房当护士。"},{"en":"The child was made a ward of court.","cn":"这个孩子由法院监护。"}],"oxford":{"phon":"wɔːd","pos":"noun","senses":[{"en":"a separate room or area in a hospital for people with the same type of medical condition","cn":"病房；病室","ex":{"en":"a maternity/surgical/psychiatric/children’s ward","cn":"产科／外科／精神科／儿科病房"}},{"en":"(in the UK) one of the areas into which a city or town is divided and which elects and is represented by a member of the local council","cn":"（英国城市中可选出一位地方议员的）区，选区"},{"en":"a person, especially a child, who is under the legal protection of a court or another person (called a guardian)","cn":"被监护人（受法院或监护人保护的人，尤指儿童）","lab":"law","ex":{"en":"The child was made a ward of court.","cn":"这个孩子由法院监护。"}},{"en":"in the direction of","cn":"在…方向（的）；朝…方向（的）","ex":{"en":"backward","cn":"向后的"},"pos":"suffix"}]}},"waterworks":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自来水厂;供水系统","en":"A waterworks is a building where a supply of water is stored and cleaned before being distributed to the public."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to suddenly start to cry because you are upset about something","cn":""},{"en":"to suddenly start to cry a lot, after trying not to cry","cn":""},{"en":"to deliberately start to cry in order to get someone's sympathy or persuade them to do something","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41waterworks.mp3","us":"media/ldoce/hwd/ame/1/waterworks.mp3"},"examples":[{"en":"‘Don’t turn on the waterworks,’ he sighed. “","cn":"别哭了。”他叹了口气说。"}],"oxford":{"phon":"ˈwɔːtəwɜːks","pos":"noun","senses":[{"en":"a building with machines for supplying water to an area","cn":"（自来）水厂","g":"[countable + singular or plural verb]"},{"en":"the organs of the body through which urine (= waste water) is passed","cn":"（人体的）排水系统；泌尿系统","g":"[plural]","lab":"informal or humorous"}]}},"warbler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸣禽;刺嘴莺","en":"Warblers are a family of small birds that have a pleasant song."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bird that can make musical sounds","cn":"鸣禽"},{"en":"a singer, especially one who does not sing very well – used humorously 〔","cn":"尤指唱得不好的〕歌手〔幽默用法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41warbler.mp3","us":"media/ldoce/hwd/ame/b/warbler.mp3"},"oxford":{"phon":"ˈwɔːblə(r)","pos":"noun","senses":[{"en":"a small bird. There are many types of warbler, some of which have a musical call.","cn":"莺（有些能发出悦耳的啭鸣）"}]}},"wacko":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"古怪的;乖僻的","en":"If you say that someone is wacko, you are saying in an unkind way that they are strange and eccentric.","ex":{"en":"Lampley was obviously completely wacko.","cn":"毫无疑问,兰普利完全疯了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a crazy or strange person","cn":"疯子﹔怪人"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41wacko.mp3","us":"media/ldoce/hwd/ame/f/laadwacko.mp3"},"examples":[{"en":"wacko opinions","cn":"古怪的看法"}],"oxford":{"phon":"ˈwækəʊ","pos":"adjective","senses":[{"en":"crazy; not sensible","cn":"古怪的；发疯的；不理智的","ex":{"en":"wacko opinions","cn":"古怪的看法"}},{"en":"an offensive word for a person who you think is crazy","cn":"疯子","pos":"noun"}]}},"wander":{"collins":{"senses":[{"pos":"VERB 动词","cn":"漫步;闲逛;游荡","en":"If you wander in a place, you walk around there in a casual way, often without intending to go in any particular direction.","ex":{"en":"When he got bored he wandered around the fair","cn":"他烦了就去集市上逛逛。"}},{"pos":"VERB 动词","cn":"迷路;迷失方向","en":"If a person or animal wanders from a place where they are supposed to stay, they move away from the place without going in a particular direction.","ex":{"en":"Because Mother is afraid we'll get lost, we aren't allowed to wander far","cn":"妈妈生怕我们迷路，不准我们走远。"}},{"pos":"VERB 动词","cn":"走神;开小差","en":"If your mind wanders or your thoughts wander, you stop concentrating on something and start thinking about other things.","ex":{"en":"His mind would wander, and he would lose track of what he was doing","cn":"他会走神，忘了自己正在干什么。"}},{"pos":"VERB 动词","cn":"(目光)游离","en":"If your eyes wander, you stop looking at one thing and start looking around at other things.","ex":{"en":"His eyes wandered restlessly around the room","cn":"他的眼睛不安地转来转去，打量着房间。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move forward by putting one foot in front of the other","cn":""},{"en":"to walk without any clear purpose or direction","cn":""},{"en":"to walk with long steps in a determined, confident, or angry way","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"The verb wander describes something that has lost track. If you're watching a boring movie, your mind might begin to wander . If you don't have a clear goal, you could wander too — meaning you drift aimlessly."}]},"collocations":{"phrases":["ADV. slowly | aimlessly | disconsolately, restlessly | happily | at will, freely The cattle are allowed to wander freely. | just, simply Sim","VERB + WANDER be free to Visitors are free to wander through the gardens and woods. | allow sb/sth to, let sb/sth How could you let him wand","PREP. across, all over, along, among, around, into, out of, round, through, towards Don't go wandering all over the house! He wandered into ","PHRASES find sb wandering They found him wandering around aimlessly. 2 stop concentrating","ADV. a little","VERB + WANDER begin to His attention was beginning to wander. | allow sth to, let sth Lissa let her mind wander a little.","PREP. from, to My thoughts wandered from the exam questions to my interview the next day."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdewander.mp3","us":"media/ldoce/hwd/ame/e/wander.mp3"},"examples":[{"en":"Her thoughts wandered back to her youth.","cn":"她浮想联翩，思绪回到了青春岁月。"},{"en":"She wandered aimlessly around the streets.","cn":"她在大街上漫无目的地到处游荡。"}],"oxford":{"phon":"ˈwɒndə(r)","pos":"verb","senses":[{"en":"to walk slowly around or to a place, often without any particular sense of purpose or direction","cn":"闲逛；漫游；游荡","g":"[intransitive, transitive]","ex":{"en":"She wandered aimlessly around the streets.","cn":"她在大街上漫无目的地到处游荡。"}},{"en":"to move away from the place where you ought to be or the people you are with","cn":"偏离（正道）；走失；离散","g":"[intransitive]","ex":{"en":"The child wandered off and got lost.","cn":"那孩子走散后迷路了。"}},{"en":"to stop being directed on something and to move without much control to other ideas, subjects, etc.","cn":"走神；神志恍惚；（思想）开小差","g":"[intransitive]","ex":{"en":"It's easy to be distracted and let your attention wander.","cn":"很容易走神分散注意力。"}},{"en":"to move slowly from looking at one thing to looking at another thing or in other directions","cn":"慢慢地移开","g":"[intransitive]","ex":{"en":"She let her gaze wander.","cn":"她东瞅瞅西望望。"}},{"en":"to go in a curve instead of following a straight course","cn":"蜿蜒；迂回曲折","g":"[intransitive]","ex":{"en":"The road wanders along through the hills.","cn":"这条路蜿蜒曲折地穿过山丘。"}},{"en":"a short walk in or around a place, usually with no special purpose","cn":"游荡；溜达；闲逛；徘徊","ex":{"en":"I went to the park and had a wander around.","cn":"我去公园转了一圈。"},"pos":"noun"}]}},"washed-out":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色)暗淡的，没有光泽的","en":"Washed-out colours are very pale.","ex":{"en":"He stared at me out of those washed-out blue eyes.","cn":"他用暗淡无神的蓝眼睛盯着我看。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精疲力竭的;疲惫不堪的","en":"If someone looks washed-out, they look very tired and lacking in energy.","ex":{"en":"She looked washed out and listless.","cn":"她看上去精疲力竭而且情绪低落。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"looking tired and unhealthy","cn":""},{"en":"with red, half-open eyes, especially as a result of lack of sleep","cn":""},{"en":"someone who looks drawn is tired from illness, worry, or working too hard, and their face looks thin and pale","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/washed_out0205.mp3","us":"media/ldoce/hwd/ame/b/washed-out.mp3"},"examples":[{"en":"Debbie’s looking a bit washed-out.","cn":"黛比看上去有点疲倦。"},{"en":"a washed-out shade of blue","cn":"褪淡的蓝色"}],"oxford":{"phon":"ˌwɒʃt ˈaʊt","pos":"adjective","senses":[{"en":"no longer brightly coloured, often as a result of being washed many times","cn":"（洗后）褪色的","ex":{"en":"She didn't like jeans that looked too washed out.","cn":"她不喜欢看起来褪色厉害的牛仔裤。"}},{"en":"pale and tired","cn":"苍白无力的；疲惫的","ex":{"en":"He always looks washed out at the end of the week.","cn":"他在周末总是满脸倦色。"}}]}},"warm-blooded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(动物)温血的，恒温的","en":"A warm-blooded animal, for example a bird or a mammal, has a fairly high body temperature which does not change much and is not affected by the surrounding temperature."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"animals that are warm-blooded have a body temperature that remains fairly high whether the temperature around them is hot or cold 〔","cn":"动物〕温血的﹐恒温的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41warm-blooded.mp3","us":"media/ldoce/hwd/ame/1/warm-blooded.mp3"},"oxford":{"phon":"ˌwɔːm ˈblʌdɪd","pos":"adjective","senses":[{"en":"having a warm blood temperature that does not change if the temperature around them changes","cn":"温血的；恒温的"}]}},"warmonger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"战争贩子（试图挑起战争的政客）","en":"If you describe a politician or leader as a warmonger, you disapprove of them because you think they are encouraging people to start or join a war."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a politician or a military leader, who is too keen to start wars or to settle arguments by starting a war","cn":""},{"en":"someone, especially a politician or a military leader, who is too keen to increase the size and power of their country's armed forces so that it can attack other countries","cn":""},{"en":"a person, especially a politician, who supports the use of military force and strong action in order to settle arguments with other countries","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A warmonger is someone strongly pro-war. Warmongers favor war above all other options."}]},"media":{"uk":"media/ldoce/hwd/bre/c/warmonger0205.mp3","us":"media/ldoce/hwd/ame/9/warmonger.mp3"},"oxford":{"phon":"ˈwɔːmʌŋɡə(r)","pos":"noun","senses":[{"en":"a person, especially a politician or leader, who wants to start a war or encourages people to start a war","cn":"战争贩子"}]}},"waltz":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"华尔兹舞曲;圆舞曲","en":"A waltz is a piece of music with a rhythm of three beats in each bar, which people can dance to.","ex":{"en":"...Tchaikovsky's 'Waltz of the Flowers'.","cn":"柴可夫斯基的《花之圆舞曲》"}},{"pos":"N-COUNT 可数名词","cn":"华尔兹舞","en":"A waltz is a dance in which two people hold each other and move around the floor doing special steps in time to waltz music.","ex":{"en":"Arthur Murray taught the foxtrot, the tango and the waltz.","cn":"阿瑟·默里教狐步舞、探戈和华尔兹。"}},{"pos":"V-RECIP 相互动词","cn":"跳华尔兹舞","en":"If you waltz with someone, you dance a waltz with them.","ex":{"en":"'Waltz with me,' he said, taking her hand","cn":"“来和我跳支华尔兹吧，”他边说边牵起她的手。"}},{"pos":"VERB 动词","cn":"(像跳华尔兹舞一样)轻松自如地进行，游刃有余地做","en":"If you say that someone waltzes somewhere, you mean that they do something in a relaxed and confident way.","ex":{"en":"She's probably got herself a new man and gone waltzing off with him","cn":"她极有可能有了新男友，和他的感情发展得一日千里。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fairly slow dance with a regular pattern of three beats","cn":"华尔兹舞"},{"en":"a piece of music intended for this type of dance","cn":"华尔兹舞曲﹐圆舞曲"},{"en":"to dance a waltz","cn":"跳华尔兹舞"}]},"collocations":{"phrases":["ADJ. slow | Viennese","VERB + WALTZ dance, do | play","WALTZ + NOUN rhythm, time"]},"media":{"uk":"media/ldoce/hwd/bre/c/ld44waltz.mp3","us":"media/ldoce/hwd/ame/a/waltz1.mp3"},"examples":[{"en":"I don't like him waltzing into the house as if he owned it.","cn":"我不喜欢他像房主似地大摇大摆走进屋来。"},{"en":"The recruits have waltzed through their training.","cn":"新招收的成员轻松顺利地完成了训练。"}],"oxford":{"phon":"wɔːls","pos":"noun","senses":[{"en":"a dance in which two people dance together to a regular rhythm; a piece of music for this dance","cn":"华尔兹舞；华尔兹舞曲；圆舞曲","ex":{"en":"to dance a/the waltz","cn":"跳华尔兹舞"}},{"en":"to dance a waltz","cn":"跳华尔兹舞","g":"[intransitive, transitive]","ex":{"en":"I watched them waltzing across the floor.","cn":"我望着他们跳着华尔兹在舞池中旋转。"},"pos":"verb"},{"en":"to walk or go somewhere in a very confident way","cn":"大摇大摆地走","g":"[intransitive]","lab":"informal","ex":{"en":"I don't like him waltzing into the house as if he owned it.","cn":"我不喜欢他像房主似的大摇大摆走进屋来。"},"pos":"verb"},{"en":"to complete or achieve something without any difficulty","cn":"轻易完成；轻而易举地取得","g":"[intransitive]","ex":{"en":"The recruits have waltzed through their training.","cn":"新招收的成员轻松顺利地完成了训练。"},"pos":"verb"}]}},"waterborne":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（疾病等）经水传染的，由水传播的","en":"A water-borne disease or infection is one that people can catch from infected water.","ex":{"en":"UN officials are warning of an outbreak of cholera and other water-borne diseases.","cn":"美国官方发出了霍乱和其他经水传播的疾病可能会爆发的警告。"}},{"pos":"ADJ 形容词","cn":"水上的;水运的","en":"Something that is water-borne travels or is transported on water.","ex":{"en":"...a waterborne safari down the Nile","cn":"尼罗河水上观光游"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"spread or carried by water","cn":"由水传播的﹔由水运送的"},{"en":"→ airborne waterborne disease/illness etc waterborne diseases such as cholera","cn":"霍乱等经水传播的疾病 waterborne traffic 水上交通"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41waterborne.mp3","us":"media/ldoce/hwd/ame/6/waterborne.mp3"},"examples":[{"en":"cholera and other waterborne diseases","cn":"霍乱等经水传染疾病"},{"en":"waterborne goods","cn":"水运货物"}],"oxford":{"phon":"ˈwɔːtəbɔːn","pos":"adjective","senses":[{"en":"spread or carried by water","cn":"水传播的；水源传染的；经水路的；水运的","ex":{"en":"cholera and other waterborne diseases","cn":"霍乱等经水传染疾病"}}]}},"waffle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"胡扯;胡说;废话连篇","en":"If you say that someone waffles, you are critical of them because they talk or write a lot without actually making any clear or important points.","ex":{"en":"My wife often tells me I waffle","cn":"我妻子经常说我胡说八道。"}},{"pos":"VERB 动词","cn":"犹豫不决;含糊其词","en":"If someone waffles on an issue or question, they cannot decide what to do or what their opinion is about it.","ex":{"en":"He's waffled on abortion and gay rights","cn":"他在堕胎和同性恋权利问题上立场模糊。"}},{"pos":"N-COUNT 可数名词","cn":"华夫饼","en":"A waffle is a kind of square cake made of batter with squares marked on it. Waffles are usually eaten with syrup poured over them."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat cake, marked with a pattern of deep squares 〔","cn":"带四方深纹的〕华夫饼﹐蛋奶烘饼"},{"en":"talk or writing that uses a lot of words but says nothing important","cn":"胡扯﹐冗长的空话"},{"en":"to use words to communicate with someone about something","cn":""}]},"vocab":{"pos":"1 n 2 v","senses":[{"en":"You might think of a waffle as a grid-patterned pancake-like food that's tasty with syrup, and you'd be right. But the word is also a verb that means to avoid making a definitive decision."}]},"media":{"img":["media/ldoce/img/waffle.jpg"],"uk":"media/ldoce/hwd/bre/4/brelasdewaffle.mp3","us":"media/ldoce/hwd/ame/d/waffle1.mp3"},"examples":[{"en":"The principal waffled on about exam results but no one was listening.","cn":"校长絮絮叨叨地谈着考试结果，但是谁也没有听进去。"},{"en":"The senator was accused of waffling on major issues.","cn":"人们指责参议员在主要问题上立场模糊。"}],"oxford":{"phon":"ˈwɒfl","pos":"noun","senses":[{"en":"a dry, flat cake with a pattern of squares on both sides, often eaten with sweet sauce, cream, etc. on top","cn":"华夫饼，蛋奶烘饼（两面有方块图案，常涂以糖浆、奶油等）","g":"[countable]","ex":{"en":"a waffle iron (= for making waffles with)","cn":"蛋奶烘饼烤模"}},{"en":"language that uses a lot of words but does not say anything important or interesting","cn":"胡扯；废话连篇","g":"[uncountable]","lab":"British English, informal，，","ex":{"en":"The report is just full of waffle.","cn":"这份报告只是一大堆废话。"}},{"en":"to talk or write using a lot of words but without saying anything interesting or important","cn":"胡扯；耍贫嘴；絮叨；胡写","g":"[intransitive]","lab":"British English, informal, disapproving，，，，","ex":{"en":"The principal waffled on about exam results but no one was listening.","cn":"校长絮絮叨叨地谈着考试结果，但是谁也没有听进去。"},"pos":"verb"},{"en":"to be unable to decide what to do about something or what you think about something","cn":"拿不定主意；三心二意","g":"[intransitive]","lab":"North American English, informal，，","ex":{"en":"The senator was accused of waffling on major issues.","cn":"人们指责参议员在主要问题上立场模糊。"},"pos":"verb"}]}},"wadi":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(北非或阿拉伯仅雨季有水的)干涸河道，干河谷","en":"A wadi is a river in North Africa or Arabia which is dry except in the rainy season."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a river bed in a desert which is usually dry but becomes full of water when there is a lot of rain 〔","cn":"沙漠中的〕干河床"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld5_wadi.mp3","us":"media/ldoce/hwd/ame/b/ld5_wadi.mp3"},"oxford":{"phon":"ˈwɒdi","pos":"noun","senses":[{"en":"(in the Middle East and North Africa) a valley or channel that is dry except when it rains","cn":"（中东和北非仅在雨后才有水的）干谷，干河谷"}]}},"wacky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"古怪的;乖僻的;滑稽可笑的","en":"If you describe something or someone as wacky, you mean that they are eccentric, unusual, and often funny.","ex":{"en":"...a wacky new television comedy series","cn":"新的搞笑电视系列喜剧"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"silly in an exciting or amusing way","cn":"疯疯癫癫的﹔古怪的﹔荒唐的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's wacky is weird or nutty or silly. Your goofy uncle who wears a funny hat and does magic tricks at the dinner table is wacky ."}]},"media":{"uk":"media/ldoce/hwd/bre/0/wacky0205.mp3","us":"media/ldoce/hwd/ame/b/wacky.mp3"},"examples":[{"en":"Some of his friends are pretty wild and wacky characters.","cn":"他的一些朋友是那种放荡不羁又怪里怪气的人。"},{"en":"wacky ideas","cn":"滑稽可笑的想法"}],"oxford":{"phon":"ˈwæki","pos":"adjective","senses":[{"en":"funny in a slightly crazy way","cn":"古怪的；滑稽可笑的；疯疯癫癫的","ex":{"en":"wacky ideas","cn":"滑稽可笑的想法"}}]}},"wastage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"浪费;耗费;浪费量;消耗量","en":"Wastage of something is the act of wasting it or the amount of it that is wasted.","ex":{"en":"...a series of measures to prevent the wastage of water","cn":"一系列节水措施"}},{"pos":"N-UNCOUNT 不可数名词","cn":"消瘦;衰弱","en":"Wastage is the process by which part of someone's body gets weaker or smaller because they are very ill or have not eaten enough.","ex":{"en":"This can lead to bodily weakness and muscle wastage.","cn":"这样可能会导致身体虚弱和肌肉萎缩。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(雇员的)减员;(尤指学生或学员的)流失人数","en":"Wastage refers to the number of people who leave a company, college, or other organization, especially before they have completed their education or training.","ex":{"en":"British universities have very little wastage and their graduates are good","cn":"英国大学的退学率很低，而且他们的毕业生很优秀。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something is lost or destroyed, especially in a way that is not useful or reasonable, or the amount that is lost or destroyed","cn":"浪费﹔耗费(量)﹐损耗(量)"},{"en":"a reduction in the number of workers because of people leaving, retiring etc and not because they have lost their jobs 〔","cn":"因离职﹑退休等引起的〕自然减员"}]},"collocations":{"phrases":["ADJ. excessive, high | natural Voluntary redundancies and natural wastage will cut staff numbers to the required level. | muscle Patients ne","VERB + WASTAGE avoid, prevent | minimize | cut down on, reduce | increase | allow for Buy more paper than you need to allow for wastage."]},"media":{"uk":"media/ldoce/hwd/bre/e/wastage0205.mp3","us":"media/ldoce/hwd/ame/6/wastage.mp3"},"examples":[{"en":"It was a new production technique aimed at minimizing wastage.","cn":"这是一项旨在使损耗减至最低的新生产技术。"},{"en":"Half of the posts will be lost through natural wastage.","cn":"有一半的职位通过自然减员将会丢失。"}],"oxford":{"phon":"ˈweɪstɪdʒ","pos":"noun","senses":[{"en":"the fact of losing or destroying something, especially because it has been used or dealt with carelessly","cn":"耗费；损耗；浪费","g":"[uncountable, singular]","ex":{"en":"It was a new production technique aimed at minimizing wastage.","cn":"这是一项旨在使损耗减至最低的新生产技术。"}},{"en":"the amount of something that is wasted","cn":"损耗量；耗费量；浪费量","g":"[uncountable]","ex":{"en":"There is little wastage from a lean cut of meat.","cn":"瘦肉基本上没有损耗。"}},{"en":"the loss of employees because they stop working or move to other jobs; the number of students who do not finish a particular course of study","cn":"（雇员的）减员；（学生的）流失人数","g":"[uncountable]","lab":"British English","ex":{"en":"Half of the posts will be lost through natural wastage.","cn":"有一半的职位通过自然减员将会丧失。"}}]}},"waiver":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"权利放弃,弃权;(规则或法律的)不强求执行","en":"A waiver is when a person, government, or organization agrees to give up a right or says that people do not have to obey a particular rule or law.","ex":{"en":"...a waiver of constitutional rights","cn":"对宪法赋予权利的放弃"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official written statement saying that a right, legal process etc can be waived","cn":"弃权声明书"}]},"vocab":{"pos":"n","senses":[{"en":"A waiver is a formal statement giving up a right. If you go on a school trip, your mom might sign a waiver saying that the school is not responsible if you get hurt on the trip."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41waiver.mp3","us":"media/ldoce/hwd/ame/8/waiver.mp3"},"oxford":{"phon":"ˈweɪvə(r)","pos":"noun","senses":[{"en":"a situation in which somebody gives up a legal right or claim; an official document stating this","cn":"（对合法权利或要求的）弃权；弃权声明"}]}},"warp":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(尤指因受热、受潮而)(使)翘曲,(使)变形","en":"If something warps or is warped, it becomes damaged by bending or curving, often because of the effect of heat or water.","ex":{"en":"Left out in the heat of the sun, tapes easily warp or get stuck in their cases","cn":"如果放在太阳下暴晒，磁带很容易翘曲或在磁带盒里黏结。"}},{"pos":"VERB 动词","cn":"扭曲；摧毁;不利于","en":"If something warps someone's character, it damages them or it influences them in a bad way.","ex":{"en":"I never had any toys, my father thought that they would warp my personal values","cn":"我从来没有任何玩具，我父亲认为它们会扭曲我的价值观。"}},{"pos":"N-COUNT 可数名词","cn":"（时间或空间的）扭曲，偏差，错觉","en":"A warp in time or space is an imaginary break or sudden change in the normal experience of time or space.","ex":{"en":"When a divorced woman re-enters the world of dating and romance, she's likely to feel as though she has entered a time warp.","cn":"当一个离了婚的女人重新进入约会和浪漫的世界时，她很可能有种回到从前的错觉。"}},{"pos":"N-SING 单数名词","cn":"经线;经纱","en":"In weaving, the warp is the threads which are held in a frame or machine called a loom while another thread is passed across through them."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a leaf or piece of cloth curls , it gradually bends, starting at its edges, especially as a result of heat or dryness","cn":""},{"en":"if something strong and hard buckles , it bends in the middle, usually because of very strong pressure or great heat","cn":""},{"en":"if something made of wood warps , it bends and twists slightly as a result of too much heat, dryness, age etc, so that it is no longer flat or straight","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/warp_las3_br.mp3","us":"media/ldoce/hwd/ame/1/warp1.mp3"},"examples":[{"en":"His judgement was warped by prejudice.","cn":"他因偏见而判断有误。"},{"en":"The window frames had begun to warp.","cn":"窗框已经开始变形。"}],"oxford":{"phon":"wɔːp","pos":"verb","senses":[{"en":"to become, or make something become twisted, or bent out of its natural shape, for example because it has become too hot, too wet, etc.","cn":"（使）扭曲，弯曲，变形","g":"[intransitive, transitive]","ex":{"en":"The window frames had begun to warp.","cn":"窗框已经开始变形。"}},{"en":"to influence somebody so that they begin to behave in an unacceptable way","cn":"使（行为等）不合情理；使乖戾","g":"[transitive]","ex":{"en":"His judgement was warped by prejudice.","cn":"他因偏见而判断有误。"}},{"en":"the threads on a loom (= a machine used for making cloth) that other threads are passed over and under in order to make cloth","cn":"（织布机上的）经线，经纱","pos":"noun"}]}},"wattage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"瓦数;瓦特数","en":"The wattage of a piece of electrical equipment is the amount of electrical power which it produces or uses, expressed in watts."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the power of a piece of electrical equipment, measured in watts 〔","cn":"电器的〕瓦(特)数"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41wattage.mp3","us":"media/ldoce/hwd/ame/2/wattage.mp3"},"oxford":{"phon":"ˈwɒtɪdʒ","pos":"noun","senses":[{"en":"an amount of electrical power expressed in watts","cn":"瓦数；瓦特数"}]}},"washed-up":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a person or an organization is washed-up, they will never be successful again 〔","cn":"人或组织〕彻底失败的﹐完蛋的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41washed-up.mp3","us":"media/ldoce/hwd/ame/5/washed-up.mp3"},"examples":[{"en":"a washed-up movie star","cn":"过气的电影明星"}],"oxford":{"phon":"ˌwɒʃt ˈʌp","pos":"adjective","senses":[{"en":"no longer successful and unlikely to succeed again in the future","cn":"（事业等）告吹的，完蛋的","ex":{"en":"Her singing career was all washed up by the time she was 27.","cn":"她到 27 岁时歌唱生涯就告终了。"}}]}},"waft":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)飘荡;吹拂","en":"If sounds or smells waft through the air, or if something such as a light wind wafts them, they move gently through the air.","ex":{"en":"The scent of climbing roses wafts through the window","cn":"藤本月季的芳香飘进了窗户。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a smell, smoke, or a light wind wafts somewhere, or if something wafts it somewhere, it moves gently through the air (","cn":"使)〔在空气中〕飘荡﹔〔风〕吹拂"},{"en":"if sounds waft somewhere, you hear them there and they are pleasant but not very loud 〔","cn":"声音〕飘荡﹐传送"}]},"vocab":{"pos":"n v","senses":[{"en":"When your grandmother cooks her famous spaghetti sauce, many wonderful smells may waft from the kitchen. In other words, the air will gently carry this familiar aroma throughout the house."}]},"collocations":{"phrases":["ADV. gently The night air wafted gently over them. | around, in, up A scent of honey wafted up from the hives.","PREP. across, down, from, into, over, through, up Spicy smells wafted through the air."]},"media":{"uk":"media/ldoce/hwd/bre/d/waft_las2_br.mp3","us":"media/ldoce/hwd/ame/a/waft.mp3"},"examples":[{"en":"The sound of their voices wafted across the lake.","cn":"他们的声音飘过湖面传到了另一边。"},{"en":"Delicious smells wafted up from the kitchen.","cn":"香喷喷的味道从厨房飘了出来。"}],"oxford":{"phon":"wɒft","pos":"verb","senses":[{"en":"to move, or make something move, gently through the air","cn":"（随风）飘荡；使飘荡；吹拂","ex":{"en":"The sound of their voices wafted across the lake.","cn":"他们的声音飘过湖面传到了另一边。"}},{"en":"a smell or a line of smoke carried through the air","cn":"一阵，一股（在空气中飘荡的味或烟）","ex":{"en":"wafts of perfume/smoke","cn":"阵阵香气；缕缕青烟"},"pos":"noun"}]}},"wanker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"笨蛋；卑鄙之人;卑微之人","en":"If someone calls a man a wanker, they do not like him and they think he is very stupid or unpleasant."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very offensive word for a boy or man who you think is stupid or unpleasant. Do not use this word.","cn":"笨蛋﹔讨厌的人〔指男性〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41wanker.mp3","us":"media/ldoce/hwd/ame/0/ld41wanker.mp3"},"examples":[{"en":"a bunch of wankers","cn":"一群下流坯子"}],"oxford":{"phon":"ˈwæŋkə(r)","pos":"noun","senses":[{"en":"an offensive word used to refer to a man that you dislike or are angry with","cn":"孬种，下流坯（用以侮辱男性）","ex":{"en":"a bunch of wankers","cn":"一群下流坯"}}]}},"warhorse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(活跃的)老兵，老政客","en":"You can refer to someone such as an old soldier or politician who is still active and aggressive as a warhorse ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soldier or politician who has been in their job a long time, and enjoys dealing with all the difficulties involved in it","cn":"沙场老将〔指资历深﹑喜欢挑战的军人或政治家〕"},{"en":"a horse used in battle","cn":"军马﹐战马"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41warhorse.mp3","us":"media/ldoce/hwd/ame/7/warhorse.mp3"},"oxford":{"phon":"ˈwɔːhɔːs","pos":"noun","senses":[{"en":"(in the past) a large horse used in battle","cn":"（旧时）军马，战马"},{"en":"an old soldier or politician who has a lot of experience","cn":"久经沙场的老兵；老练的政治家","lab":"informal"}]}},"wasp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盎格鲁—撒克逊族裔的白人新教徒（指社会上拥有强大权力和影响力的白人）","en":"WASP is used to refer to the people in American society whose ancestors came from northern Europe, especially England, and who are considered to have a lot of power and influence. WASP is an abbreviation for (缩略=) 'White Anglo-Saxon Protestant'.","ex":{"en":"...a WASP with a Yale degree.","cn":"一位从耶鲁毕业的权势人物"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin black and yellow flying insect that can sting you","cn":"胡峰﹐黄蜂"}]},"collocations":{"phrases":["WASP + VERB fly, crawl | sting sb | buzz","WASP + NOUN sting","PHRASES a wasp's nest"]},"media":{"uk":"media/ldoce/hwd/bre/b/wasp0205.mp3","us":"media/ldoce/hwd/ame/8/wasp1.mp3","img":["media/thumb/wasp.jpg"]},"examples":[{"en":"a privileged Wasp background","cn":"享有特权的盎格鲁 – 撒克逊裔白人新教徒出身"}],"oxford":{"phon":"wɒsp","pos":"noun","senses":[{"en":"a black and yellow flying insect that can sting","cn":"黄蜂；胡蜂","ex":{"en":"a wasp sting","cn":"黄蜂蜇伤"}},{"en":"a white American whose family originally came from northern Europe and is therefore thought to be from the most powerful section of society (the abbreviation for ‘White Anglo-Saxon Protestant’)","cn":"白种盎格鲁–撒克逊新教徒（祖先来自北欧，被认为是美国社会中势力最强大的白人，全写为 White Anglo-Saxon Protestant）","ex":{"en":"a privileged Wasp background","cn":"享有特权的盎格鲁–撒克逊裔白人新教徒出身"}}]}},"wallet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钱包;皮夹","en":"A wallet is a small flat folded case, usually made of leather or plastic, in which you can keep banknotes and credit cards."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small flat case, often made of leather, that you carry in your pocket, for holding paper money, bank cards etc 〔","cn":"装钞票等的〕钱包﹐皮夹子"},{"en":"a case for documents, often made of leather or plastic 〔","cn":"装文件的〕皮夹﹐塑料夹"}]},"collocations":{"phrases":["ADJ. bulging, fat, stuffed He pulled a &pound; 10 note out of his fat wallet. a wallet stuffed with fifty-pound notes","VERB + WALLET get out, pull out, take out | put away","PREP. in a/the ~ He carried a photo of his children in his wallet."]},"media":{"uk":"media/ldoce/hwd/bre/5/wallet0205.mp3","us":"media/ldoce/hwd/ame/8/wallet.mp3","img":["media/thumb/wallet.jpg"]},"examples":[{"en":"a document wallet","cn":"文件夹"},{"en":"I’ve only got about £10 in my wallet.","cn":"我的钱包里只有大概十英镑。"}],"oxford":{"phon":"ˈwɒlɪt","pos":"noun","senses":[{"en":"a small, flat, folding case made of leather or plastic used for keeping paper money and credit cards in","cn":"（放钞票、信用卡的）钱包，皮夹子","lab":"North American English also","ex":{"en":"He carried a photo of his children in his wallet.","cn":"他在钱包里夹着孩子们的照片。"}},{"en":"a flat case made of leather, plastic or card for carrying documents in","cn":"（携带文件用的）皮夹，塑料夹，硬纸夹","lab":"British English","ex":{"en":"a document wallet","cn":"文件夹"}}]}},"washout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"彻底失败;大败","en":"If an event or plan is a washout, it fails completely.","ex":{"en":"The mission was a washout.","cn":"这个任务彻底失败了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is not successful","cn":""},{"en":"something that is not successful because people do not like it – used especially about a film, play, product, or performance","cn":""},{"en":"used when saying that something is extremely unsuccessful","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/washout0205.mp3","us":"media/ldoce/hwd/ame/c/washout.mp3"},"examples":[{"en":"The picnic was a total washout – nobody turned up!","cn":"野餐彻底失败——根本没人来！"}],"oxford":{"phon":"ˈwɒʃaʊt","pos":"noun","senses":[{"en":"an event, etc. that is a complete failure, especially because of rain","cn":"因雨取消的事；彻底失败的事情","ex":{"en":"They feared that the wedding was going to be a washout after torrential rain.","cn":"他们担心倾盆大雨过后这次婚礼将会取消。"}}]}},"wastrel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"二流子;败家子","en":"If you describe someone as a wastrel you mean that they are lazy and spend their time and money on foolish things.","ex":{"en":"Her father wouldn't let her marry a wastrel.","cn":"她的父亲不会让她嫁给一个败家子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a lazy person who does not try to achieve anything in life","cn":"浪荡子﹐不务正业的人"}]},"vocab":{"pos":"n","senses":[{"en":"Your brother who spends money as quickly as he gets it, always wearing new clothes and taking friends out for expensive dinners? You might call him a wastrel , meaning he spends his money foolishly."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41wastrel.mp3","us":"media/ldoce/hwd/ame/a/wastrel.mp3"},"oxford":{"phon":"ˈweɪstrəl","pos":"noun","senses":[{"en":"a lazy person who spends their time and/or money in a careless and stupid way","cn":"花花公子；浪荡子"}]}},"wakeful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以入睡的;失眠的;睡眠轻的","en":"Someone who is wakeful finds it difficult to get to sleep and wakes up very often when they should be sleeping.","ex":{"en":"Wakeful babies will often continue to need little sleep as they grow older.","cn":"通常睡眠轻的婴儿长大后仍然只需要较少的睡眠。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not sleeping or unable to sleep","cn":"醒着的﹔不能入睡的"},{"en":"a wakeful period of time is one when you cannot sleep 〔","cn":"时间〕不眠的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41wakeful.mp3","us":"media/ldoce/hwd/ame/1/wakeful.mp3"},"examples":[{"en":"She had spent many wakeful nights worrying about him.","cn":"她度过了许多不眠之夜，为他担心。"},{"en":"He lay wakeful all night.","cn":"他躺在床上彻夜未眠。"}],"oxford":{"phon":"ˈweɪkfl","pos":"adjective","senses":[{"en":"not sleeping; unable to sleep","cn":"失眠的；不能入睡的","ex":{"en":"He lay wakeful all night.","cn":"他躺在床上彻夜未眠。"}},{"en":"spent with little or no sleep","cn":"没怎么睡的；不眠的","ex":{"en":"She had spent many wakeful nights worrying about him.","cn":"她度过了许多不眠之夜，为他担心。"}}]}},"warmer":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something, especially a piece of equipment, that is used to make or keep things warm","cn":"加热器﹔保温器"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld44warmer.mp3","us":"media/ldoce/hwd/ame/1/ld44warmer.mp3"},"examples":[{"en":"a plate warmer","cn":"暖盘器"}],"oxford":{"phon":"ˈwɔːmə(r)","pos":"noun","senses":[{"en":"a piece of clothing, a device, etc. that warms somebody/something","cn":"保温衣；保温器；加热器","ex":{"en":"a plate warmer","cn":"暖盘器"}}]}}});
